@unittest.skipIf(os.name == "nt" or os.geteuid() == 0,
                 "a mode this account cannot list needs POSIX and a user not root")
class TestADataFolderThatCannotBeListedIsNotAnEmptyOne(StatusCase):
    """``data/`` this account may not list is refused by name, never read as empty.

    Measured before on the demo season, with ``chmod 000 data`` after a good build:
    exit 1, "No scorecards were read from data", and the front page saying "no
    scorecards were found" -- the one thing that was not true, since the cards were
    all there. Python's ``rglob`` skips a directory it may not list without raising
    (3.11 and 3.12 alike), so the reader's own ``except OSError`` never ran, and a
    scheduled run skipped the same "empty" folder until the mode changed. Now the
    folder is opened once before it is walked, and the refusal is main's: exit 2,
    the errno on one ``error:`` line, "a file or folder it needed could not be
    opened" on the page, and the figures left as they were.

    Rejected: letting the reader's refusal through as a rejected card. Tried, it
    said "pages seen 1, refused 1" and "the one scorecard it found could not be
    scored" -- a folder counted as a card.
    """

    def test_a_folder_with_no_permissions(self):
        before = self.snapshot()
        data = self.cwd / "data"
        data.chmod(0)
        self.addCleanup(data.chmod, 0o755)
        run = self.build(expect=2)
        self.assertIn("error: [Errno 13] Permission denied: 'data'\n", run.err)
        self.assertNotIn("No scorecards were read", run.text)
        self.assertEqual(self.said(),
                         self.failure("a file or folder it needed could not be "
                                      "opened"))
        after = self.snapshot()
        del before[site.STATUS_FILE], after[site.STATUS_FILE]
        self.assertEqual(after, before, "a refused build moved the figures")

    def test_a_folder_it_may_list_and_not_enter_is_refused_as_that_one_is(self):
        # Mode 444: the names can be read and nothing under them reached. Measured
        # once the walk refused a folder (/tmp/t7/scratch/FOLDERS/probe2.py): exit
        # 1, "1 folder(s) not opened" and the root named as a folder under it,
        # where 000 exits 2 with the errno.
        data = self.cwd / "data"
        data.chmod(0o444)
        self.addCleanup(data.chmod, 0o755)
        run = self.build(expect=2)
        self.assertIn("error: [Errno 13] Permission denied: 'data'\n", run.err)
        self.assertEqual(self.said(),
                         self.failure("a file or folder it needed could not be "
                                      "opened"))


@unittest.skipIf(os.name == "nt" or os.geteuid() == 0,
                 "a mode this account cannot list needs POSIX and a user not root")
class TestACardFolderThatCannotBeListedIsRefusedAsAFolderAndNotACard(StatusCase):
    """A folder under ``data/`` the walk could not list is refused, and said as one.

    Measured before on the demo season (``/tmp/t7/scratch/FOLDERS/probe.py``),
    rebuilt after ``chmod 000 data/demo-season/round-05``: exit 0, nothing on
    stderr, ``pages seen 12, scored 12, refused 0`` and ``exit 0: all 12 card(s)
    scored, no errors``, with three cards gone from the dashboard and the front
    page. With every card behind such a folder the run said ``pages seen 0``,
    told the club to export a match from Match Centre, and recorded "no
    scorecards were found". Now the folder is refused by name under ``refused``,
    beside the cards, with the errno, and the run exits 1 as for any refusal; but
    it is counted as a folder everywhere a card is counted, because how many
    cards it holds is exactly what nobody knows. Rejected: a section and an exit
    status of its own, which every reader of the refused list would have to
    learn, and a status that stopped the run would withhold every other season's
    results over one folder.
    """

    def shut(self, *names: str) -> None:
        for name in names:
            folder = self.cwd / "data" / name
            folder.chmod(0)
            self.addCleanup(folder.chmod, 0o755)

    def cut(self) -> None:
        """A card in ``Round1`` cut short, which the reader refuses as a card."""
        first = sorted((self.cwd / "data" / "Round1").glob("*.pdf"))[0]
        (self.cwd / "data" / "Round1" / "cut.pdf").write_bytes(
            first.read_bytes()[:1024])

    def test_the_report_names_the_folder_and_counts_no_card_for_it(self):
        self.shut("Round3")
        run = self.build(expect=1)
        self.assertEqual(run.err, "")
        self.assertIn("  pages seen   4\n  scored       4\n  refused      0\n"
                      "  not opened   1 folder(s)\n", self.section(run.out, "cards"))
        refused = self.section(run.out, "refused").splitlines()
        self.assertTrue(refused[0].startswith("== refused: 1 folder(s) not opened ="),
                        refused[0])
        self.assertEqual(len(refused[0]), 78)
        self.assertEqual(refused[1:4],
                         ["  data/Round3",
                          "      the directory could not be listed",
                          "      Permission denied"])
        # The doctor reads a file's pages, and a folder has none.
        self.assertNotIn("doctor", "\n".join(refused))
        self.assertNotIn("found and not scored", run.out)
        self.assertEqual(self.section(run.out, "result").splitlines()[-1],
                         "  exit 1: 1 folder(s) not opened")
        self.assertLessEqual(max(map(len, run.out.splitlines())), 78)

    def test_a_folder_named_like_a_card_is_not_offered_the_doctor(self):
        # Measured (/tmp/t7/scratch/FOLDERS/pdfdir): the demo's round-05 renamed
        # round-05.pdf and shut was offered `python3 tools/doctor.py
        # data/demo-season/round-05.pdf`, and the doctor answers that a folder is
        # not a file. Named to sort before the card cut beside it, which is the one
        # the doctor is offered on.
        (self.cwd / "data" / "Round3").rename(self.cwd / "data" / "Early.pdf")
        self.shut("Early.pdf")
        alone = self.section(self.build(expect=1).out, "refused")
        self.assertIn("  data/Early.pdf\n      the directory could not be listed\n",
                      alone)
        self.assertNotIn("doctor", alone)
        self.cut()
        beside = self.section(self.build(expect=1).out, "refused")
        doctor = beside[beside.index("Point the doctor"):]
        self.assertIn("cut.pdf", doctor)
        self.assertNotIn("Early.pdf", doctor)
        # Not "any one of them", over a list one of which it is not for.
        self.assertTrue(doctor.startswith("Point the doctor at any file among them "),
                        doctor)

    def problems(self, run) -> str:
        """The competition's own ``problems`` sentence, its wrapping undone."""
        section = self.section(run.out, self.COMP)
        return " ".join(section[section.index("  problems"):].split("\n\n")[0].split())

    def test_the_competitions_problems_line_counts_it_as_a_folder(self):
        self.shut("Round3")
        said = self.problems(self.build(expect=1))
        self.assertTrue(said.endswith(" and the run's 1 folder(s) not opened"), said)
        self.assertNotIn("card", said)

    def test_the_readme_quotes_what_it_prints(self):
        self.shut("Round3")
        run = self.build(expect=1)
        self.assertEqual(
            readme_block(self, "### A folder under data/ was not opened"),
            self.section(run.out, "refused").splitlines()[:4])

    def test_quiet_still_says_it(self):
        self.shut("Round3")
        run = self.build("--quiet", expect=1)
        self.assertIn("  not opened   1 folder(s)\n", run.out)
        self.assertIn("  data/Round3\n", run.out)

    def test_the_documents_and_the_front_page_count_it_apart_from_the_cards(self):
        self.shut("Round3")
        self.build(expect=1)
        season = self.season()
        self.assertEqual({key: season["meta"][key] for key in
                          ("cards_seen", "cards_scored", "cards_rejected",
                           "folders_unlisted")},
                         {"cards_seen": 4, "cards_scored": 4, "cards_rejected": 0,
                          "folders_unlisted": 1})
        self.assertEqual(season["validation"]["rejected"],
                         [{"path": "data/Round3",
                           "reason": "the directory could not be listed",
                           "detail": "Permission denied",
                           "page": 0, "folder": True}])
        self.assertFalse(season["validation"]["ok"])
        front = (self.cwd / "site" / "index.html").read_text(encoding="utf-8")
        self.assertIn(">1 folder could not be opened<", front)
        self.assertNotIn("could not be read<", front)

    def test_a_card_refused_beside_it_is_counted_as_a_card(self):
        self.cut()
        self.shut("Round3")
        run = self.build(expect=1)
        self.assertIn("  pages seen   5\n  scored       4\n  refused      1\n"
                      "  not opened   1 folder(s)\n", self.section(run.out, "cards"))
        self.assertTrue(self.section(run.out, "refused").startswith(
            "== refused: 1 card(s) found and not scored and 1 folder(s) not opened "
            "=="))
        self.assertEqual(self.section(run.out, "result").splitlines()[-1],
                         "  exit 1: 1 card(s) found and not scored and 1 folder(s) "
                         "not opened")
        self.assertTrue(self.problems(run).endswith(
            " and the run's 1 refused card(s) and 1 folder(s) not opened"),
            self.problems(run))
        self.assertEqual(self.season()["meta"]["cards_rejected"], 1)
        # In the report's order, which is the order the page lists them in.
        self.assertEqual([r["path"] for r in self.season()["validation"]["rejected"]],
                         ["data/Round1/cut.pdf", "data/Round3"])
        front = (self.cwd / "site" / "index.html").read_text(encoding="utf-8")
        self.assertIn(">1 card could not be read<", front)
        self.assertIn(">1 folder could not be opened<", front)

    def test_a_config_it_could_not_write_beside_them_is_the_last_of_one_list(self):
        # Two clauses of the run's and one thing it did not finish are one list in
        # the last line. Measured with the run's two listed apart and then joined
        # to the third (/tmp/t7/scratch/LISTS-B/fixup/me.txt): "1 card(s) found and
        # not scored and 1 folder(s) not opened and notes.txt/config.toml not
        # written".
        self.cut()
        self.shut("Round3")
        (self.cwd / "notes.txt").write_text("not a folder\n", encoding="utf-8")
        result = self.wrote(self.build("--config", "notes.txt/config.toml",
                                       expect=1))
        self.assertTrue(result.endswith(
            "exit 1: 1 card(s) found and not scored, 1 folder(s) not opened and "
            "notes.txt/config.toml not written"), result)

    def test_every_card_behind_one_is_nothing_built_and_recorded_as_unopened(self):
        self.shut("Round1", "Round2", "Round3")
        run = self.build(expect=1)
        self.assertIn("  pages seen   0\n", run.out)
        result = self.wrote(run)
        self.assertIn("No scorecards were read from data. 3 folder(s) there could "
                      "not be opened, so no card in them was read. The section "
                      "above names each one and why. Nothing was built, because "
                      "there was nothing readable to build from.", result)
        self.assertNotIn("Export a match", result)
        self.assertTrue(result.endswith("exit 1: 3 folder(s) not opened and nothing "
                                        "built"), result)
        self.assertEqual(self.said(),
                         self.failure("a file or folder it needed could not be "
                                      "opened"))

    def test_a_card_refused_beside_them_is_said_with_them_and_the_folders_first(
            self):
        """Nothing read, a card refused and the rest behind folders: both, once.

        Measured (``/tmp/t7/scratch/FOLDERS/probe2.py``) with every round shut
        and a cut card beside them: the page recorded "the one scorecard it found
        could not be scored", which says nothing of the three folders, and the
        report pointed at the section above twice in one paragraph. Now the
        folders decide the status, since exporting the card again is no help
        while they stay shut, and the pointer is said once, after both counts.
        Rejected: the card deciding, as the count of what was found and refused.
        """
        card = sorted((self.cwd / "data" / "Round1").glob("*.pdf"))[0]
        (self.cwd / "data" / "cut.pdf").write_bytes(card.read_bytes()[:1024])
        self.shut("Round1", "Round2", "Round3")
        result = self.wrote(self.build(expect=1))
        self.assertIn("No scorecards were read from data. 1 card(s) were found "
                      "there and none of them could be read. 3 folder(s) there "
                      "could not be opened, so no card in them was read. The "
                      "section above names each one and why. Nothing was built, "
                      "because there was nothing readable to build from.", result)
        self.assertEqual(result.count("The section above"), 1)
        self.assertTrue(result.endswith("exit 1: 1 card(s) found and not scored, 3 "
                                        "folder(s) not opened and nothing built"),
                        result)
        self.assertEqual(self.said(),
                         self.failure("a file or folder it needed could not be "
                                      "opened"))


class TestAnInternalErrorIsRecordedAndStillRaises(StatusCase):
    """A bug is written on the page and then let go, traceback and all.

    Rejected: catching it to print a sentence instead. The traceback is the one
    thing whoever runs this next needs to report the bug, and an exit status of 1
    from an uncaught exception is what every scheduler already understands.
    """

    def test_a_bug_in_the_scoring(self):
        with mock.patch.object(export_mod, "build_season",
                               side_effect=RuntimeError("a bug")):
            with self.assertRaises(RuntimeError):
                self.in_process()
        self.assertEqual(self.said(), self.failure("an internal error stopped it"))


class TestTheSingleFilePageCarriesNoStatus(StatusCase):
    """The folded page is the one sent to somebody, and it is a copy, not a site.

    A status inside it would be frozen at the moment it was folded and read as
    current by whoever it was sent to.
    """

    def test_the_folded_page(self):
        self.build("--single-file")
        folded = self.cwd / "site" / self.COMP / site.single_file_name(
            self.cwd / "site" / self.COMP)
        text = folded.read_text(encoding="utf-8")
