class TestPruneRemovesOnlyTheDashboardsThisToolWrote(OrphanCase):
    """``--prune``: the way out, and what it refuses to take with it.

    Reporting a stale dashboard is only half an answer, because the other half is
    ``rm -rf`` aimed at a folder inside a club's published site, typed by somebody
    reading a paragraph. So the program does it, and the rule for what it will
    delete is the rule it already documents for what it overwrites: the five files
    it writes into a competition directory are its own, and anything else in there
    belongs to a human. A directory holding one of those is named and left exactly
    where it is, whatever else is true of it.
    """

    def test_it_removes_the_dashboard_nothing_builds_any_more(self):
        stale = self.archive_the_second_competition()
        self.build("--prune")
        self.assertFalse(stale.exists(), f"{stale} survived --prune")

    def test_it_leaves_the_dashboards_this_run_did_build(self):
        live = self.cwd / "site" / self.kept
        self.archive_the_second_competition()
        before = self.contents(live)
        self.build("--prune")
        self.assertEqual(self.contents(live), before)
        self.assertTrue((self.cwd / "site" / "index.html").is_file())

    def test_it_says_what_it_removed_and_how_many_files_went(self):
        self.archive_the_second_competition()
        section = self.sentences(self.build("--prune").out, "pruned")
        self.assertIn(str(Path("site") / self.lost), section)
        self.assertIn("5 file(s)", section)

    def test_a_dashboard_with_a_folded_copy_in_it_still_goes(self):
        """The one-file dashboard is the sixth file this tool writes, so it goes too.

        The name of a folded page is the directory's own, which makes it the one name
        on the list the name alone does not settle: a rule that read it as a
        stranger's would leave every folder a club had ever asked to fold standing
        for ever, and the report's only account of why would be a file name that
        looks exactly like the folder it is in.
        """
        self.build("--single-file")
        stale = self.archive_the_second_competition()
        folded = stale / site.single_file_name(stale)
        self.assertTrue(folded.is_file(), f"the fixture holds no folded page to "
                                         f"prune: {sorted(p.name for p in stale.iterdir())}")
        section = self.sentences(self.build("--prune").out, "pruned")
        self.assertFalse(stale.exists(), f"{stale} survived --prune with a folded "
                                        f"page of this tool's own in it")
        self.assertIn("6 file(s)", section)

    def test_it_refuses_a_directory_holding_a_file_this_tool_did_not_write(self):
        stale = self.archive_the_second_competition()
        before = self.contents(stale)
        (stale / "notes.txt").write_text("last year's ladder\n", encoding="utf-8")
        run = self.build("--prune", expect=1)
        self.assertTrue(stale.is_dir(), f"{stale} was removed with a file of the "
                                       f"club's own in it")
        # And not emptied around the file it was refused for. Deleting what it was
        # allowed to and reporting afterwards would leave a dashboard that still
        # opens and shows a blank page, which is worse than either outcome it was
        # choosing between.
        kept = {name: body for name, body in self.contents(stale).items()
                if name != "notes.txt"}
        self.assertEqual(kept, before, f"{stale} was left standing and emptied")
        self.assertIn("notes.txt", run.out)

    def test_refusing_one_folder_does_not_save_the_others(self):
        stale = self.archive_the_second_competition()
        (stale / "notes.txt").write_text("keep me\n", encoding="utf-8")
        copy = self.cwd / "site" / f"{self.kept}-old"
        shutil.copytree(self.cwd / "site" / self.kept, copy)
        self.build("--prune", expect=1)
        self.assertTrue(stale.is_dir())
        self.assertFalse(copy.exists(), f"{copy} was left because another folder "
                                        f"could not be removed")

    def test_a_prune_that_could_not_finish_is_not_reported_as_a_clean_run(self):
        # Exit 1, like every other thing this program was asked to do and could
        # not: a cron job that prunes each week has no other way to learn that a
        # folder it expected to go is still there.
        stale = self.archive_the_second_competition()
        (stale / "notes.txt").write_text("keep me\n", encoding="utf-8")
        run = self.build("--prune", expect=1)
        self.assertIn("not removed", run.out.split("== result")[-1])

    def test_an_emptied_season_folder_goes_with_the_last_dashboard_in_it(self):
        """``site/<season>/`` is this tool's too, and an empty one is a dead link.

        Multi-season mode nests a competition under its season, so pruning the
        last competition of an archived season leaves a folder with nothing in it
        -- which the front page does not link and a club cannot tell from a season
        whose dashboards failed to write.
        """
        config = self.cwd / "config.toml"
        config.write_text('[build]\nseasons = "multi"\n', encoding="utf-8")
        shutil.move(self.cwd / "data" / "Round1",
                    self.cwd / "data" / "2026-winter")
        self.build()
        season = self.cwd / "site" / "2026-winter"
        self.assertTrue(season.is_dir(), f"the multi-mode build wrote no "
                                        f"{season}: {self.files_in('site')}")
        shutil.rmtree(self.cwd / "data" / "2026-winter")
        self.build("--prune")
        self.assertFalse(season.exists(), f"{season} was left behind empty")

    def test_a_season_folder_still_holding_a_live_dashboard_is_not_touched(self):
        """The other half of the line above, and the one that could lose a season.

        Two competitions in one season folder, one of them archived: the folder is
        emptied of one dashboard and is not empty. A tidy-up that removed the
        parent after removing a child would take the division that is still being
        played with it -- silently, since the run that did it would report the
        prune it meant to do and exit 0.
        """
        (self.cwd / "config.toml").write_text('[build]\nseasons = "multi"\n',
                                              encoding="utf-8")
        season = self.cwd / "data" / "2026-winter"
        season.mkdir()
        for folder in sorted((self.cwd / "data").iterdir()):
            if folder != season:
                shutil.move(folder, season / folder.name)
        self.build()
        built = sorted(p.parent for p in
                       (self.cwd / "site" / "2026-winter").rglob("season.json"))
        self.assertEqual(len(built), 2, f"the fixture built {built}, and this test "
                                       f"needs two competitions in one season")
        shutil.rmtree(season / self.SECOND)
        self.build("--prune")
        live, gone = built[0], built[1]
        self.assertTrue((live / "index.html").is_file(),
                        f"{live} went with the season folder's other dashboard")
        self.assertFalse(gone.exists(), f"{gone} survived --prune")

    def test_it_deletes_nothing_when_the_run_read_no_cards(self):
        """The one combination that could wipe a club's whole site.

        ``--prune`` in a script, a ``data/`` that did not mount, and every
        dashboard on disk is one this run is not writing. Nothing is found in that
        case, so nothing is deleted -- the same rule that keeps the report quiet.
        The one file that moves is the front page's status, to say the build
        failed (4.57).
        """
        before = self.contents(self.cwd / "site")
        shutil.rmtree(self.cwd / "data")
        (self.cwd / "data").mkdir()
        self.build("--prune", expect=1)
        after = self.contents(self.cwd / "site")
        self.assertIn(b'"level": "fail"', after.pop(site.STATUS_FILE))
        del before[site.STATUS_FILE]
        self.assertEqual(after, before)

    def test_prune_and_check_together_are_refused_rather_than_half_honoured(self):
        # `--check` promises that nothing at all is written, and a delete is the
        # loudest possible way to break that promise. Refused during the parse, the
        # way `--force` without `--discover` is.
        run = self.build("--check", "--prune", expect=2)
        self.assertIn("--prune", run.err)
        self.assertIn("--check", run.err)


# --- --only: one season in the report, every season read, checked and written --


ONLY_CONFIG = ('[build]\nseasons = "multi"\n\n[seasons]\n'
               '"2026-winter" = "2026 Winter Season"\n'
               '"2025-winter" = "2025 Winter Season"\n')

# What `--only 2026-wintr` prints on stderr against the three seasons below, word
# for word. Written down once, because the README quotes it and the test that says
# the README is right should be comparing against the same text as the test that
# says the program prints it.
ONLY_REFUSAL = """\
error: --only 2026-wintr: not a season this run found
  The seasons this run found, newest first:
    2026-winter    2026 Winter Season
    2026-summer    Season 1
    2025-winter    2025 Winter Season
  Capitals and spaces in a name do not matter. Nothing was written."""


def write_three_seasons(project: Path) -> None:
    """Three seasons under ``project/data``, and the config that makes them three.

    This file's own season in ``2026-winter``, dated August to September, and two
    demo divisions beside it: ``2026-summer`` and ``2025-winter``, both played on a
    Tuesday. The night is chosen and the seed is not, because demo dates follow the
    night -- measured in /tmp/t4/scratch/y88/m10, a Wednesday demo is dated a day
    after a Tuesday one whatever ``--seed`` says -- and two seasons whose last cards
    fall on one day are what the stale-scope sentence has to be seen not to call
    "later". No ``[competitions]`` section, so every season has values in the review
    list, and a label for two of the three seasons, so the refusal's list shows both
    kinds of row.
    """
    data = project / "data"
    write_season_cards(data)
    (data / "2026-winter").mkdir()
    for folder in sorted(data.glob("Round*")):
        folder.rename(data / "2026-winter" / folder.name)
    for season, division, seed in (("2026-summer", "2", ()),
                                   ("2025-winter", "3", ("--seed", "7"))):
        done = subprocess.run(
            (sys.executable, str(ROOT / "tools" / "demo.py"), "--day", "Tuesday",
             "--division", division, "--teams", "4", *seed,
             "--out", str(data / season)),
            capture_output=True, text=True, timeout=600)
        if done.returncode != 0:
            raise AssertionError(f"tools/demo.py failed:\n{done.stdout}{done.stderr}")
    (project / "config.toml").write_text(ONLY_CONFIG, encoding="utf-8")


class TestACheckRunSaysABuildWouldLeaveNothingLinkingADashboardLeftBehind(OrphanCase):
    """``--check`` said nothing linked a dashboard its front page still linked.

    Measured before (/tmp/t6/scratch/m6/before.txt, as
    /tmp/t4/scratch/z462/fixup/probe_check.after.txt found): a run with
    ``--check`` over a competition whose cards had gone listed it under left
    behind and said "Nothing under site links them any more", and
    site/index.html, which ``--check`` does not rewrite, still linked it. The
    plain run's sentence was true, because that run had just rewritten the page.

    So the sentence is in the tense of the run: a run that wrote says what the
    front page it wrote does, and ``--check`` says what a build would leave.
    Rejected: dropping the sentence under ``--check``, which is the half of the
    paragraph that says why a folder nobody links still matters.
    """

    WOULD = ("A build would leave nothing under site linking them, so nobody will "
             "find one by accident")
    DONE = "Nothing under site links them any more, so nobody will find one"

    def front(self) -> str:
        return (self.cwd / "site" / "index.html").read_text(encoding="utf-8")

    def test_check_says_what_a_build_would_leave(self):
        self.archive_the_second_competition()
        run = self.build("--check")
        self.assertIn(self.lost, self.front(),
                      "the front page does not link it, so the fixture cannot "
                      "tell the two sentences apart")
        text = self.sentences(run.out, "left behind")
        self.assertIn(self.WOULD, text)
        self.assertNotIn("links them any more", text)

    def test_a_build_says_what_the_front_page_it_wrote_does(self):
        self.archive_the_second_competition()
        run = self.build()
        self.assertNotIn(self.lost, self.front())
        self.assertIn(self.DONE, self.sentences(run.out, "left behind"))


class TestACheckSaysWhereABuildWritesTheCompetitionOfASecondCopy(OrphanCase):
    """``--check`` said a competition "is written to" a path nothing was at.

    Measured before (/tmp/t7/scratch/SITE-A/p175-before.txt), on the default
    demo with its dashboard renamed by hand to site/wednesday-3-old:
    ``--check`` exited 0 and gave that folder the reason "a second copy: this
    competition is written to site/wednesday-division-3 now", while
    site/wednesday-division-3 did not exist, and the lead under it already
    said "A build would leave nothing under site linking them". The plain
    run's reason was true, because that run had just written the path.

    So the reason is in the tense of the run, asked of the same ``wrote`` that
    4.130's leads take: a build says where it wrote the competition, and
    ``--check`` says where a build writes it. Rejected: dropping the reason
    under ``--check``, which is the one line that tells a copy apart from a
    competition whose cards have gone, and those two want opposite things
    done.
    """

    def renamed(self) -> Path:
        """The live dashboard renamed by hand, and the path its name was."""
        (self.cwd / "site" / self.kept).rename(
            self.cwd / "site" / f"{self.kept}-old")
        return Path("site") / self.kept

    def test_check_says_where_a_build_writes_a_dashboard_renamed_by_hand(self):
        live = self.renamed()
        text = self.sentences(self.build("--check").out, "left behind")
        self.assertFalse((self.cwd / live).exists(),
                         "--check wrote the path, so the fixture cannot tell "
                         "the two tenses apart")
        self.assertIn(f"{self.kept}-old", text)
        self.assertIn(f"a second copy: a build writes this competition to "
                      f"{live}", text)
        self.assertNotIn("is written to", text)

    def test_a_build_says_where_it_wrote_the_competition_now(self):
        live = self.renamed()
        text = self.sentences(self.build().out, "left behind")
        self.assertTrue((self.cwd / live / "season.json").is_file())
        self.assertIn(f"a second copy: this competition is written to "
                      f"{live} now", text)
        self.assertNotIn("a build writes", text)


class TestAPruneKeepsADashboardLeftBehindThatHoldsALink(OrphanCase):
    """What a build refuses to write through, ``--prune`` does not delete.

    Measured before (/tmp/t7/scratch/SITE-A/p63-before.txt): a dashboard left
    behind whose ``season.json`` was a link to a file elsewhere was listed,
    and ``--prune`` exited 0 saying "removed 5 file(s)", the link among them.
    A link is something the club made, and the build now refuses one at that
    name, so the rule ``_stranger_names`` keeps for both -- a prune looser
    than the build deletes what the build would not touch -- keeps the
    folder, link and all. Rejected: removing the folder and the link and
    leaving the file at its end, which is the deletion of the club's link this
    refusal exists to avoid.

    And the link is named as the build names it, by the build's split,
    ``_links_and_others``. As first written the prune said "kept: holds
    file(s) this tool did not write: season.json" of the link the build calls
    a link (/tmp/t7/scratch/SITE-A/p63b-impl.txt), which reads as the tool's
    own file, as by its name it is. The build's advice is left off, because
    the summary under the list gives a prune's.
    """

    def linked(self, stale: Path) -> bytes:
        """The copy's ``season.json`` made a link to a file outside --out."""
        outside = self.cwd / "outside-season.json"
        held = (stale / "season.json").read_bytes()
        outside.write_bytes(held)
        (stale / "season.json").unlink()
        (stale / "season.json").symlink_to(outside)
        return held

    def test_the_dashboard_and_its_link_are_kept_and_the_link_is_named(self):
        stale = self.archive_the_second_competition()
        held = self.linked(stale)
        run = self.build("--prune", expect=1)
        self.assertTrue((stale / "season.json").is_symlink())
        self.assertTrue((stale / "season-data.js").is_file())
        self.assertEqual((self.cwd / "outside-season.json").read_bytes(), held)
        text = self.sentences(run.out, "pruned")
        self.assertIn(f"kept: site/{self.lost}/season.json is a link, and the "
                      f"dashboard needs that name for a file of its own", text)
        self.assertNotIn("this tool did not write: season.json", text)
        self.assertNotIn("different --out directory", text)

    def test_a_page_of_the_clubs_beside_it_is_a_file_it_did_not_write(self):
        """The split is the build's: a file at the one-file name is no link.

        The copy's one-file name is one of its own, and the club's page there
        is not a page this tool wrote, so it is listed with the files this
        tool did not write, first, and the link after it.
        """
        stale = self.archive_the_second_competition()
        self.linked(stale)
        page = stale / f"{self.lost}.html"
        page.write_text("<p>our own page</p>\n", encoding="utf-8")
        run = self.build("--prune", expect=1)
        self.assertEqual(page.read_text(encoding="utf-8"),
                         "<p>our own page</p>\n")
        self.assertIn(f"kept: holds file(s) this tool did not write: "
                      f"{self.lost}.html; site/{self.lost}/season.json is a "
                      f"link, and the dashboard needs that name for a file of "
                      f"its own", self.sentences(run.out, "pruned"))


@unittest.skipIf(os.name == "nt" or os.geteuid() == 0,
                 "a mode this account cannot list needs POSIX and a user not root")
class TestADashboardWhoseCardsCouldNotBeListedIsNeitherLeftBehindNorPruned(OrphanCase):
    """A competition whose folder was not opened is not a competition gone.

    Measured (``/tmp/t7/scratch/FOLDERS/probe.py``, two demo divisions with the
    Tuesday one's folder at mode 000): before, ``--prune`` exited 0 and deleted
    ``site/tuesday-division-2``, listed under ``pruned``; once the reader refused
    the folder, the same run exited 1 naming ``data/tuesday`` and still deleted
    it. A run that could not open a folder of cards lists nothing under ``--out``
    as left behind, as a run that read no cards does not: the dashboard it did not
    write may be the one those cards build. Rejected: listing it and refusing to
    prune it, which is advice to type a command that would not do what it says.
    """

    def shut(self) -> Path:
        folder = self.cwd / "data" / self.SECOND
        folder.chmod(0)
        self.addCleanup(folder.chmod, 0o755)
        return self.cwd / "site" / self.lost

    def test_prune_removes_nothing(self):
        stale = self.shut()
        before = self.contents(stale)
        run = self.build("--prune", expect=1)
        self.assertEqual(self.contents(stale), before)
        self.assertNotIn("== pruned", run.out)
        self.assertIn(f"  data/{self.SECOND}\n      the directory could not be "
                      f"listed\n", run.out)

    def test_nothing_is_listed_as_left_behind(self):
        self.shut()
        run = self.build(expect=1)
        self.assertNotIn("== left behind", run.out)
        self.assertNotIn(f"site/{self.lost}", run.out)


class TestATemporaryFileAStoppedBuildLeftIsNeitherAStrangerNorKept(OrphanCase):
    """A dot-named temporary a stopped build left is the build's own.

    Each file is written to ``.<name>.tmp`` beside it and renamed over it, and
    the temporary is removed when the write fails; a run killed between the
    two, or a machine that went down, can still leave one. It is a dotfile,
    which the stranger check has always passed over, so it neither stops the
    next build nor keeps a dashboard left behind from ``--prune``; and the name
    is one per file, so the next write of that file clears it rather than
    leaving a second, and only it: a dotfile of the club's is not the build's.
    A link at the name is removed, not written through, so a file it points at
    outside site/ keeps its bytes and season.json is a file. Rejected: a fresh
    name for each write, which a run killed every night would leave one more of
    each time; and sweeping ``.*.tmp`` on each build, which deletes a club's
    file by its pattern.
    """

    LEFT = ".season.json.tmp"
    HALF = b'{"meta": {"generated": "2026-09-0'

    def rewrite_the_live_one(self) -> None:
        """A card of the live competition taken away, so its season.json is
        written again."""
        next(p for p in sorted((self.cwd / "data").rglob("*.pdf"))
             if self.SECOND not in p.parts).unlink()

    def test_the_next_build_is_not_refused_and_clears_it(self):
        (self.cwd / "site" / self.kept / self.LEFT).write_bytes(self.HALF)
        (self.cwd / "site" / self.kept / ".notes.tmp").write_bytes(b"the club's\n")
        self.rewrite_the_live_one()
        self.build()
        self.assertEqual(sorted(p.name for p in (self.cwd / "site").rglob(".*")),
                         [".notes.tmp"])

    def test_a_link_at_its_name_is_removed_and_never_written_through(self):
        precious = self.cwd / "precious.txt"
        precious.write_bytes(b"the club's\n")
        (self.cwd / "site" / self.kept / self.LEFT).symlink_to(precious)
        self.rewrite_the_live_one()
        self.build()
        document = self.cwd / "site" / self.kept / "season.json"
        self.assertEqual(precious.read_bytes(), b"the club's\n")
        self.assertFalse(document.is_symlink(), "season.json is the link it was "
                                                "renamed from")
        self.assertFalse(os.path.lexists(document.with_name(self.LEFT)))

    def test_prune_removes_a_dashboard_left_behind_with_one(self):
        stale = self.archive_the_second_competition()
        (stale / self.LEFT).write_bytes(self.HALF)
        self.build("--prune")
        self.assertFalse(stale.exists(), f"{stale} survived --prune")


class OnlyCase(CliCase):
    """Three seasons, made once for the class and copied fresh for each test.

    Copied rather than rebuilt, because most of what is tested here is two runs
    that started from the same state -- one with ``--only`` and one without -- and
    "the same state" has to mean the same bytes, not the same instructions.
    """

    WINTER, SUMMER, ARCHIVE = "2026-winter", "2026-summer", "2025-winter"

    @classmethod
    def setUpClass(cls):
        cls._shared = tempfile.TemporaryDirectory()
        cls.pristine = Path(cls._shared.name) / "start"
        write_three_seasons(cls.pristine)

    @classmethod
    def tearDownClass(cls):
        cls._shared.cleanup()

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.cwd = self.copy("project")

    def copy(self, name: str) -> Path:
        where = Path(self._tmp.name) / name
        shutil.copytree(self.pristine, where)
        return where

    def build_in(self, where: Path, *argv: str, expect: int | None = 0) -> Run:
        done = subprocess.run(
            (sys.executable, str(BUILD), "--generated", STAMP, *argv),
            cwd=where, capture_output=True, text=True, timeout=600)
        run = Run(done.returncode, done.stdout, done.stderr, where)
        if expect is not None and run.code != expect:
            self.fail(f"build.py {' '.join(argv)} in {where.name} exited {run.code}, "
                      f"expected {expect}:\n{run.text[-3000:]}")
        return run

    @staticmethod
    def tree(where: Path, directory: str = "site") -> dict[str, bytes]:
        base = where / directory
        return {p.relative_to(base).as_posix(): p.read_bytes()
                for p in sorted(base.rglob("*")) if p.is_file()}

    @staticmethod
    def flat(text: str) -> str:
        return " ".join(text.split())

    @staticmethod
    def headings(text: str) -> list[str]:
        return [line[3:].rstrip("= ") for line in text.splitlines()
                if line.startswith("== ")]

    def warnings(self, text: str) -> str:
        """The warnings section, whose heading starts with its count."""
        heading = next((h for h in self.headings(text)
                        if re.fullmatch(r"\d+ warnings?", h)), None)
        self.assertIsNotNone(heading, f"the report has no warnings:\n{text[:2500]}")
        return self.section(text, heading)

    def counted(self, text: str, pattern: str) -> int:
        """The number a heading starts with, for the heading *pattern* matches."""
        found = [re.match(pattern, h) for h in self.headings(text)]
        found = [m for m in found if m]
        self.assertEqual(len(found), 1, self.headings(text))
        return int(found[0].group(1))

    def cards_of(self, where: Path, season: str) -> list[Path]:
        return sorted((where / "data" / season).rglob("*.pdf"))

    def comp(self, season: str) -> str:
        """The one competition id this fixture files under *season*."""
        return {self.WINTER: "2026-winter-tuesday-division-b",
                self.SUMMER: "2026-summer-tuesday-division-2",
                self.ARCHIVE: "2025-winter-tuesday-division-3"}[season]

    def break_two_seasons(self, where: Path) -> None:
        """A half-downloaded card in 2025-winter and two cards that disagree in
        2026-winter: a refused card and a validation error, in two seasons that
        ``--only 2026-summer`` does not list.

        Two cards that disagree, not the same card twice, because a copy is only a
        warning; the second one is written the way the two-season README test writes
        its archived card, for a fixture this season has already carded.
        """
        (where / "data" / self.ARCHIVE / "half.pdf").write_bytes(b"%PDF-1.4\n1 0 obj\n<<")
        home, away = "riverside-rockets", "hilltop-aces"
        home_name, home_players = TEAMS[home]
        away_name, away_players = TEAMS[away]
        home_rows, home_on_court = squad_for(home, home_players, None)
        away_rows, away_on_court = squad_for(away, away_players, None)
        cardwriter.write_card_file(
            where / "data" / self.WINTER / "Round1" / "again.pdf",
            cardwriter.CardSpec(
                date=DATES["1"], round_label="1", division="B", court="21",
                match_id="29990001", home_name=home_name, away_name=away_name,
                rows=rows_for(((6, 4), (4, 6), (6, 4), (4, 6)),
                              home_on_court, away_on_court),
                home_roster=home_rows, away_roster=away_rows))

    def swap(self, where: Path, one: str, other: str) -> None:
        data = where / "data"
        (data / one).rename(data / "swapping")
        (data / other).rename(data / one)
        (data / "swapping").rename(data / other)


class TestAScopeHidesOnlyWhatItCanPlace(unittest.TestCase):
    """The two rules ``--only`` narrows by, each one function, each failing the way
    it was chosen to.

    ``hides`` is what the report leaves out, and it fails open: a document or a
    note that names no season is listed, because a report that shows too much
    costs a club a scroll. ``covers`` is where ``--single-file`` may add a one-file
    page, and it fails closed: a fold is sticky, so a page nobody asked for is
    permanent. One predicate for both was the alternative, and whichever way it is
    written it gets one of the two directions wrong.
    """

    def test_every_season_hides_nothing_and_covers_everything(self):
        from matchcentre.scope import EVERY_SEASON, Scope
        for scope in (EVERY_SEASON, Scope()):
            self.assertFalse(scope.narrowed)
            for key in ("2026-winter", "", None):
                with self.subTest(key=key):
                    self.assertFalse(scope.hides(key))
                    self.assertTrue(scope.covers(key))

    def test_a_narrowed_scope_hides_only_a_season_it_can_name(self):
        from matchcentre.scope import Scope
        scope = Scope(("a",))
        self.assertTrue(scope.narrowed)
        self.assertIs(scope.hides("b"), True)
        for key in ("a", "", None):
            with self.subTest(key=key):
                self.assertIs(scope.hides(key), False)

    def test_a_narrowed_scope_adds_pages_only_to_a_season_it_can_name(self):
        from matchcentre.scope import Scope
        scope = Scope(("a",))
        self.assertIs(scope.covers("a"), True)
        for key in ("b", "", None):
            with self.subTest(key=key):
                self.assertIs(scope.covers(key), False)

    def test_it_names_its_seasons_the_way_a_sentence_does(self):
        from matchcentre.scope import Scope, in_words
        self.assertEqual(Scope(("a",)).words(), "a")
        self.assertEqual(Scope(("a", "b")).words(), "a and b")
        self.assertEqual(Scope(("c", "a", "b")).words(), "c, a and b")
        self.assertEqual(in_words([]), "")

    def test_a_document_that_names_no_season_is_listed(self):
        # The report filters by `hides`, not by `not covers`: a document with no
        # season key is listed under any --only, because nothing places it elsewhere.
        from matchcentre.scope import Scope
        docs = [{"meta": {"season_key": key}} for key in ("a", "b", "")] + [{"meta": {}}]
        scope = Scope(("a",))
        self.assertEqual(build_mod._listed(docs, scope), [docs[0], docs[2], docs[3]])
        self.assertEqual(build_mod._listed(docs, scope, hidden=True), [docs[1]])


class TestAListInASentenceIsJoinedByOneRule(unittest.TestCase):
    """``a``, ``a and b``, ``a, b and c``, and the same with ``or``, from one function.

    The ``a, b and c`` rule was written five times: ``slugs.listed`` and
    ``scope.in_words``, two whole copies both called from build.py;
    ``scorecard._listed``, which took ``or`` as well and raised IndexError on an
    empty list, so that only its callers' guards kept a refusal's wording from
    stopping the build; and two inline joins, the years in
    ``validate._across_years`` and ``card.date_forms``'s ``or``. Measured on the
    unfixed tree, the three functions gave the same text for one to four items, and
    ``''`` from the first two for none. So :func:`~matchcentre.scope.in_words` takes
    the conjunction, none is its case, each of those copies calls it, and
    discovery's note on a round played in two years names its rounds by
    :func:`~matchcentre.sheet.rounds_listed`, as the checks do. The demo's reports
    and sites were byte-identical before and after, 137 files: one season, two
    seasons, printing names, a sheet table four teams short, and two rounds carded
    across four years (/tmp/t4/scratch/f4/probes/bytes.py).

    Rejected: refusing an empty list, as scorecard's copy did by accident. Every
    caller decides what none means before it asks, and a refusal there stops a
    build over the wording of a sentence. ``tools/fetch.py``'s ``_listed`` was left
    alone as a different rule: it counts card ids past ``GROUP_CAP`` and joined the
    rest with commas alone. That read ``a, b`` below the cap and ``a, ..., h and 6
    more`` past it, so it lists by in_words since 4.237, its count the last item.
    Six lists in a sentence were joined with `` and `` alone, which gives ``a and
    b and c`` for three: F9's games, sets and status, the
    fixtures of ``bye-and-fixture``, and two in ``tools/fetch._changed``
    (/tmp/t6/scratch/m23/probe-before.txt). They call in_words now, and so do
    ``scorecard._taken_for_a_heading`` and the demo's heading, whose two items at
    most read as this rule's already. So the scan below reads every `` and `` join
    as a copy, and reads a comma join spliced after a word where a word, a full
    stop, a comma, a semicolon, a question mark or the end of the string follows
    it, which is where the 4.158 lists of the next class were. Since 4.237 it reads
    a join after a colon and at the start of a sentence as well, which
    TestAListAfterAColonOrOpeningASentenceIsASentenceToo measures. Since 4.169 it
    also reads a join after another splice or ``round(s)``, after a dash, inside
    brackets, and handed to a call, which
    TestAListInBracketsAfterADashOrAfterRoundsIsASentenceToo measures. Whatever it
    finds that is not named, or finds more of in a function than it is named for,
    is reported with its file, line, function and source, so that a merge bringing
    a new one can see where it is.
    """

    def test_none_one_two_and_three_are_joined_with_and_or_with_or(self):
        from matchcentre.scope import in_words
        cases = {(): ("", ""), ("a",): ("a", "a"), ("a", "b"): ("a and b", "a or b"),
                 ("a", "b", "c"): ("a, b and c", "a, b or c")}
        for items, (joined, alternatives) in cases.items():
            with self.subTest(items=items):
                self.assertEqual(in_words(items), joined)
                self.assertEqual(in_words(list(items), "or"), alternatives)
        self.assertEqual(in_words(iter((1, 2, 3))), "1, 2 and 3")

    def test_no_other_copy_of_the_rule_is_left(self):
        # The copy's tell is ", ".join of everything but the last item, wherever it
        # is written, a function, an f-string or a sum. One is allowed: in_words.
        # A list the rule was never asked about has one too: " and ".join, which
        # makes "a and b and c" of three, or ", ".join of the whole list spliced
        # into a sentence after a word, as "captains for {...} came from" was, or
        # bound to a name the same function splices so, as "plays in {where} but"
        # was. After a word, a colon, as "known: {...}" was, or at the start of a
        # sentence or of the string, as "{...}: these cards sit" was (4.237). After
        # another splice or "round(s) ", as "round{s} {...}, which" and "across
        # round(s) {rounds}" were, after a dash, as "fixtures — {...} are
        # missing" was, or after a bracket, as "played ({...})" was (4.169). After
        # the join comes a word, a full stop, a comma, a colon, a semicolon or a
        # question mark, the end of the string, as the readings _match_format joins
        # with "; " end, a space before another splice, as F10's "{...} has"
        # was, or the bracket closing. A join with "or" a fallback, "+" a count or
        # "if ... else" is read as the join, spliced or bound to a name, as "are
        # {blame}." and "not read: {listed}." were
        # (TestAListWithACapOrAFallbackIsASentenceToo). So is a join handed to a
        # call, as the last line's clauses were to ending() (4.169). A finding's
        # detail is a list and keeps its commas, so it is not read.
        allowed = [
            # The one prose hit left: "--only {...}: not seasons" echoes on the
            # error: line what was typed, as it was typed.
            "build.py:_only_scope",
            # A field's value: the report's "seasons  multi: {keys}", and the same
            # keys under "not listed:", the seasons --only leaves out.
            "build.py:_cards_section", "build.py:_not_listed_section",
            # "{label} -- 2 card(s), built {date}", two facts about one folder.
            "build.py:_orphan_evidence",
            "matchcentre/scope.py:in_words",
            # --describe's "home roster:" field, the roster as the card prints it.
            "matchcentre/scorecard.py:describe_lines",
            # One team's figures beside the sheet's, "Aces 10.5, 3 played (sheet
            # 11.0, 4 played)", which only a finding's detail is made of.
            "matchcentre/validate.py:_side_by_side",
            # The doctor's cell widths and its "row markers" field, not prose.
            "tools/doctor.py:_table", "tools/doctor.py:_markers",
        ]
        found = []
        for path in (ROOT / "build.py", *sorted((ROOT / "matchcentre").glob("*.py")),
                     *sorted((ROOT / "tools").glob("*.py"))):
            source = path.read_text(encoding="utf-8")
            tree = ast.parse(source)
            owner = {child: node.name for node in ast.walk(tree)
                     if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                     for child in ast.walk(node)}
            detail = {sub for node in ast.walk(tree)
                      if isinstance(node, ast.keyword) and node.arg == "detail"
                      for sub in ast.walk(node.value)}

            def operands(value):
                if isinstance(value, ast.BoolOp):
                    return [part for side in value.values for part in operands(side)]
                if isinstance(value, ast.BinOp):
                    return operands(value.left) + operands(value.right)
                if isinstance(value, ast.IfExp):
                    return operands(value.body) + operands(value.orelse)
                return [value]
            spliced = {operand for node in ast.walk(tree)
                       if isinstance(node, ast.JoinedStr) and node not in detail
                       for before, part, after in zip(
                           [ast.Constant(". "), *node.values], node.values,
                           [*node.values[1:], ast.Constant("")])
                       if isinstance(part, ast.FormattedValue)
                       and isinstance(before, ast.Constant)
                       and re.search(r"(?:[a-z:.?)]|^|—|--) $|\($", before.value)
                       and isinstance(after, ast.Constant)
                       and re.match(r"(?: [a-z]|[.,:;?](?: |$)| ?$|\))", after.value)
                       for operand in operands(part.value)}
            spliced |= {operand for node in ast.walk(tree)
                        if isinstance(node, ast.Call) and node not in detail
                        for value in (*node.args, *(keyword.value for keyword
                                                    in node.keywords
                                                    if keyword.arg != "detail"))
                        for operand in operands(value)}
            named = {(owner.get(value), value.id) for value in spliced
                     if isinstance(value, ast.Name)}
            spliced |= {operand for node in ast.walk(tree)
                        if isinstance(node, ast.Assign)
                        and any(isinstance(target, ast.Name)
                                and (owner.get(node), target.id) in named
                                for target in node.targets)
                        for operand in operands(node.value)}
            where = path.relative_to(ROOT).as_posix()
            found += sorted(
                ((f"{where}:{owner.get(node, '<module>')}", node.lineno,
                  ast.get_source_segment(source, node))
                 for node in ast.walk(tree)
                 if isinstance(node, ast.Call)
                 and isinstance(node.func, ast.Attribute)
                 and node.func.attr == "join"
                 and isinstance(node.func.value, ast.Constant)
                 and node.func.value.value in (", ", " and ")
                 and len(node.args) == 1
                 and (node.func.value.value == " and " or node in spliced
                      or isinstance(node.args[0], ast.Subscript)
                      and ast.unparse(node.args[0].slice) == ":-1")),
                key=lambda hit: hit[1])
        # Failed on what it names, so that a hit it cannot name cannot pass.
        said = self.unaccounted(found, allowed)
        self.assertEqual(said, [], "\n".join(said))

    @staticmethod
    def unaccounted(found, allowed) -> list[str]:
        """Each hit the scan does not allow, by its file, line, function and source.

        So that a merge bringing a list joined with commas alone can see which it
        is and where to move it: every hit in a function holding more than it is
        named for, which is every hit in one not named at all, and then each name
        nothing matched. Measured when it named only the hits outside the named
        functions (/tmp/t7/scratch/LISTS-B/fixup/scan-message-pre.txt): a join put
        in ``scorecard.describe``, beside the roster field it is named for, failed
        with the two lists of functions and nothing after them, and that is one of
        the functions a unit in flight edits.
        """
        from collections import Counter
        count = Counter(site for site, _, _ in found)
        extra = count - Counter(allowed)
        said = [f"{site.split(':')[0]}:{line} {site.split(':')[1]}: {text}"
                for site, line, text in found if site in extra]
        return said + [f"named, and not found: {site}"
                       for site in Counter(allowed) - count]

    def test_a_join_more_in_a_function_it_names_is_named_by_its_line(self):
        found = [("m.py:f", 3, "', '.join(a)"), ("m.py:g", 5, "', '.join(b)"),
                 ("m.py:f", 9, "', '.join(c)"), ("n.py:h", 2, "', '.join(d)")]
        self.assertEqual(self.unaccounted(found, ["m.py:f", "m.py:g", "m.py:k"]),
                         ["m.py:3 f: ', '.join(a)", "m.py:9 f: ', '.join(c)",
                          "n.py:2 h: ', '.join(d)", "named, and not found: m.py:k"])
        self.assertEqual(self.unaccounted(found[:2], ["m.py:f", "m.py:g"]), [])


class TestTheTeamsANoteOrAnErrorNamesAreListedAsASentence(CliCase):
    """Two notes and ``player-two-teams`` list their teams as ``a, b and c``.

    Each joined its teams with commas alone, beside notes that list through
    ``discover._listed``. Measured before, on the demo, and on the demo written with
    ``--teams 3`` and ``--teams 2`` (/tmp/t4/scratch/g2/b3): the captains' note said
    ``captains for Brindle Magpies, Brindle Quolls, Brindle Rosellas came from the
    (C) marks``, and the note just above it ``were un-shouted into Brindle Magpies,
    Brindle Quolls, Brindle Rosellas.``, with the same six-team list on the demo and
    ``Brindle Magpies, Brindle Rosellas`` for two. A player on two teams' cards in
    one round was told ``zed-quill plays for aces, rockets in round 3``, and on three
    ``aces, owls, rockets`` (/tmp/t4/scratch/g2/b-two-teams-before.txt). The error's
    detail keeps its commas, because it is a list and not a sentence.

    The one-rule scan above finds a join spliced between two words, inline or
    through a name the same function splices so. On the unfixed tree it found the
    captains' note, ``player-two-teams`` and the two lists of the next class, and
    nothing else. The team names' note ends at a full stop, so the scan does not see
    it. It is moved too, because it prints just above the captains' note, and one run
    would otherwise list one set of teams two ways. ``player-two-teams`` is older than
    this wave, and it is moved because the scan finds it: left as it was, it would be
    an exception the scan has to name. Widening the scan to joins beside a full stop
    or a comma found 29 more, among them a list of cell widths and questions that
    want ``or`` (/tmp/t4/scratch/g2/scanrules-before.txt), and those were filed. They
    are moved now, and the scan is widened to hold them: with the `` and `` joins,
    it found 30 on the unfixed tree, and in_words and the cell widths once they
    were moved (/tmp/t6/scratch/m23/scan2-before.txt and scan2-after.txt). A join
    after a colon, as F9's ``for different fixtures: ...``, or opening a sentence,
    as F10's ``... have fewer than``, was not a hit; since 4.237 both are.
    Nor is ``roster-incomplete``'s ``player(s) {...} of``, which
    TestTheListsTheChecksNameAreSentences holds
    beside the rest. Nor was a join after a splice that makes ``round`` plural or
    before one that makes ``is`` so, as in F3's, discovery's and the config
    writer's ``rounds 2, 3, which the draw does not list``, the notes' ``rounds 5,
    6, 7, SF, GF are in the declared draw`` and ``rounds SF, GF are declared as
    finals``, or one after a dash, as a declared round's ``— Riverside Rockets v
    Parkview Wanderers, Hilltop Aces v Lakeside Spinners are missing``, nor F3's
    ``(1, 2, 3)``. Those seven were measured through ``build.py``
    (/tmp/t6/scratch/m23/fixup/lists-after.txt) and left for a row of their own.
    Since 4.169 each is a hit and lists by in_words, as
    TestAListInBracketsAfterADashOrAfterRoundsIsASentenceToo says.
    """

    COMP = "tuesday-division-b"
    DECLARED = {"hilltop-aces": ("Hilltop Aces", "Dev Raman"),
                "lakeside-spinners": ("Lakeside Spinners", "Gil Ahearn")}
    LISTED = {0: "Hilltop Aces, Lakeside Spinners, Parkview Wanderers and Riverside "
                 "Rockets",
              1: "Lakeside Spinners, Parkview Wanderers and Riverside Rockets",
              2: "Parkview Wanderers and Riverside Rockets"}

    def notes(self, declared: int) -> list[str]:
        """The two notes, with the team names and captains of *declared* teams given."""
        given = list(self.DECLARED.items())[:declared]
        path = self.cwd / "config.toml"
        path.write_text(
            "[team_names]\n"
            + "".join(f'{slug} = "{name}"\n' for slug, (name, _) in given)
            + f"\n[competitions.{self.COMP}.captains]\n"
            + "".join(f'"{name}" = "{captain}"\n' for _, (name, captain) in given),
            encoding="utf-8")
        cfg = config_mod.load(path)
        cards, rejected = scorecard.read_tree(self.cwd / "data",
                                              expect=cfg.declared_format())
        found = discover_mod.discover(cards, rejected, config=cfg,
                                      root=self.cwd / "data")
        return [note for note in found.notes
                if "un-shouted into" in note or ": captains for " in note]

    def test_the_notes_list_four_three_and_two_teams(self):
        path = self.cwd / "config.toml"
        for declared, listed in self.LISTED.items():
            with self.subTest(teams=4 - declared):
                self.assertEqual(self.notes(declared), [
                    f"{self.COMP}: cards shout team names, so {4 - declared} of them "
                    f"were un-shouted into {listed}. [team_names] in {path} is where "
                    f"to correct any that read wrongly, and a line there counts once "
                    f"it has no # in front.",
                    f"{self.COMP}: captains for {listed} came from the (C) marks "
                    f"printed on the scorecards. [competitions.{self.COMP}.captains] "
                    f"in {path} is where to name one yourself, and a line there "
                    f"counts once it has no # in front."])

    def test_a_player_on_two_or_three_teams_is_told_them_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        rules = scoring.ruleset("games-bonus")

        def played(home: str, away: str) -> Match:
            sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                                   home_players=("zed-quill",),
                                   away_players=(f"{away}-{n}",), rule=shape.set_rule)
                         for n, slot in enumerate(shape.slots))
            return Match(competition=self.COMP, round="3", home=home, away=away,
                         fmt=shape, rules=rules, sets=sets)

        for teams, listed in ((("rockets", "aces"), "aces and rockets"),
                              (("rockets", "aces", "owls"), "aces, owls and rockets")):
            with self.subTest(teams=len(teams)):
                matches = [played(team, f"other-{n}") for n, team in enumerate(teams)]
                # The context carries the config the build read, which the
                # sentence names.
                found = validate._check_player_teams(SimpleNamespace(
                    playable=matches, competition=SimpleNamespace(rounds={}),
                    config_name="other.toml"))
                self.assertEqual(
                    [(issue.message, issue.detail) for issue in found],
                    [(f"zed-quill plays for {listed} in round 3; nobody is on two "
                      f"courts at once, so either one of those cards names the wrong "
                      f"player, or they are two different people who share a printed "
                      f"name — which is what [namesakes] in other.toml is for.",
                      ", ".join(sorted(teams)))])


class TestAnUnknownTeamsMatchesAndADrawsRepeatsAreListedAsASentence(unittest.TestCase):
    """F8 lists the matches it names, and a declared round its repeats, as a sentence.

    Each joined its list with commas alone, through a name: ``where`` in
    ``validate._check_team_list`` and ``named`` in ``discover._repeat_notes``.
    Measured before, through each function
    (/tmp/t4/scratch/g2/fixup/f8-repeats-before.txt): a team the list lacks, in two
    matches, was told ``'wombles' plays in R1 wombles v aces, R2 wombles v owls but is
    not in the declared team list``, and with the list derived ``appears in R1 wombles
    v aces, R2 wombles v owls and in no other round``, which reads the last clause as
    the list's third item. A declared round with two fixtures written down twice said
    ``lists Aces v Owls, Rockets v Spinners more than once``. One item read as it does
    now, and the demo prints neither.

    Both are older than this wave, as ``player-two-teams`` is, and they are moved for
    the same reason: the one-rule scan, read through a name, finds them. Rejected:
    reading through a name for the lists this wave wrote alone, which is a list of
    exceptions written into the scan.
    """

    def test_an_unknown_team_is_told_its_matches_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        rules = scoring.ruleset("games-bonus")

        def played(number: int, away: str) -> Match:
            sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                                   home_players=("zed-quill",),
                                   away_players=(f"{away}-p",), rule=shape.set_rule)
                         for slot in shape.slots)
            return Match(competition="c", round=str(number), home="wombles",
                         away=away, fmt=shape, rules=rules, sets=sets)

        listed = {1: "R1 wombles v aces",
                  2: "R1 wombles v aces and R2 wombles v owls",
                  3: "R1 wombles v aces, R2 wombles v owls and R3 wombles v rockets"}
        for declared in (True, False):
            for count, where in listed.items():
                with self.subTest(declared=declared, matches=count):
                    matches = [played(n + 1, away) for n, away in
                               enumerate(("aces", "owls", "rockets")[:count])]
                    competition = SimpleNamespace(
                        id="c", teams=dict.fromkeys(("aces", "owls", "rockets")),
                        teams_declared=declared, rounds={})
                    found = validate._check_team_list(SimpleNamespace(
                        competition=competition, matches=matches, club=None))
                    self.assertEqual([issue.message for issue in found], [
                        f"'wombles' plays in {where} but is not in the declared "
                        f"team list for c. Either the banner or the list is wrong; "
                        f"if it is the banner, [aliases] files it under the declared "
                        f"team it is, and the cards do not say which that is, so no "
                        f"line is offered." if declared else
                        f"'wombles' appears in {where} and in no other round; with "
                        f"no declared team list this program cannot tell a new team "
                        f"from a misspelt one."])

    def test_a_declared_round_is_told_its_repeats_as_a_sentence(self):
        from types import SimpleNamespace
        teams = {slug: SimpleNamespace(name=slug.title()) for slug in
                 ("aces", "owls", "rockets", "spinners", "wanderers", "wrens")}
        pairs = (("aces", "owls"), ("rockets", "spinners"), ("wanderers", "wrens"))
        listed = {1: "Aces v Owls", 2: "Aces v Owls and Rockets v Spinners",
                  3: "Aces v Owls, Rockets v Spinners and Wanderers v Wrens"}
        for count, named in listed.items():
            with self.subTest(repeats=count):
                note, = discover_mod._repeat_notes("c", "1", pairs[:count], teams)
                self.assertTrue(note.startswith(
                    f"c: round 1 of the declared draw lists {named} more than once. "),
                    note)


class TestThreeCardsThatDisagreeAboutOneMatchAreToldAsThree(CliCase):
    """F9 lists what three cards disagree about as a sentence, and counts none of them.

    ``validate._disagreement`` joined the games, the sets and the status with
    `` and `` alone, and the sentence around it was written for two cards. Measured
    before, through ``build.py`` on the season with two more cards for round 1's
    Rockets v Aces that give the games as 24-7 and 24-9
    (/tmp/t6/scratch/m23/probe-before.txt): exit 1, 201 lines, and ``3 cards claim
    round 1 riverside-rockets v hilltop-aces and disagree about the games — 24-6
    and 24-7 and 24-9. So neither is counted``, the sentence ending ``because
    choosing between two results is a guess this program will not make. To fix it,
    remove the file that is wrong``. Three cards are not neither, and need not be
    two results, and two of them can be wrong. Three that agree about every figure
    and name three players were told ``both cards say the same about it`` and ``a
    rubber the other card gives to somebody else``, and that the night comes back
    ``when the card that is wrong leaves data/``
    (/tmp/t6/scratch/m23/adj-before.txt, line 24). So the list is ``in_words``',
    and of three or more cards the sentences say ``none of them``, ``every card
    says``, ``another card`` and ``every file that is wrong``, as the page's own
    wording of F9 does. ``choosing between them`` is said of any number. Two cards
    read as they did but for that.

    Rejected: ``choosing between N results``. Two of three cards can agree, and
    then the choice is between two results and not three.
    """

    COPIES = (((6, 1), (6, 2), (6, 0), (6, 4)), ((6, 3), (6, 2), (6, 0), (6, 4)))
    NAMES = ("Zed Quill", "Yan Oss")

    def f9(self, copies: int, *, named: bool = False) -> str:
        """F9 as the report prints it, unwrapped, with *copies* more cards of R1.

        The copies give other games, or with *named* the same games and another
        player in the Rockets' first singles.
        """
        rnd, home, away, played = FIXTURES[0]
        away_rows, away_on_court = squad_for(away, TEAMS[away][1])
        for n, scores in enumerate(self.COPIES[:copies]):
            home_rows, home_on_court = squad_for(
                home, TEAMS[home][1], {home: Swap(1, self.NAMES[n])} if named else None)
            cardwriter.write_card_file(
                self.cwd / "data" / f"Round{rnd}" / f"copy-{n}.pdf",
                cardwriter.CardSpec(
                    date=DATES[rnd], round_label=rnd, division="B",
                    court=f"0{n + 7}", match_id=f"40{n + 7}0001",
                    home_name=TEAMS[home][0], away_name=TEAMS[away][0],
                    rows=rows_for(played if named else scores, home_on_court,
                                  away_on_court),
                    home_roster=home_rows, away_roster=away_rows))
        run = self.build(expect=1)
        self.assertLessEqual(max(map(len, run.out.splitlines())), 78)
        return flat(" ".join(printed_finding(self, run.out, "F9")))

    def test_three_cards_are_listed_as_a_sentence_and_none_of_them_is_counted(self):
        self.assertIn(
            "3 cards claim round 1 riverside-rockets v hilltop-aces and disagree "
            "about the games — 24-6, 24-7 and 24-9. So none of them is counted — not "
            "in the ladder, not in either team's row, not in anybody's playing "
            "record — because choosing between them is a guess this program will "
            "not make. To fix it, remove every file that is wrong from data/ and "
            "build again.", self.f9(2))

    def test_two_cards_are_still_neither(self):
        self.assertIn(
            "2 cards claim round 1 riverside-rockets v hilltop-aces and disagree "
            "about the games — 24-6 and 24-7. So neither is counted — not in the "
            "ladder, not in either team's row, not in anybody's playing record — "
            "because choosing between them is a guess this program will not make. "
            "To fix it, remove the file that is wrong from data/ and build again.",
            self.f9(1))

    def test_three_cards_that_name_three_players_are_not_spoken_of_as_two(self):
        self.assertIn(
            "3 cards claim round 1 riverside-rockets v hilltop-aces, agree about the "
            "result and disagree about who played. The result is counted once — "
            "every card says the same about it — and no appearance is credited for "
            "the night, because crediting the card read first would put a real "
            "person in a rubber another card gives to somebody else. Everybody's "
            "record for that night comes back when every card that is wrong has "
            "left data/.", self.f9(2, named=True))

    def test_two_cards_that_name_two_players_are_still_both(self):
        self.assertIn(
            "2 cards claim round 1 riverside-rockets v hilltop-aces, agree about the "
            "result and disagree about who played. The result is counted once — "
            "both cards say the same about it — and no appearance is credited for "
            "the night, because crediting the card read first would put a real "
            "person in a rubber the other card gives to somebody else. Everybody's "
            "record for that night comes back when the card that is wrong leaves "
            "data/.", self.f9(1, named=True))

    def test_every_part_three_cards_disagree_about_is_listed_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import MatchStatus

        def read(games, sets, status):
            return SimpleNamespace(
                home_games=games[0], away_games=games[1], home_sets=sets[0],
                away_sets=sets[1], status=MatchStatus(status), winner="home",
                players_on=lambda side: ())

        group = [read((24, 6), (4, 0), "played"), read((24, 7), (3, 1), "forfeit"),
                 read((24, 9), (2, 2), "played")]
        self.assertEqual(validate._disagreement(group[:2]),
                         "the games — 24-6 and 24-7; the sets — 4-0 and 3-1; the "
                         "status — played and forfeit")
        self.assertEqual(validate._disagreement(group),
                         "the games — 24-6, 24-7 and 24-9; the sets — 4-0, 3-1 and "
                         "2-2; the status — played, forfeit and played")


class TestTheListsTheChecksNameAreSentences(unittest.TestCase):
    """Six findings list what they name as ``a, b and c``, and their details keep commas.

    ``totals-mismatch``, ``set-players-missing``, ``player-two-rosters``,
    ``ratings-missing``, ``roster-mismatch`` and ``roster-incomplete`` joined their
    lists with commas alone. Measured before, through each check
    (/tmp/t6/scratch/m23/probe-before.txt, and this class run on the unfixed tree):
    a card of four players with one rating was told ``no rating was read for
    bo-nash, dee-ferro, eli-quade.``, a home roster of three players the squad does
    not hold ``the home roster names ana-reyes, bo-nash, cy-oduya, who are not in
    rockets's registered squad.``, a TOTAL row wrong in three cells ``disagree on
    home sets, home games, away games.``, and one name in three teams' roster
    blocks ``Kit Vasse is in the roster block of aces, owls, rockets, so``. Two
    items read ``aces, owls``. So each sentence lists by ``scope.in_words``. A
    finding's detail is a list and not a sentence, and keeps its commas, as
    ``player-two-teams``' does.

    Rejected: leaving ``roster-incomplete``, whose ``player(s) {...} of`` the
    widened scan does not read. It is the sentence beside ``roster-mismatch``, and
    one would list ``a, b and c`` and the other ``a, b, c``.

    ``roster-mismatch`` has since been removed (4.230), since no build reached it,
    and the roster test below holds ``roster-incomplete`` alone.
    """

    SHAPE = fmt_mod.match_format("doubles-singles-doubles")
    HOME = ("ana-reyes", "bo-nash", "cy-oduya")
    AWAY = ("dee-ferro", "eli-quade", "fay-ruston")

    def match(self, *, ratings=None, blank=()):
        """R3 Rockets v Aces, the away side unread in the slots *blank* names."""
        from matchcentre.model import Match, SetResult
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=self.HOME[:slot.players],
                               away_players=(() if slot.key in blank
                                             else self.AWAY[:slot.players]),
                               rule=self.SHAPE.set_rule)
                     for slot in self.SHAPE.slots)
        return Match(competition="c", round="3", home="rockets", away="aces",
                     fmt=self.SHAPE, rules=scoring.ruleset("games-bonus"), sets=sets,
                     home_roster=self.HOME, away_roster=self.AWAY,
                     ratings=ratings or {}, source="r3.pdf")

    def test_the_cells_a_total_row_gets_wrong_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import pdf, validate
        listed = {(9, 24, 6, 0): "home sets", (9, 99, 6, 0): "home sets and home games",
                  (9, 99, 98, 0): "home sets, home games and away games"}
        with tempfile.TemporaryDirectory() as tmp:
            for totals, wrong in listed.items():
                with self.subTest(wrong=wrong):
                    path = cardwriter.write_card_file(
                        Path(tmp) / "card.pdf", cardwriter.CardSpec(totals=totals))
                    card = scorecard.read_page(pdf.extract(path))
                    found = validate._check_totals(SimpleNamespace(
                        rule=self.SHAPE.set_rule, in_play=[card]))
                    self.assertEqual([issue.message for issue in found], [
                        f"{path}: the printed TOTAL row and the set rows disagree on "
                        f"{wrong}."])

    def test_the_sets_no_player_was_read_for_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        listed = {1: "d1", 2: "d1 and s1", 3: "d1, s1 and s2"}
        slots = [slot.key for slot in self.SHAPE.slots]
        for count, nameless in listed.items():
            with self.subTest(sets=count):
                competition = SimpleNamespace(id="c", player_index=lambda: {},
                                              teams={})
                found = validate._check_set_players(SimpleNamespace(
                    competition=competition, club=None,
                    playable=[self.match(blank=slots[:count])]))
                self.assertEqual(
                    [issue.message for issue in found
                     if issue.rule == "set-players-missing"],
                    [f"R3 rockets v aces: no away player was read for {nameless}, so "
                     f"those games are counted for aces but for nobody in it."])

    def test_the_players_no_rating_was_read_for_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Rating
        # Four players on court, two a side in the doubles, and the row's case is
        # the last: only ana-reyes rated.
        # 4.442 moved the words: one name is told what its block gave, and more
        # than one are listed by the same rule as before, the block said once for
        # each side the names are on: ana-reyes and bo-nash are both home players,
        # on one block, and bo-nash, dee-ferro and eli-quade on both.
        listed = {("bo-nash", "dee-ferro", "eli-quade"):
                      "the roster block gives no rating for ana-reyes, who played, "
                      "so ana-reyes shows",
                  ("dee-ferro", "eli-quade"):
                      "the roster block gives no rating for ana-reyes and bo-nash, "
                      "who played, so each shows",
                  ("ana-reyes",):
                      "the roster blocks give no rating for bo-nash, dee-ferro and "
                      "eli-quade, who played, so each shows"}
        for rated, absent in listed.items():
            with self.subTest(rated=rated):
                found = validate._check_ratings(SimpleNamespace(playable=[
                    self.match(ratings={slug: Rating(singles=5.0) for slug in rated})]))
                self.assertEqual([issue.message for issue in found],
                                 [f"R3 rockets v aces: {absent} none for this "
                                  f"round."])

    def test_a_roster_the_squad_does_not_match_is_told_it_as_a_sentence(self):
        # Only what the roster leaves out: roster-mismatch, which told a roster the
        # names it gives beyond the squad, is gone (4.230).
        from types import SimpleNamespace
        from matchcentre import validate
        others = ("gus-marr", "hal-onu", "ivy-pell")
        listed = {1: "gus-marr", 2: "gus-marr and hal-onu",
                  3: "gus-marr, hal-onu and ivy-pell"}
        for count, absent in listed.items():
            with self.subTest(players=count):
                squad = self.HOME[count:] + others[:count]
                team = SimpleNamespace(players=[SimpleNamespace(slug=slug)
                                                for slug in squad])
                found = validate._check_rosters(SimpleNamespace(
                    playable=[self.match()],
                    competition=SimpleNamespace(teams={"rockets": team})))
                self.assertEqual(
                    [(issue.rule, issue.message, issue.detail) for issue in found],
                    [("roster-incomplete",
                      f"R3 rockets v aces: the home roster omits registered player(s) "
                      f"{absent} of rockets.", ", ".join(self.HOME))])

    def test_one_name_in_three_roster_blocks_is_told_them_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        listed = {("aces", "owls"): "aces and owls",
                  ("aces", "owls", "rockets"): "aces, owls and rockets"}
        for teams, holders in listed.items():
            with self.subTest(teams=len(teams)):
                competition = SimpleNamespace(teams={
                    team: SimpleNamespace(slug=team, players=[SimpleNamespace(
                        slug="kit-vasse", name="Kit Vasse")]) for team in teams})
                # The context carries the config the build read, which the line
                # to paste is sent to.
                issue, = validate._check_namesakes(
                    SimpleNamespace(competition=competition, config_name="other.toml"))
                self.assertTrue(issue.message.startswith(
                    f"Kit Vasse is in the roster block of {holders}, so one player "),
                    issue.message)
                paste = ", ".join(f'"{team}"' for team in teams)
                self.assertTrue(issue.message.endswith(
                    f"add kit-vasse = [{paste}] under [namesakes] in other.toml."),
                    issue.message)
                self.assertEqual(issue.detail, ", ".join(teams))


class TestTheListsTheNotesAndTheLoaderNameAreSentences(unittest.TestCase):
    """Discovery's notes, the loader and the careers page list as a sentence too.

    Measured before (/tmp/t6/scratch/m23/probe-before.txt): a round with three
    declared teams unaccounted for said ``accounts for none of Rockets, Spinners,
    Wrens.``; a [namesakes] entry over three teams ``a player of their own in aces,
    owls, rockets``; a competition section with no season_key in a run of three
    seasons ``the section needs season_key — one of 2025-winter, 2026-summer,
    2026-winter.``; ``[rules] unplayed = "avg"`` ``must be one of 'average',
    'zero', got 'avg'``; cards of two shapes ``(d1-d2-s1 on d.pdf; d1-s1-d2 on
    a.pdf, b.pdf, c.pdf)``; and a careers template short of three markers ``is
    missing <!--TITLE-->, <!--HEADING-->, <!--FOOTER-->;``. Each lists by
    ``scope.in_words`` now, and the two that offer a choice list with ``or``: the
    section needs ``season_key — 2025-winter, 2026-summer or 2026-winter``, and
    unplayed ``is not "average" or "zero"``, by ``scope.choices`` since 4.242, as
    ``[build] seasons`` is.

    Rejected: ``one of a, b or c``, which offers the choice twice. Left alone: a list
    after a colon, as ``Seasons are the folder names directly under data:
    2025-winter, 2026-summer``, or opening a sentence, which the widened scan did
    not read and which were filed as a shape of their own. Both are sentences since
    4.237 (TestAListAfterAColonOrOpeningASentenceIsASentenceToo).
    """

    def test_a_round_short_of_teams_names_them_as_a_sentence(self):
        from types import SimpleNamespace
        teams = {slug: SimpleNamespace(name=slug.title())
                 for slug in ("aces", "owls", "rockets", "spinners", "wrens")}
        for byes, named in ((("rockets",), "Spinners and Wrens"),
                            ((), "Rockets, Spinners and Wrens")):
            with self.subTest(named=named):
                # is_finals since 4.445, which skips a final's round; number and
                # the card's two teams since 4.444, which counts a round's own
                # cards' teams as accounted for; washed_out, washouts and
                # has_washout since 4.535, which counts a washout's teams as
                # accounted for too, and a round with one as a round come.
                drawn = SimpleNamespace(source="cards", fixtures=(("aces", "owls"),),
                                        byes=byes, is_finals=False, number="1",
                                        washed_out=False, washouts=(),
                                        has_washout=False)
                note, = discover_mod._shortfall_notes(
                    "c", {"1": drawn},
                    [SimpleNamespace(round="1", home="aces", away="owls")], teams,
                    True)
                self.assertTrue(note.startswith(
                    f"c: round 1 accounts for none of {named}. Two or more teams "),
                    note)

    def test_a_namesakes_entry_names_its_teams_as_a_sentence(self):
        # Each team its own competition, whose page holds the name with that team
        # if the team is seen, and the name alone if the team is in ``beside``. Only
        # an entry with nothing to check is a note; the rest are warnings.
        from types import SimpleNamespace
        waits = ("In {}, that name is printed only on a card that counts for nothing "
                 "so far (a washout, or a night not yet played), or on some but not "
                 "all of the cards of a night that disagree. A card like that "
                 "registers nobody, and a night whose cards disagree registers only "
                 "the names they all print, so the entry waits there until a card "
                 "that counts names {}.")
        given = "[namesakes] in config.toml gives kit-vasse a player of their own in "
        cases = {
            "all three wait": (("aces", "owls", "rockets"), (), ("aces", "owls",
                                                                 "rockets"), (),
                given + "aces, owls and rockets. "
                + waits.format("aces, owls and rockets", "those players")),
            "two wait and one is missed": (
                ("aces", "owls", "rockets", "wrens"), ("wrens",), ("aces", "owls"), (),
                given + "aces, owls, rockets and wrens, and no card puts that name "
                "in rockets: check that team against the banner it is printed "
                "under. " + waits.format("aces and owls", "those players")),
            "one waits and four are missed": (
                ("aces", "owls", "rockets", "wrens", "larks", "moths"), ("aces",),
                ("owls",), (),
                given + "aces, owls, rockets, wrens, larks and moths, and no card "
                "puts that name in rockets, wrens, larks and moths: check each of "
                "those against the banner it is printed under. "
                + waits.format("owls", "that player")),
            "all three are missed": (
                ("aces", "owls", "rockets"), (), (), (),
                given + "aces, owls and rockets, and no card puts that name in any of "
                "them, so the entry separated nobody. Check the name against a card "
                "and each team against the banner it is printed under."),
            "three of four are missed": (
                ("aces", "owls", "rockets", "wrens"), ("aces",), (), (),
                given + "aces, owls, rockets and wrens, and no card puts that name "
                "in owls, rockets and wrens, so the entry separated nobody. Check "
                "each of those against the banner it is printed under."),
            "one of two is missed": (
                ("aces", "owls"), ("aces",), (), (),
                given + "aces and owls, and no card puts that name in owls, so the "
                "entry separated nobody. Check that team against the banner it is "
                "printed under."),
            "three of four are missed, beside the name alone": (
                ("aces", "owls", "rockets", "wrens"), ("aces",), (), ("aces",),
                given + "aces, owls, rockets and wrens, and no card puts that name "
                "in owls, rockets and wrens. The rest were still separated; those "
                "added nothing, so check each of those against the banner it is "
                "printed under."),
            "one of two is missed, beside the name alone": (
                ("aces", "owls"), ("aces",), (), ("aces",),
                given + "aces and owls, and no card puts that name in owls. The rest "
                "were still separated; that one added nothing, so check it against "
                "the banner it is printed under."),
            "three competitions": (
                ("aces", "owls", "rockets"), ("aces", "owls", "rockets"), (), (),
                given + "aces, owls and rockets, and no one competition has two of "
                "those teams. Only teams of the same competition are ever one "
                "record, so this entry renamed that player and separated nobody. "
                "Leave it off, or name teams of one competition."),
        }
        for case, (teams, seen, waiting, beside, said) in cases.items():
            with self.subTest(case):
                config = SimpleNamespace(path=Path("config.toml"), competitions={},
                                         namesakes={"kit-vasse": list(teams)})
                club = SimpleNamespace(competitions=[
                    SimpleNamespace(teams={team: None}, page=(
                        {f"kit-vasse-{team}"} & {f"kit-vasse-{t}" for t in seen})
                        | ({"kit-vasse"} if team in beside else set()))
                    for team in teams])
                named = ({f"kit-vasse-{team}" for team in seen},
                         {f"kit-vasse-{team}" for team in waiting})
                with mock.patch.object(discover_mod, "_players_named",
                                       return_value=named), \
                        mock.patch.object(discover_mod, "_played_in",
                                          side_effect=lambda comp, _: comp.page), \
                        mock.patch.object(discover_mod.careers, "writes_careers",
                                          return_value=False):
                    self.assertEqual(discover_mod._namesake_notes(config, club, {}),
                                     ([], [said]) if case == "all three wait"
                                     else ([said], []))

    def test_a_namesakes_entry_ahead_of_a_team_s_first_card_is_worded_by_count(self):
        # A team [competitions] declares and no card prints waits, after any that
        # wait on a washout, and a team beside it to check makes the entry a warning.
        from types import SimpleNamespace
        waits = ("In owls, that name is printed only on a card that counts for "
                 "nothing so far (a washout, or a night not yet played), or on some "
                 "but not all of the cards of a night that disagree. A card like that "
                 "registers nobody, and a night whose cards disagree registers only "
                 "the names they all print, so the entry waits there until a card "
                 "that counts names that player.")
        ahead = ("No card this run read prints {}, which [competitions] declares, so "
                 "the entry waits there for {}.")
        given = "[namesakes] in config.toml gives kit-vasse a player of their own in "
        cases = {
            "one is declared": (("aces", "owls"), (), ("owls",), ([], [
                given + "aces and owls. "
                + ahead.format("owls", "that team's first card")])),
            "two are declared": (
                ("aces", "owls", "rockets"), (), ("owls", "rockets"), ([], [
                    given + "aces, owls and rockets. "
                    + ahead.format("owls and rockets", "those teams' first cards")])),
            "one waits and one is declared": (
                ("aces", "owls", "rockets"), ("owls",), ("rockets",), ([], [
                    given + "aces, owls and rockets. " + waits + " "
                    + ahead.format("rockets", "that team's first card")])),
            "one is declared and one is missed": (
                ("aces", "owls", "rockets"), (), ("rockets",), ([
                    given + "aces, owls and rockets, and no card puts that name in "
                    "owls: check that team against the banner it is printed under. "
                    + ahead.format("rockets", "that team's first card")], [])),
        }
        for case, (teams, waiting, declared, said) in cases.items():
            with self.subTest(case):
                config = SimpleNamespace(path=Path("config.toml"),
                                         namesakes={"kit-vasse": list(teams)})
                club = SimpleNamespace(competitions=[
                    SimpleNamespace(teams={team: None}) for team in teams])
                named = ({"kit-vasse-aces"}, {f"kit-vasse-{team}" for team in waiting})
                with mock.patch.object(discover_mod, "_players_named",
                                       return_value=named), \
                        mock.patch.object(discover_mod, "_teams_declared",
                                          return_value=set(declared)), \
                        mock.patch.object(discover_mod, "_played_in",
                                          return_value={"kit-vasse-aces"}), \
                        mock.patch.object(discover_mod.careers, "writes_careers",
                                          return_value=False):
                    self.assertEqual(discover_mod._namesake_notes(config, club, {}),
                                     said)

    def test_a_section_without_its_season_key_is_offered_the_keys_with_or(self):
        from types import SimpleNamespace
        listed = {1: "2025-winter", 2: "2025-winter or 2026-summer",
                  3: "2025-winter, 2026-summer or 2026-winter"}
        for count, keys in listed.items():
            with self.subTest(seasons=count):
                config = SimpleNamespace(
                    path=Path("config.toml"), exists=True, club_name="x",
                    namesakes={}, demo=False, competitions={
                        "monday-division-c": config_mod.CompetitionConfig(
                            id="monday-division-c", day="Monday", division="C")})
                seasons = ("2025-winter", "2026-summer", "2026-winter")[:count]
                notes = discover_mod._global_notes(
                    config, Path("data"), SimpleNamespace(name="", competitions=[]),
                    {"x": [object()]}, True, {},
                    {f"c{n}": key for n, key in enumerate(seasons)})
                self.assertEqual(
                    [note[note.index("In multi"):] for note in notes
                     if "season_key" in note],
                    [f"In multi-season mode the season is part of the id too, so "
                     f"the section needs season_key — {keys}."])

    def test_an_unplayed_mode_it_cannot_read_is_refused_with_the_two_it_can(self):
        # Worded as [build] seasons is (4.242), where it said ``must be 'average' or
        # 'zero', got 'avg'``, ``got 0`` for a number, and asked nothing of
        # ``averge``, one edit from average, or of ``ZER0``, read as zer0, one from
        # zero (/tmp/t7/scratch/RU2/p242u/before.txt). The question is asked of the
        # value as read, and the line shown as written.
        for table, written, meant in (
                ("rules", '"avg"', ""),
                ("rules", '"averge"', " Did you mean average?"),
                ("rules", "0", ""),
                ("competitions.x", '"ZER0"', " Did you mean zero?")):
            with self.subTest(table=table, written=written):
                with tempfile.TemporaryDirectory() as tmp:
                    path = Path(tmp) / "config.toml"
                    path.write_text(f"[{table}]\nunplayed = {written}\n",
                                    encoding="utf-8")
                    with self.assertRaises(config_mod.ConfigError) as refused:
                        config_mod.load(path)
                self.assertEqual(str(refused.exception),
                                 f'{path}: [{table}] unplayed = {written} is not '
                                 f'"average" or "zero".{meant}')

    def test_cards_of_two_shapes_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        shape = fmt_mod.match_format("doubles-singles-doubles")

        def read(flags, source):
            return SimpleNamespace(card=SimpleNamespace(doubles_flags=flags,
                                                        source=source, page=0))

        other = read((True, True, False), "d.pdf")
        cards = [read((True, False, True), f"{name}.pdf") for name in "abc"]
        config = SimpleNamespace(min_sets_for=lambda declared: None,
                                 declared_format=lambda declared: None)
        listed = {1: "a.pdf", 2: "a.pdf and b.pdf", 3: "a.pdf, b.pdf and c.pdf"}
        for count, sources in listed.items():
            with self.subTest(cards=count):
                with self.assertRaises(discover_mod.DiscoveryError) as refused:
                    discover_mod._match_format("c", [*cards[:count], other],
                                               config=config, declared=None,
                                               set_rule=shape.set_rule)
                self.assertTrue(str(refused.exception).startswith(
                    f"c: the cards do not agree on the shape of a match (d1-d2-s1 on "
                    f"d.pdf; d1-s1-d2 on {sources})."), str(refused.exception))

    def test_a_careers_template_short_of_its_markers_names_them_as_a_sentence(self):
        listed = {1: "<!--FOOTER-->", 2: "<!--HEADING--> and <!--FOOTER-->",
                  3: "<!--TITLE-->, <!--HEADING--> and <!--FOOTER-->"}
        with tempfile.TemporaryDirectory() as tmp:
            web = Path(tmp) / "web"
            shutil.copytree(site.WEB, web)
            for count, missing in listed.items():
                with self.subTest(markers=count):
                    page = (site.WEB / site.CAREERS_PAGE).read_text(encoding="utf-8")
                    for marker in ("<!--FOOTER-->", "<!--HEADING-->",
                                   "<!--TITLE-->")[:count]:
                        page = page.replace(marker, "")
                    (web / site.CAREERS_PAGE).write_text(page, encoding="utf-8")
                    with mock.patch.object(site, "WEB", web), \
                            self.assertRaises(site.SiteError) as refused:
                        site._careers_pages(Path(tmp) / "site", [])
                    self.assertEqual(str(refused.exception),
                                     f"{web / site.CAREERS_PAGE} is missing {missing}; "
                                     f"written as it stands the careers page would "
                                     f"lose what goes there")


def played_match(round_label: str, home: str, away: str, *, match_id: str = "",
                 home_players: tuple[str, ...] = ("zed-quill",),
                 home_roster: tuple[str, ...] = ("zed-quill",)):
    """A doubles-singles-doubles match the checks can be handed, every set 6-2."""
    from matchcentre.model import Match, SetResult
    shape = fmt_mod.match_format("doubles-singles-doubles")
    sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                           home_players=home_players, away_players=(f"{away}-p",),
                           rule=shape.set_rule) for slot in shape.slots)
    return Match(competition="c", round=round_label, home=home, away=away,
                 fmt=shape, rules=scoring.ruleset("games-bonus"), sets=sets,
                 match_id=match_id, source=f"{home}-{away}.pdf",
                 home_roster=home_roster, away_roster=(f"{away}-p",))


class TestAMessageAboutThreeOrMoreIsNotWordedForTwo(unittest.TestCase):
    """Three messages that can name three things or more are worded for that many.

    ``player-two-rosters``, ``_match_format``'s refusal and ``team-twice-in-round``
    were written for two. Measured on a copy of the unfixed tree
    (/tmp/t7/scratch/LISTS-A/before.txt): one printed name in three teams' roster
    blocks was told ``one player holds both registrations: whatever either of them
    played``, that ``they are two different people``, or one person whose ``both
    halves do belong together``, and ``If they are two people, add``; cards of
    three shapes, and of four, that ``One of them is missing or has gained a set
    row``, that the cards need ``splitting into two seasons``, and ``Neither
    reading is safe to score``; and a team with three matches in one round that
    its points ``would be counted twice``. Each message now counts its list once
    and words itself from that count. For two it reads as it did. For more it
    says ``all 3``, ``any``, ``Some of them``, ``None of the 3 readings`` and
    ``counted 3 times``. The team's matches are listed by ``scope.in_words`` as
    well (4.237).

    Rejected: one wording for every count, as ``registration(s)`` and
    ``reading(s)`` would give. It is right for no count, and each of these
    messages is read by a club that has one count in front of it.
    """

    def test_one_name_in_three_roster_blocks_is_told_of_all_three(self):
        from types import SimpleNamespace
        from matchcentre import validate
        told = {
            ("aces", "owls"): (
                "Kit Vasse is in the roster block of aces and owls, so one player "
                "holds both registrations: whatever either of them played counts "
                "towards the same record, and the team, rating and win rate on it "
                "belong to only one of them. Either they are two different people "
                "who share a printed name, or one person who changed teams "
                "mid-season and both halves do belong together. If they are two "
                "people,"),
            ("aces", "owls", "rockets"): (
                "Kit Vasse is in the roster block of aces, owls and rockets, so one "
                "player holds all 3 registrations: whatever any of them played "
                "counts towards the same record, and the team, rating and win rate "
                "on it belong to only one of them. Either they are 3 different "
                "people who share a printed name, or one person who changed teams "
                "mid-season and all 3 registrations do belong together. If they "
                "are 3 people,")}
        for teams, said in told.items():
            with self.subTest(teams=len(teams)):
                # And a team without the name, which is no part of the count.
                competition = SimpleNamespace(teams={
                    team: SimpleNamespace(slug=team, players=[SimpleNamespace(
                        slug="kit-vasse", name="Kit Vasse")]) for team in teams})
                competition.teams["zebras"] = SimpleNamespace(
                    slug="zebras", players=[SimpleNamespace(slug="ula-bird",
                                                            name="Ula Bird")])
                issue, = validate._check_namesakes(SimpleNamespace(
                    competition=competition, config_name=config_mod.DEFAULT_PATH))
                # Up to the line to paste, which the class above holds.
                self.assertEqual(issue.message.partition(" add kit-vasse = ")[0],
                                 said)

    def test_cards_of_three_shapes_are_not_told_one_of_two_is_wrong(self):
        from types import SimpleNamespace
        shape = fmt_mod.match_format("doubles-singles-doubles")

        def read(flags, source):
            return SimpleNamespace(card=SimpleNamespace(doubles_flags=flags,
                                                        source=source, page=0))

        cards = [read((True, False, True), "a.pdf"), read((True, True, False), "b.pdf"),
                 read((True, False, True, False), "c.pdf"),
                 read((False, True, True), "d.pdf")]
        # A second card of a.pdf's shape, so the readings are fewer than the cards.
        also = read((True, False, True), "e.pdf")
        config = SimpleNamespace(min_sets_for=lambda declared: None,
                                 declared_format=lambda declared: None)
        readings = ["d1-d2-s1 on b.pdf", "d1-s1-d2 on a.pdf and e.pdf",
                    "d1-s1-d2-s2 on c.pdf", "s1-d1-d2 on d.pdf"]
        many = ("Some of them are missing or have gained a set row, or the "
                "competition changed format and its cards need splitting into "
                "seasons. None of the {} readings is safe to score")
        told = {2: "One of them is missing or has gained a set row, or the "
                   "competition changed format and its cards need splitting into "
                   "two seasons. Neither reading is safe to score",
                3: many.format(3), 4: many.format(4)}
        for count, said in told.items():
            with self.subTest(shapes=count):
                with self.assertRaises(discover_mod.DiscoveryError) as refused:
                    discover_mod._match_format("c", [*cards[:count], also],
                                               config=config, declared=None,
                                               set_rule=shape.set_rule)
                self.assertEqual(str(refused.exception),
                                 f"c: the cards do not agree on the shape of a match "
                                 f"({'; '.join(readings[:count])}). {said}, so "
                                 f"nothing was scored.")

    def test_a_team_with_three_matches_in_a_round_is_counted_three_times(self):
        from types import SimpleNamespace
        from matchcentre import validate
        group = [played_match("1", "aces", "owls"), played_match("1", "aces", "wrens"),
                 played_match("1", "moths", "aces")]
        # The rest of the draw, which is no part of the count.
        others = [played_match("1", "larks", "rockets"),
                  played_match("2", "aces", "larks"),
                  played_match("2", "owls", "wrens")]
        told = {2: "aces has 2 matches in round 1: R1 aces v owls and R1 aces v "
                   "wrens. Its points for the round would be counted twice.",
                3: "aces has 3 matches in round 1: R1 aces v owls, R1 aces v wrens "
                   "and R1 moths v aces. Its points for the round would be counted "
                   "3 times."}
        for count, said in told.items():
            with self.subTest(matches=count):
                found = validate._check_duplicates(SimpleNamespace(
                    matches=group[:count] + others, multi_season=False,
                    config_name=config_mod.DEFAULT_PATH,
                    competition=SimpleNamespace(rounds=())))
                self.assertEqual([issue.message for issue in found
                                  if issue.rule == "team-twice-in-round"], [said])

    def test_a_fixture_on_two_cards_is_one_of_the_teams_matches_in_its_round(self):
        # The second card is F9's to report, as the same card twice or as two cards
        # that disagree; here it is one fixture, named and counted once.
        from types import SimpleNamespace
        from matchcentre import validate
        owls = played_match("1", "aces", "owls")
        again = {"the same card": dataclasses.replace(owls, source="aces-owls (1).pdf"),
                 "a card that disagrees": dataclasses.replace(
                     owls, source="aces-owls (2).pdf", sets=tuple(
                         dataclasses.replace(row, home_games=2, away_games=6)
                         for row in owls.sets))}
        group = [owls, played_match("1", "aces", "wrens"),
                 played_match("1", "moths", "aces")]
        told = {2: "aces has 2 matches in round 1: R1 aces v owls and R1 aces v "
                   "wrens. Its points for the round would be counted twice.",
                3: "aces has 3 matches in round 1: R1 aces v owls, R1 aces v wrens "
                   "and R1 moths v aces. Its points for the round would be counted "
                   "3 times."}
        for second, card in again.items():
            for count, said in told.items():
                with self.subTest(second=second, matches=count):
                    found = validate._check_duplicates(SimpleNamespace(
                        matches=[card, *group[:count]], multi_season=False,
                        config_name=config_mod.DEFAULT_PATH,
                        competition=SimpleNamespace(rounds=())))
                    self.assertEqual([issue.message for issue in found
                                      if issue.rule == "team-twice-in-round"], [said])
                    self.assertEqual([issue.subject for issue in found
                                      if issue.rule == "F9"], ["R1 aces v owls"])


class TestAListAfterAColonOrOpeningASentenceIsASentenceToo(unittest.TestCase):
    """A list after a colon, or at the start of a sentence, reads ``a, b and c``.

    The scan in TestAListInASentenceIsJoinedByOneRule read a comma join only after
    a word, so a list after a colon or opening a sentence was left joined with
    commas alone. Measured on a copy of the unfixed tree
    (/tmp/t7/scratch/LISTS-A/before.txt and scan/hits-before.txt), widening the
    scan to both places, and leaving out a finding's detail, found 23 joins
    besides in_words and the doctor's cell widths. One match id on three cards
    said ``for different fixtures: R1 aces v owls, R1 rockets v wrens, R2 larks v
    moths.``, three players on no squad ``zed-quill, yan-oss, xi-lu played home``,
    the seasons note ``directly under data: 2025-winter, 2026-summer,
    2026-winter.``, a key the ladder cannot count ``known: points_average, points,
    ..., head_to_head, name``, a bye for an undeclared team ``Declared: Aces,
    Larks, Wrens``, and a turned PDF ``90, 180, 270 degrees``. Each is listed by
    ``scope.in_words`` now, beside the lists in the same sentences that already
    were. An unknown set rule's ``known: advantage-6, fast4, ...`` and its three
    like it were found the same way, and offer a choice now, as
    TestARuleNothingKnowsIsRefusedWithTheRulesItCouldBe checks. Two of them had a
    verb for many: a declared format was told ``the cards describe d1-s1-d2 (3
    sets): a.pdf.`` of one card, and the misread note ``data/Round4/four-a.pdf
    record a set score``. Each now counts its list and agrees with it, as the next
    class checks through ``build.py``.

    Rejected: leaving a list after a colon joined with commas, as a list set out
    for reading. Every one of these is a clause of a sentence, and the lists
    before the colon in the same sentences were already sentences. One is left
    alone: ``error: --only 2026-wintr, 2025-sumer: not seasons this run found``
    echoes the values as they were typed, on the error line, and the scan names
    it. A finding's detail is a list and not a sentence, so it keeps its commas,
    and so does the report's ``seasons      multi: 2025-winter, 2026-winter``,
    a field's value.
    """

    def test_a_match_id_on_three_cards_lists_their_fixtures_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        group = [played_match("1", "aces", "owls", match_id="7"),
                 played_match("1", "rockets", "wrens", match_id="7"),
                 played_match("2", "larks", "moths", match_id="7")]
        told = {2: "R1 aces v owls and R1 rockets v wrens",
                3: "R1 aces v owls, R1 rockets v wrens and R2 larks v moths"}
        for count, fixtures in told.items():
            with self.subTest(cards=count):
                found = validate._check_duplicates(SimpleNamespace(
                    matches=group[:count], multi_season=False,
                    competition=SimpleNamespace(rounds=())))
                self.assertEqual([issue.message for issue in found
                                  if issue.rule == "F9"],
                                 [f"match id 7 appears on {count} cards, for "
                                  f"different fixtures: {fixtures}."])

    def test_players_on_no_squad_and_no_roster_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        from matchcentre import validate
        players = ("zed-quill", "yan-oss", "xi-lu")
        told = {1: ("zed-quill", "is", "this"),
                2: ("zed-quill and yan-oss", "are", "each"),
                3: ("zed-quill, yan-oss and xi-lu", "are", "each")}
        for count, (listed, verb, which) in told.items():
            with self.subTest(players=count):
                match = played_match("1", "aces", "owls", home_players=players[:count],
                                     home_roster=())
                found = validate._check_set_players(SimpleNamespace(
                    competition=SimpleNamespace(id="c", player_index=lambda: {}),
                    club=None, playable=[match]))
                self.assertEqual(
                    [issue.message for issue in found
                     if "on no registered squad" in issue.message],
                    [f"R1 aces v owls: {listed} played home for aces and {verb} on "
                     f"no registered squad, and no home roster was read from this "
                     f"card to check against, so {which} is a fill-in, a spelling "
                     f"that needs an alias, or a player no card has registered."])

    def test_the_season_notes_list_their_seasons_and_competitions_as_a_sentence(self):
        from types import SimpleNamespace
        config = SimpleNamespace(exists=True, path=Path("config.toml"), demo=False,
                                 competitions={})
        origins = {"tuesday-division-b": discover_mod._FROM_DATE,
                   "wednesday-division-3": discover_mod._FROM_DATE,
                   "thursday-division-1": discover_mod._NO_SEASON,
                   "friday-division-2": discover_mod._NO_SEASON,
                   "monday-division-4": discover_mod._NO_SEASON}
        notes = discover_mod._global_notes(
            config, Path("data"), SimpleNamespace(name=""), {}, True, origins,
            {"a": "2025-winter", "b": "2026-summer", "c": "2026-winter"})
        self.assertEqual(notes, [
            "Seasons are the folder names directly under data: 2025-winter, "
            "2026-summer and 2026-winter. That folder name is the only thing this "
            "program reads off a path; give each one a readable label under "
            "[seasons] in config.toml.",
            "tuesday-division-b and wednesday-division-3: these cards sit directly "
            "in data rather than in a season folder, so the season was taken from "
            "the year on the card. Move them into a folder named for their season "
            "to make that certain.",
            "friday-division-2, monday-division-4 and thursday-division-1: no "
            "season folder and no readable date, so these cards carry no season "
            "key at all. In multi-season mode that means two seasons of the same "
            "day and division would share one ladder — file them under a season "
            "folder."])

    def test_cards_a_declared_format_disagrees_with_are_listed_and_agreed_with(self):
        from types import SimpleNamespace
        shape = fmt_mod.match_format("doubles-singles-doubles")
        config = SimpleNamespace(
            min_sets_for=lambda declared: None, path="config.toml",
            declared_format=lambda declared: fmt_mod.match_format("doubles-2"))
        cards = [SimpleNamespace(card=SimpleNamespace(
            doubles_flags=(True, False, True), source=f"{name}.pdf", page=0))
            for name in "abc"]
        told = {1: ("card describes", "a.pdf", "card"),
                2: ("cards describe", "a.pdf and b.pdf", "cards"),
                3: ("cards describe", "a.pdf, b.pdf and c.pdf", "cards")}
        for count, (describe, listed, cause) in told.items():
            with self.subTest(cards=count):
                with self.assertRaises(discover_mod.DiscoveryError) as refused:
                    discover_mod._match_format("c", cards[:count], config=config,
                                               declared=None,
                                               set_rule=shape.set_rule)
                self.assertEqual(str(refused.exception),
                                 f"c: config.toml declares a d1-d2 match (2 sets) but "
                                 f"the {describe} d1-s1-d2 (3 sets): {listed}. A "
                                 f"declared format is used in preference to a "
                                 f"detected one, but not while they disagree — fix "
                                 f"the config or find out what is wrong with the "
                                 f"{cause}.")

    def test_a_key_the_ladder_cannot_count_is_told_the_keys_known_as_a_sentence(self):
        # No club reaches it: a ruleset refuses a key it does not know, as the
        # class of the settings' refusals checks, and the ladder's order handles
        # head_to_head and name before it asks for a number.
        from matchcentre import stats
        keys = scoring.LADDER_KEYS
        with self.assertRaises(ValueError) as refused:
            stats._ladder_value("head_to_head", None, None)
        self.assertEqual(str(refused.exception),
                         f"'head_to_head' is not a numeric ladder key; known: "
                         f"{', '.join(keys[:-1])} and {keys[-1]}")

    def test_a_bye_for_a_team_not_declared_lists_the_declared_as_a_sentence(self):
        with self.assertRaises(config_mod.ConfigError) as refused:
            config_mod._byes_table({"Owls": [3]}, "c", ("Wrens", "Aces", "Larks"),
                                   Path("config.toml"))
        self.assertEqual(str(refused.exception),
                         "config.toml: [competitions.c.byes] 'Owls' is not one of "
                         "this competition's teams. A bye credits points for "
                         "playing nothing, so an unrecognised name here is refused "
                         "rather than guessed at. Declared: Aces, Larks and Wrens")

    def test_an_old_dashboard_holding_strangers_names_them_as_a_sentence(self):
        from types import SimpleNamespace
        told = {1: "ours.html", 2: "notes.txt and ours.html",
                3: "notes.txt, ours.html and photo.jpg"}
        with tempfile.TemporaryDirectory() as tmp:
            old = Path(tmp) / "old"
            old.mkdir()
            names = ("notes.txt", "ours.html", "photo.jpg")
            for name in names:
                (old / name).write_text("ours\n", encoding="utf-8")
            for count, listed in told.items():
                with self.subTest(files=count):
                    strangers = names[1:2] if count == 1 else names[:count]
                    with self.assertRaises(site.SiteError) as refused:
                        site.remove_orphan(SimpleNamespace(
                            path=old, strangers=strangers, removable=False,
                            kind="dashboard", pages=()))
                    self.assertEqual(str(refused.exception),
                                     f"{old} holds file(s) this tool did not "
                                     f"write: {listed}")

    def test_old_dashboards_that_print_names_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        told = {1: "1 of them prints players' names: site/a.",
                2: "2 of them print players' names: site/a and site/b.",
                3: "3 of them print players' names: site/a, site/b and site/c."}
        for count, said in told.items():
            with self.subTest(dashboards=count):
                report = build_mod._Report()
                build_mod._players_refusal_section(
                    report, args=SimpleNamespace(out=Path("site"), data=Path("data")),
                    refused=[],
                    before=[(Path(f"site/{name}"), "names") for name in "abc"[:count]])
                self.assertIn(f"already holds {count} of its dashboards from an "
                              f"earlier build, and {said} The lines above",
                              flat(report.render(quiet=False)))

    def test_the_tools_list_what_they_looked_for_and_found_as_a_sentence(self):
        import doctor
        import fetch
        import screenshots
        turned = " degrees -- the page is turned, and every coordinate on it with it"
        for raw, said in ((b"/Rotate 180", "180"),
                          (b"/Rotate 90 /Rotate 270", "90 and 270"),
                          (b"/Rotate 90 /Rotate 180 /Rotate 270", "90, 180 and 270")):
            with self.subTest(rotation=said):
                self.assertEqual(doctor._rotation(raw), said + turned)
        ids = [f"42000{number:02d}" for number in range(10)]
        for count, said in (
                (2, "4200000 and 4200001"), (3, "4200000, 4200001 and 4200002"),
                (8, ", ".join(ids[:7]) + " and 4200007"),
                (9, ", ".join(ids[:8]) + " and 1 more"),
                (10, ", ".join(ids[:8]) + " and 2 more")):
            with self.subTest(cards=count):
                self.assertEqual(fetch._listed(ids[:count]), said)
        err = io.StringIO()
        with mock.patch.object(screenshots, "_find_browser", return_value=None), \
                contextlib.redirect_stderr(err):
            self.assertEqual(screenshots.main([]), 2)
        *names, last = screenshots.BROWSERS
        self.assertIn(f"  Looked for: {', '.join(names)} and {last}\n", err.getvalue())


class TestTheReportsListsAfterAColonOrOpeningASentenceAreSentences(CliCase):
    """F10, the team-list note and the misread note list as ``a, b and c`` in a build.

    Measured through ``build.py`` on a copy of the unfixed tree
    (/tmp/t7/scratch/LISTS-A/runs/before): the season with round three's rockets
    v wanderers taken out said ``parkview-wanderers, riverside-rockets have fewer
    than the 3 counted by the rest.``, and with round two's aces v wanderers out
    too ``hilltop-aces, parkview-wanderers, riverside-rockets have``; the team list
    read from the cards was ``4 teams: Hilltop Aces, Lakeside Spinners, Parkview
    Wanderers, Riverside Rockets.``; and a round four with a 9-2 set on two cards
    said ``data/Round4/four-a.pdf, data/Round4/four-b.pdf record a set score``, and
    on one card ``data/Round4/four-a.pdf record a set score``, in the plural, and
    that ``the card was misread`` either way. Each lists by ``scope.in_words`` now,
    and the misread note counts its cards once, for its two verbs.
    """

    COMP = "tuesday-division-b"

    def round_four(self, *played: tuple[str, str, tuple]) -> None:
        """Round four's cards, each ``(home, away, scores)``, as a club prints them."""
        folder = self.cwd / "data" / "Round4"
        folder.mkdir(parents=True, exist_ok=True)
        for index, (home, away, scores) in enumerate(played, start=7):
            home_rows, home_on_court = squad_for(home, TEAMS[home][1])
            away_rows, away_on_court = squad_for(away, TEAMS[away][1])
            cardwriter.write_card_file(folder / f"r4-{index}.pdf", cardwriter.CardSpec(
                date="2026-09-08", round_label="4", division="B",
                court=f"{index:02d}", match_id=f"200{index:04d}",
                home_name=TEAMS[home][0], away_name=TEAMS[away][0],
                rows=rows_for(scores, home_on_court, away_on_court),
                home_roster=home_rows, away_roster=away_rows))

    def test_teams_behind_the_rest_open_their_sentence_as_a_list(self):
        # Round three's rockets v wanderers, then round two's aces v wanderers too.
        for gone, behind in (((4,), "parkview-wanderers and riverside-rockets"),
                             ((4, 3), "hilltop-aces, parkview-wanderers and "
                                      "riverside-rockets")):
            with self.subTest(behind=behind):
                for index in gone:
                    self.cards[index].unlink(missing_ok=True)
                run = self.build()
                # On the average, which costs them no place (4.523).
                self.assertIn(
                    f"{self.COMP}: the ladder is in progress — teams have played "
                    f"unequal numbers of matches. {behind} have fewer than "
                    f"the 3 counted by the rest; the ladder is ordered on the "
                    f"average, so that costs them no place.",
                    flat("\n".join(printed_finding(self, run.out, "F10"))))
                if len(gone) == 1:
                    self.assertIn(
                        f"{self.COMP}: the team list was read from the cards — 4 "
                        f"teams: Hilltop Aces, Lakeside Spinners, Parkview Wanderers "
                        f"and Riverside Rockets. Check it, then",
                        flat(run.out))

    def test_cards_scoring_an_impossible_set_are_listed_and_agreed_with(self):
        cards = (("riverside-rockets", "hilltop-aces",
                  ((6, 1), (9, 2), (6, 0), (6, 3))),
                 ("lakeside-spinners", "parkview-wanderers",
                  ((6, 1), (6, 2), (9, 0), (6, 3))))
        told = {1: "data/Round4/r4-7.pdf records a set score that is impossible "
                   "under first-to-6. Either the set rule is wrong for this "
                   "competition or the card was misread;",
                2: "data/Round4/r4-7.pdf and data/Round4/r4-8.pdf record a set "
                   "score that is impossible under first-to-6. Either the set rule "
                   "is wrong for this competition or the cards were misread;"}
        for count, said in told.items():
            with self.subTest(cards=count):
                self.round_four(*cards[:count])
                run = self.build(expect=1)
                self.assertIn(f"{self.COMP}: {said} the match warnings name the set.",
                              report_notes(run.out), run.out[-3000:])


class TestAListWithACapOrAFallbackIsASentenceToo(unittest.TestCase):
    """A list with its count past a cap, or a fallback for none, reads ``a, b and c``.

    The one-rule scan followed a name only where the join was the whole of what the
    name held, so a join with ``or`` a fallback, or ``+`` a count, was not read.
    Measured on a copy of the unfixed tree (/tmp/t7/scratch/LISTS-A/fixup/pdf/
    fonts-before-impl.txt and capped-before-impl.txt): a page whose fonts none
    decode said ``the fonts this reader could not read are /F1 (Mystery0), /F2
    (Mystery1)``, with a third ``, /F3 (Mystery2)``; the files under data that are
    not PDFs ``not read: data/Round1/page1.html, data/Round1/page2.html.``, and
    past five ``data/Round1/page5.html, and 1 more``; and the threshold's why ``2
    played match(es) in tuesday-division-1, tuesday-division-2 decided nothing``,
    and of eight competitions no ``and`` at all, though of nine it said ``and 1
    more``. Each lists by ``scope.in_words`` now, the count past the cap its last
    item, as ``tools/fetch._listed`` does.

    The threshold's list is spliced after ``match(es)``, which the scan does not
    read as a word, so this class is what holds it.
    """

    def test_the_fonts_no_glyph_of_a_page_decodes_in_are_listed_as_a_sentence(self):
        from matchcentre import pdf
        told = {("F1",): "/F1 (AAAAAA+Scorecard)",
                ("F1", "F2"): "/F1 (AAAAAA+Scorecard) and /F2 (AAAAAA+Scorecard)",
                ("F1", "F2", "F3"): "/F1 (AAAAAA+Scorecard), /F2 (AAAAAA+Scorecard) "
                                    "and /F3 (AAAAAA+Scorecard)"}
        with tempfile.TemporaryDirectory() as tmp:
            for names, fonts in told.items():
                with self.subTest(fonts=len(names)):
                    # The card's one font, with no map, under each name. The reader
                    # finds objects by scanning, so the offsets moved do not matter.
                    shown = b" ".join(b"/%s 12 Tf <0102> Tj" % name.encode()
                                      for name in names)
                    fonts_in = b" ".join(b"/%s 4 0 R" % name.encode() for name in names)
                    raw = cardwriter._assemble(b"BT 60 60 Td " + shown + b" ET",
                                               with_to_unicode=False)
                    raw = raw.replace(b"/Font << /F1 4 0 R >>",
                                      b"/Font << " + fonts_in + b" >>")
                    path = Path(tmp) / "blank.pdf"
                    path.write_bytes(raw)
                    with self.assertRaises(pdf.PdfError) as refused:
                        pdf.extract(path)
                    self.assertEqual(str(refused.exception).partition(
                        "the fonts this reader could not read are ")[2].partition(
                        ". A page reported as empty")[0], fonts)

    def test_the_files_that_are_not_pdfs_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        names = [f"data/Round1/page{n}.html" for n in range(1, 8)]
        told = {1: names[0], 2: f"{names[0]} and {names[1]}",
                3: f"{names[0]}, {names[1]} and {names[2]}",
                5: f"{', '.join(names[:4])} and {names[4]}",
                6: f"{', '.join(names[:5])} and 1 more",
                7: f"{', '.join(names[:5])} and 2 more"}
        for count, listed in told.items():
            with self.subTest(files=count):
                report = build_mod._Report()
                build_mod._strays_note(report, args=SimpleNamespace(data=Path("data")),
                                       strays=[Path(name) for name in names[:count]])
                self.assertIn(f"{count} file(s) under data are not PDFs and were not "
                              f"read: {listed}. Match Centre exports",
                              flat(report.render(quiet=False)))

    def test_the_competitions_short_of_a_result_are_listed_as_a_sentence(self):
        ids = [f"tuesday-division-{n}" for n in range(1, 11)]
        told = {1: "", 2: f" in {ids[0]} and {ids[1]}",
                3: f" in {ids[0]}, {ids[1]} and {ids[2]}",
                8: f" in {', '.join(ids[:7])} and {ids[7]}",
                9: f" in {', '.join(ids[:8])} and 1 more"}
        for count, where in told.items():
            with self.subTest(competitions=count):
                why = build_mod._threshold_why(12, 0, 0, 3, ids[:count], alone=False)
                self.assertTrue(why.startswith(f"12 played match(es){where} decided "
                                               f"nothing because"), why)


class TestAListInBracketsAfterADashOrAfterRoundsIsASentenceToo(CliCase):
    """A list in brackets, after a dash or after ``round(s)`` reads ``a, b and c``.

    The one-rule scan read a comma join spliced after a word, a colon or the start
    of a sentence. A join after a splice that makes ``round`` plural, after a dash
    or inside brackets was left with commas alone, and so was one handed straight
    to a call. Measured through ``build.py``, and by calls, on a copy of the
    unfixed tree (/tmp/t7/scratch/LISTS-B/probe.py, before.txt). F3 said ``3
    regular rounds have been played (1, 2, 3). Cards were found for rounds 2, 3,
    which the draw does not list``. A declared round said ``— Riverside Rockets v
    Parkview Wanderers, Hilltop Aces v Lakeside Spinners are missing``, and the
    notes ``rounds 5, 6, 7, SF, GF are in the declared draw`` and ``3 regular
    rounds (1, 2, 3) and 2 finals rounds (SF, GF)``. A round carded in two years
    said ``(2025, 2026)`` in the run whose F9 says ``2025 and 2026``. The report
    said ``cards 8 across round(s) 1, 2, 3, SF, GF``, and its last line ``exit 1: 1
    card(s) found and not scored, 1 folder(s) not opened`` under the heading ``==
    refused: 1 card(s) found and not scored and 1 folder(s) not opened ==``.
    Widened to those four places, the scan found 33 joins where it had found 4
    (/tmp/t7/scratch/LISTS-B/scan-before.txt), and 24 of the 29 new ones were
    lists. Each is listed by ``scope.in_words`` now, and a list of rounds by
    ``sheet.rounds_listed``. The words that agree with rounds are counted by
    ``sheet.by_weeks``, as the sheet check's are. The shapes a written config.toml
    names are the values ``format`` takes, so they are offered the way a
    setting's values are, by ``scope.choices``. The classes that hold each
    sentence through ``build.py`` quote the new wording. This one holds the lists
    that no test quoted.

    Rejected: a bracketed list as a detail the scan exempts. It is a clause of the
    sentence it sits in, beside lists in the same sentences that were already
    sentences, and an exemption is a second rule the next join can hide behind.
    The exit line was asked the same question and answered the same way. Nothing
    reads it back: tools/scheduled.py keeps the status, and neither CI nor the
    doctor parses the line. So it is a sentence, like the refused heading above it.
    """

    COMP = "tuesday-division-b"

    def test_a_length_of_nought_over_one_round_is_told_one_round_has_been_played(self):
        # Measured before (/tmp/t7/scratch/LISTS-B/zero/zero-before.txt): "1 regular
        # rounds have been played (1)". The loader takes a length of 0, so F3 is
        # what refuses it, and its count agrees with the one round it names.
        for rnd in ("2", "3"):
            shutil.rmtree(self.cwd / "data" / f"Round{rnd}")
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f"rounds_total = 0\n", encoding="utf-8")
        run = self.build(expect=1)
        self.assertEqual(flat("\n".join(printed_finding(self, run.out, "F3"))),
                         f"F3 {self.COMP}: rounds_total is declared as 0 but 1 "
                         f"regular round has been played (1). rounds played: 1")

    def test_the_cards_of_one_round_are_said_to_be_across_that_round(self):
        # Measured before: "cards 2 across round(s) 1". The field is counted as
        # every other list of rounds is, rather than hedged with "(s)".
        for rnd in ("2", "3"):
            shutil.rmtree(self.cwd / "data" / f"Round{rnd}")
        self.assertIn("  cards        2 across round 1\n",
                      self.section(self.build().out, self.COMP))

    def test_an_old_dashboard_holding_two_strangers_names_them_as_a_sentence(self):
        # The build's refusal, which --prune's (a class above) already said so.
        self.build()
        for stray in ("photo.jpg", "notes.txt"):
            (self.cwd / "site" / self.COMP / stray).write_text("ours\n",
                                                               encoding="utf-8")
        run = self.build(expect=2)
        self.assertIn(f"error: site/{self.COMP} holds file(s) this tool did not write "
                      f"(notes.txt and photo.jpg); move them aside or build into a "
                      f"different --out directory", flat(run.text))

    def test_two_set_rows_on_one_slot_are_listed_as_a_sentence(self):
        # The list's rule alone. What the message says around it, "two set rows"
        # whatever their number and every slot the card holds as "the same slot",
        # is a row of its own (/tmp/t7/scratch/LISTS-B/fixup/pre.txt), and whoever
        # words that owes this test only the rule.
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.scope import in_words
        match = played_match("1", "aces", "owls")
        doubled = dataclasses.replace(match, sets=(*match.sets, match.sets[0]))
        found = validate._check_sets(SimpleNamespace(
            competition=SimpleNamespace(id="c", fmt=match.fmt, rules=match.rules),
            rule=match.fmt.set_rule, playable=[doubled]))
        [message] = [issue.message for issue in found if issue.rule == "set-count"]
        listed = re.findall(r"\(([^()]*)\)", message)
        self.assertTrue(listed, message)
        for inside in listed:
            self.assertEqual(inside, in_words(re.split(r", | and ", inside)), message)

    def test_the_numbers_in_one_games_cell_are_listed_as_a_sentence(self):
        from types import SimpleNamespace
        for printed, listed in ((("6", "4"), "6 and 4"),
                                (("6", "4", "2"), "6, 4 and 2")):
            with self.subTest(printed=listed):
                page = SimpleNamespace(words_in_band=lambda *_, words=printed: [
                    SimpleNamespace(text=word) for word in words])
                warnings: list[str] = []
                scorecard._games(page, (0, 1), SimpleNamespace(inner=(0, 0)), 2,
                                 "home", warnings)
                self.assertEqual(warnings, [
                    f"row 3: {len(printed)} numbers in the home games column "
                    f"({listed}); used the first"])

    def test_the_page_templates_are_listed_as_a_sentence(self):
        web = self.cwd / "web"
        with mock.patch.object(site, "WEB", web), \
                self.assertRaises(site.SiteError) as refused:
            site._require_templates()
        self.assertEqual(str(refused.exception),
                         f"{web} does not exist; it holds the page templates "
                         f"(index.html, app.js, styles.css, picker.html and "
                         f"careers.html) that every dashboard is built from")
        web.mkdir()
        for name in ("index.html", "app.js", "styles.css"):
            (web / name).write_text("ours\n", encoding="utf-8")
        with mock.patch.object(site, "WEB", web), \
                self.assertRaises(site.SiteError) as refused:
            site._require_templates()
        self.assertEqual(str(refused.exception),
                         f"missing page template(s): {web / 'picker.html'} and "
                         f"{web / 'careers.html'}")

    def test_a_dashboard_called_index_lists_the_tools_own_files_as_a_sentence(self):
        out = self.cwd / "site" / "index"
        with self.assertRaises(site.SiteError) as refused:
            site.write_competition(out, {}, single_file=True)
        self.assertEqual(str(refused.exception),
                         f"{out} would need its one-file dashboard called index.html, "
                         f"which is already one of this tool's own files (index.html, "
                         f"app.js, styles.css, season.json and season-data.js); the "
                         f"file is named after the directory, so rename the "
                         f"competition or build without --single-file")

    def test_the_shapes_a_written_config_names_are_offered_as_a_choice(self):
        # Measured before (/tmp/t7/scratch/LISTS-B/shapes-before.txt): "doubles-2,
        # doubles-3, ..., singles-doubles", the names format takes, unquoted.
        lines = config_mod.render(config_mod.Config(
            path=self.cwd / "config.toml")).splitlines()
        start = lines.index("# shapes:") + 1
        end = next(n for n in range(start, len(lines))
                   if not lines[n].startswith("#   "))
        *names, last = sorted(fmt_mod.FORMATS)
        self.assertEqual(" ".join(line[4:] for line in lines[start:end]),
                         ", ".join(f'"{name}"' for name in names) + f' or "{last}"')
        self.assertLessEqual(max(len(line) for line in lines[start:end]), 78)

    def test_the_example_config_offers_the_shapes_as_the_written_one_does(self):
        # Measured before (/tmp/t7/scratch/LISTS-B/fixup/pre.txt): "One of:
        # doubles-2, doubles-3, ..., singles-doubles.", with commas alone and no
        # quotes, beside a written file that offers them as a choice, and read by
        # no test, so a shape added to FORMATS would have left it stale.
        from matchcentre.scope import choices
        example = (ROOT / "config.example.toml").read_text(encoding="utf-8")
        start = example.index("# format —")
        block = example[start:example.index('# format = "', start)]
        self.assertIn(f"It takes {choices(sorted(fmt_mod.FORMATS))}.",
                      " ".join(line[2:] for line in block.splitlines()))

    def test_the_match_shape_a_note_names_is_listed_as_a_sentence(self):
        # Measured before (/tmp/t7/scratch/LISTS-B/fixup/pre.txt): "read off the
        # cards themselves — Doubles 1, Singles 1, Singles 2, Doubles 2 (first to
        # 6) — from the marker column", and "declared as" the same. The join sat in
        # format.describe(), where the scan does not look.
        shape = "Doubles 1, Singles 1, Singles 2 and Doubles 2 (first to 6)"
        self.assertIn(f"{self.COMP}: the match shape was read off the cards "
                      f"themselves — {shape} — from the marker column",
                      flat(self.build().out))
        (self.cwd / "config.toml").write_text(
            '[rules]\nformat = "doubles-singles-doubles"\n', encoding="utf-8")
        self.assertIn(f"{self.COMP}: the match shape is declared as {shape}, and "
                      f"every card agrees with it.", flat(self.build().out))

    def test_the_match_shape_the_report_and_the_page_hold_as_a_field_is_as_it_was(
            self):
        # A field's value, the card's rows in order, as scoring's "win 4, draw 3,
        # loss 2" is beside it: the page prints it after "Format:", and every
        # club's season.json holds it so already.
        (self.cwd / "config.toml").write_text(
            '[rules]\nformat = "doubles-singles-doubles"\n', encoding="utf-8")
        run = self.build()
        field = "Doubles 1, Singles 1, Singles 2, Doubles 2 (first to 6)"
        self.assertEqual(self.season()["meta"]["rules"]["format_detail"], field)
        self.assertIn(f"format doubles-singles-doubles {field}",
                      flat(self.section(run.out, "rules in force")))


class TestARuleNothingKnowsIsRefusedWithTheRulesItCouldBe(CliCase):
    """A rule's name refused offers the names it could be, as the settings beside it do.

    Each listed what it knew as ``known: a, b, c``, and asked nothing, where the
    settings beside it offer their values as a choice, by ``scope.choices``, and ask
    after the nearest. Measured through ``build.py`` on a copy of the unfixed tree
    (/tmp/t7/scratch/LISTS-A/fixup/known.txt): ``[rules] sets = "frist-to-6"`` said
    ``error: config.toml: [rules] unknown set rule 'frist-to-6'; known:
    advantage-6, fast4, first-to-6, ...``, and ``scoring = "games-bonsu"`` and
    ``format = "dubles-2"`` the same, where ``unplayed = "avrage"`` said ``is not
    "average" or "zero". Did you mean average?``. Each now says it that way, the
    value in double quotes, as config.toml writes it and as ``forfeit_award``'s
    refusal quotes it.

    Rejected: ``known: a, b and c``, which listed them by ``scope.in_words`` as a
    sentence does, and was a second wording for the values a setting takes.
    """

    @staticmethod
    def offered(names) -> str:
        return ", ".join(f'"{name}"' for name in names[:-1]) + f' or "{names[-1]}"'

    def test_each_is_refused_with_the_rules_it_could_be_and_the_nearest(self):
        sets, shapes = sorted(fmt_mod.SET_RULES), sorted(fmt_mod.FORMATS)
        refusals = (
            (fmt_mod.FormatError, lambda: fmt_mod.set_rule("frist-to-6"),
             f'set rule "frist-to-6" is not {self.offered(sets)}. Did you mean '
             f'first-to-6?'),
            (fmt_mod.FormatError, lambda: fmt_mod.set_rule("tiebreak"),
             f'set rule "tiebreak" is not {self.offered(sets)}.'),
            (fmt_mod.FormatError, lambda: fmt_mod.match_format("dubles-2"),
             f'match format "dubles-2" is not {self.offered(shapes)}. Did you mean '
             f'doubles-2?'),
            (scoring.ScoringError, lambda: scoring.ruleset("games-bonsu"),
             'scoring scheme "games-bonsu" is not "games-bonus", "rubbers", '
             '"sets-first" or "simple". Did you mean games-bonus?'),
            (scoring.ScoringError, lambda: scoring.ruleset("points"),
             'scoring scheme "points" is not "games-bonus", "rubbers", '
             '"sets-first" or "simple".'),
            (scoring.ScoringError, lambda: dataclasses.replace(
                scoring.ruleset("games-bonus"), ladder_by=("pionts", "name")),
             f'ladder key "pionts" is not {self.offered(scoring.LADDER_KEYS)}. Did '
             f'you mean points?'))
        for error, call, said in refusals:
            with self.subTest(said=said[:28]):
                with self.assertRaises(error) as refused:
                    call()
                self.assertEqual(str(refused.exception), said)

    def test_a_rules_line_nothing_knows_is_refused_so_by_the_build(self):
        for line, said in (
                ('scoring = "games-bonsu"', 'scoring scheme "games-bonsu" is not '
                 '"games-bonus", "rubbers", "sets-first" or "simple". Did you mean '
                 'games-bonus?'),
                ('sets = "frist-to-6"', f'set rule "frist-to-6" is not '
                 f'{self.offered(sorted(fmt_mod.SET_RULES))}. Did you mean '
                 f'first-to-6?'),
                ('format = "dubles-2"', f'match format "dubles-2" is not '
                 f'{self.offered(sorted(fmt_mod.FORMATS))}. Did you mean '
                 f'doubles-2?')):
            with self.subTest(line=line):
                (self.cwd / "config.toml").write_text(f"[rules]\n{line}\n",
                                                      encoding="utf-8")
                done = self.build(expect=2)
                self.assertEqual(done.err, f"error: config.toml: [rules] {said}\n")
                self.assertFalse((self.cwd / "site").exists())


class TestASeasonsLineItCannotReadIsRefusedWithTheTwoValuesItCan(CliCase):
    """``[build] seasons`` refused says what was written and what it takes, in words.

    Measured on the tree before this, by /tmp/t7/scratch/RU2/p242/probe.py: each of
    ``seasons = "singel"``, ``"multiple"`` and ``3`` stopped the build at exit 2
    with no site, saying ``[build] seasons must be one of ('single', 'multi'), got
    'singel'``: a Python tuple, the typed value lowercased and quoted as Python
    quotes it, ``'3'`` for the number 3, and no question, where the players line
    beside it in the same table asks ``Did you mean numbered?``. Now it says the
    line as the file has it, the two values as a sentence offers a choice, and the
    nearest of them where one is near. Rejected: ``one of "single" or "multi"``,
    which offers the choice twice.
    """

    def test_each_is_refused_with_the_line_the_values_and_the_nearest(self):
        for written, meant in (('"singel"', " Did you mean single?"),
                               ('"Mutli"', " Did you mean multi?"),
                               ('"multiple"', ""), ("3", "")):
            with self.subTest(written=written):
                (self.cwd / "config.toml").write_text(
                    f"[build]\nseasons = {written}\n", encoding="utf-8")
                done = self.build(expect=2)
                self.assertEqual(done.err,
                                 f'error: config.toml: [build] seasons = {written} '
                                 f'is not "single" or "multi".{meant}\n')
                self.assertFalse((self.cwd / "site").exists())


class TestABannerNobodyDeclaredIsAskedAboutTheTeamsNearestIt(CliCase):
    """F8, the page and a derived list's note ask one question of a banner, by one rule.

    Three copies of the question gave one key three answers. Measured before,
    through ``build.py`` on the season with the Rockets and the Aces printed HILLTOP
    A and HILLTOP B, the four teams declared, and a round-four card against the
    Spinners bannered HILTOP A (/tmp/t6/scratch/m23/adj-before.txt): exit 1, the
    note and the page's warning asked ``Did you mean one of 'Hilltop A'
    (hilltop-a), 'Hilltop B' (hilltop-b)?`` and F8 ``Did you mean hilltop-a,
    hilltop-b?``, of a banner one letter from Hilltop A and two from Hilltop B.
    Bannered HILLTOP, F8 asked ``Did you mean hilltop-a, hilltop-b?`` and the note
    and the page nothing, because discovery takes a key that differs from a team
    only by a tag, ``hilltop`` beside ``hilltop-a``, for two real sides of one club.
    Asked directly, the loader's copy said ``Did you mean one of hilltop-a,
    hilltop-b?`` of every one of those keys. Over the 2,903 one-edit slips of the
    four slugs, F8 and discovery named different teams for 125
    (/tmp/t6/scratch/m23/questions-before.txt). Each copy took every name within
    two edits, where the README says the nearest are named, and both only when two
    are equally close.

    So ``discover.nearest_team`` is the one rule for a banner, the declared teams
    nearest it less its siblings, and F8, declared or not, the note and the page ask
    it and word what it gives through ``slugs.did_you_mean``, with a tie as ``a or
    b``. F8 names slugs, as the rest of its sentence does, and the note and the page
    the declared spelling with its slug. Every one of the 125 was settled by F8
    asking nothing, as discovery did, of a slip that is a sibling of a side: F8
    asked of 2,903 slips and now asks of 2,778, and 840 that F8 and the note asked
    about two teams are asked about the nearer one alone
    (/tmp/t6/scratch/m23/fixup/dir-before.json, dir-after.json). The nearest are
    found before the siblings are taken out, so ``kenmore-4``, a side short of
    ``kenmore-3``, is not asked about ``kenmure-3``, another club two edits off,
    as the other order asked. The loader keeps candidates of its own, the nearest of
    the names legal where the key was written, because a setting has no siblings: no
    setting or section has a hyphen or a digit, and over the loader's 21,480
    one-edit slips the sibling rule changes nothing. A line of the sheet keeps its
    own too, siblings and all (``sheet._resolved``): it is copied off this
    competition's sheet under its heading, so ``Hilltop`` there is one of the two.

    Rejected: asking about ``hilltop`` again, as F8 did. A club with sides A and B
    whose card prints HILLTOP may be showing a third side, and naming the two
    declared ones would have it alias a side it has not got onto one it has.
    """

    COMP = "tuesday-division-b"

    def built(self, banner: str) -> tuple[list[str], str, list[str]]:
        """The notes, F8 and the page's warnings, the round-four card bannered so."""
        shutil.rmtree(self.cwd / "data")
        data = self.cwd / "data"
        write_season_cards(data, banners={"riverside-rockets": "HILLTOP A",
                                          "hilltop-aces": "HILLTOP B"})
        away_rows, away_on_court = squad_for("lakeside-spinners",
                                             TEAMS["lakeside-spinners"][1])
        home = ("Mo Tran", "Ned Oake", "Pia Lund")
        home_rows, home_on_court = squad_for("hilltop", home)
        (data / "Round4").mkdir()
        cardwriter.write_card_file(data / "Round4" / "four.pdf", cardwriter.CardSpec(
            date="2026-09-08", round_label="4", division="B", court="09",
            match_id="4090001", home_name=banner, away_name="LAKESIDE SPINNERS",
            rows=rows_for(((6, 1), (6, 2), (6, 0), (6, 3)), home_on_court,
                          away_on_court),
            home_roster=home_rows, away_roster=away_rows))
        (self.cwd / "config.toml").write_text(
            f"[competitions.{self.COMP}]\nday = \"Tuesday\"\ndivision = \"B\"\n"
            f"teams = [\"Hilltop A\", \"Hilltop B\", \"Lakeside Spinners\", "
            f"\"Parkview Wanderers\"]\n", encoding="utf-8")
        run = self.build(expect=1)
        self.assertLessEqual(max(map(len, run.out.splitlines())), 78)
        # 4.239: F8 owns a banner the declared list lacks, and discovery's note
        # about it is gone (TestABannerTheDeclaredListLacksIsReportedOnceByF8...).
        notes = [note for note in report_notes(run.out)
                 if "which is not in the declared team list" in note]
        warnings = [warning for match in self.season(self.COMP)["matches"]
                    for warning in match.get("warnings") or ()
                    if "is not one of the teams declared" in warning]
        return notes, flat(" ".join(printed_finding(self, run.out, "F8"))), warnings

    def test_a_banner_nearest_one_team_is_asked_about_that_team_alone(self):
        notes, f8, page = self.built("HILTOP A")
        self.assertEqual(notes, [])
        self.assertIn(f"'hiltop-a' plays in R4 hiltop-a v lakeside-spinners but is "
                      f"not in the declared team list for {self.COMP}. Did you mean "
                      f"hilltop-a? Either", f8)
        self.assertEqual(page, [f"'HILTOP A' is not one of the teams declared for "
                                f"{self.COMP}. Did you mean 'Hilltop A' (hilltop-a)?"])

    def test_a_banner_a_tag_short_of_two_teams_is_asked_nothing(self):
        notes, f8, page = self.built("HILLTOP")
        self.assertEqual(notes, [])
        self.assertIn(f"'hilltop' plays in R4 hilltop v lakeside-spinners but is not "
                      f"in the declared team list for {self.COMP}. Either", f8)
        self.assertNotIn("Did you mean", f8)
        self.assertEqual(page, [f"'HILLTOP' is not one of the teams declared for "
                                f"{self.COMP}."])

    def test_a_key_as_near_two_teams_is_asked_about_both_with_or(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=("zed-quill",), away_players=("yan-oss",),
                               rule=shape.set_rule) for slot in shape.slots)
        known = {"rackets": "Rackets", "rockets": "Rockets", "wrens": "Wrens"}
        played = Match(competition="c", round="4", home="rickets", away="wrens",
                       fmt=shape, rules=scoring.ruleset("games-bonus"), sets=sets)
        for declared in (True, False):
            with self.subTest(declared=declared):
                issue, = validate._check_team_list(SimpleNamespace(
                    matches=[played], club=None, competition=SimpleNamespace(
                        id="c", teams=dict.fromkeys(known),
                        teams_declared=declared, rounds={})))
                # A declared list's F8 follows its question with the remedy (4.239).
                self.assertEqual(issue.message.partition(" Did you mean")[2]
                                 .partition("?")[0], " rackets or rockets",
                                 issue.message)
        self.assertEqual(discover_mod._did_you_mean("rickets", known),
                         " Did you mean 'Rackets' (rackets) or 'Rockets' (rockets)?")

    def test_f8_and_discovery_name_the_same_teams_for_every_slip(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=("zed-quill",), away_players=("yan-oss",),
                               rule=shape.set_rule) for slot in shape.slots)
        known = {"hilltop-a": "Hilltop A", "hilltop-b": "Hilltop B",
                 "lakeside-spinners": "Lakeside Spinners"}
        letters = "abhilopt-"
        keys = {"hilltop"} | {f"{slug[:i]}{c}{slug[i + 1:]}" for slug in known
                              for i in range(len(slug)) for c in letters}
        keys |= {f"{slug[:i]}{c}{slug[i:]}" for slug in known
                 for i in range(len(slug) + 1) for c in letters}
        keys |= {f"{slug[:i]}{slug[i + 1:]}" for slug in known
                 for i in range(len(slug))}
        disagree = []
        for key in sorted(keys - set(known)):
            played = Match(competition="c", round="4", home=key,
                           away="lakeside-spinners", fmt=shape,
                           rules=scoring.ruleset("games-bonus"), sets=sets)
            said = discover_mod._did_you_mean(key, known)
            for declared in (True, False):
                issue, = validate._check_team_list(SimpleNamespace(
                    matches=[played], club=None, competition=SimpleNamespace(
                        id="c", teams=dict.fromkeys(known),
                        teams_declared=declared, rounds={})))
                # The question alone, not the remedy after it (4.239).
                asked = issue.message.partition(" Did you mean")[2].partition("?")[0]
                if re.findall(r"[a-z]+(?:-[a-z]+)+", asked) != re.findall(
                        r"\(([^)]+)\)", said):
                    disagree.append((key, declared, asked, said))
        self.assertEqual(disagree, [])

    def test_a_banner_nearest_a_side_of_its_own_club_is_asked_about_no_other_club(
            self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=("zed-quill",), away_players=("yan-oss",),
                               rule=shape.set_rule) for slot in shape.slots)
        # kenmore-4 is one edit from its own club's kenmore-3 and two from
        # kenmure-3; hilltop-c one from hilltop-a and hilltop-b, two from
        # hilltops-a. Both may be a side the club has and the list has not.
        for key, known in (("kenmore-4", ("kenmore-3", "kenmure-3", "wrens")),
                           ("hilltop-c", ("hilltop-a", "hilltop-b", "hilltops-a",
                                          "wrens"))):
            names = {slug: slug.title() for slug in known}
            self.assertEqual(discover_mod._did_you_mean(key, names), "", key)
            played = Match(competition="c", round="4", home=key, away="wrens",
                           fmt=shape, rules=scoring.ruleset("games-bonus"), sets=sets)
            for declared in (True, False):
                with self.subTest(key=key, declared=declared):
                    issue, = validate._check_team_list(SimpleNamespace(
                        matches=[played], club=None, competition=SimpleNamespace(
                            id="c", teams=dict.fromkeys(names),
                            teams_declared=declared, rounds={})))
                    self.assertNotIn("Did you mean", issue.message)


def one_edit_slips(word: str, alphabet: str) -> set[str]:
    """Every spelling one insertion, deletion, substitution or swap from *word*."""
    out: set[str] = set()
    for i in range(len(word) + 1):
        out.update(word[:i] + c + word[i:] for c in alphabet)
        if i < len(word):
            out.add(word[:i] + word[i + 1:])
            out.update(word[:i] + c + word[i + 1:] for c in alphabet)
        if i < len(word) - 1:
            out.add(word[:i] + word[i + 1] + word[i] + word[i + 2:])
    return out


class BannerCase(CliCase):
    """The suite's season with the Rockets and the Aces printed as sides of clubs,
    and a round-four card against the Spinners under the banner a test gives."""

    COMP = "tuesday-division-b"
    TWO_SIDES = ("Hilltop A", "Hilltop B", "Lakeside Spinners", "Parkview Wanderers")
    ONE_SIDE = ("Hilltop A", "Kenmore 3", "Lakeside Spinners", "Parkview Wanderers")
    KENMURE = ("Hilltop A", "Kenmure 3", "Lakeside Spinners", "Parkview Wanderers")
    THURSDAY = "thursday-division-c"

    def banner_run(self, banner: str, *, teams: tuple[str, ...] | None,
                   expect: int, thursday: bool | None = None) -> Run:
        """``build.py`` over the season, the list declared as *teams* or not at all.

        The Rockets and the Aces are printed as the first two of *teams*. With
        *thursday*, Division C plays two Thursdays beside it, Kenmore 4 against the
        Owls, with its list declared if *thursday* is true.
        """
        shutil.rmtree(self.cwd / "data")
        data = self.cwd / "data"
        sides = teams[:2] if teams else self.TWO_SIDES
        write_season_cards(data, banners={"riverside-rockets": sides[0].upper(),
                                          "hilltop-aces": sides[1].upper()})
        if thursday is not None:
            self.thursday_cards(data / "Thursday")
        away_rows, away_on_court = squad_for("lakeside-spinners",
                                             TEAMS["lakeside-spinners"][1])
        home_rows, home_on_court = squad_for("hilltop",
                                             ("Mo Tran", "Ned Oake", "Pia Lund"))
        (data / "Round4").mkdir()
        cardwriter.write_card_file(data / "Round4" / "four.pdf", cardwriter.CardSpec(
            date="2026-09-08", round_label="4", division="B", court="09",
            match_id="4090001", home_name=banner, away_name="LAKESIDE SPINNERS",
            rows=rows_for(((6, 1), (6, 2), (6, 0), (6, 3)), home_on_court,
                          away_on_court),
            home_roster=home_rows, away_roster=away_rows))
        if teams:
            listed = ", ".join(f'"{team}"' for team in teams)
            (self.cwd / "config.toml").write_text(
                f"[competitions.{self.COMP}]\nday = \"Tuesday\"\ndivision = \"B\"\n"
                f"teams = [{listed}]\n" + (
                    f"[competitions.{self.THURSDAY}]\nday = \"Thursday\"\n"
                    f"division = \"C\"\nteams = [\"Kenmore 4\", \"Oakdale Owls\"]\n"
                    if thursday else ""), encoding="utf-8")
        run = self.build(expect=expect)
        self.assertLessEqual(max(map(len, run.out.splitlines())), 78)
        return run

    @staticmethod
    def thursday_cards(folder: Path) -> None:
        """Division C's two Thursdays, Kenmore 4 and the Owls, players of their own."""
        kenmore = squad_for("kenmore-4", ("Ula Brand", "Vic Corell", "Wes Dunmore"))
        owls = squad_for("oakdale-owls", ("Xan Elkin", "Yul Farrow", "Zia Gorse"))
        folder.mkdir(parents=True)
        for rnd, date_, (home_name, home), (away_name, away) in (
                ("1", "2026-08-20", ("KENMORE 4", kenmore), ("OAKDALE OWLS", owls)),
                ("2", "2026-08-27", ("OAKDALE OWLS", owls), ("KENMORE 4", kenmore))):
            cardwriter.write_card_file(folder / f"c-r{rnd}.pdf", cardwriter.CardSpec(
                date=date_, round_label=rnd, division="C", court=f"2{rnd}",
                match_id=f"500000{rnd}", home_name=home_name, away_name=away_name,
                rows=rows_for(((6, 1), (6, 2), (2, 6), (6, 3)), home[1], away[1]),
                home_roster=home[0], away_roster=away[0]))

    def f8(self, run: Run) -> str:
        return flat(" ".join(printed_finding(self, run.out, "F8")))


class TestATagOutsideItsClubsSchemeIsNoSideOfTheClub(BannerCase):
    """A tag or a number outside a club's own scheme is asked about the club's side.

    ``discover._siblings`` took any trailing tag of one or two characters for another
    side of the club, and any digit anywhere for a side's number, so
    ``discover.nearest_team``, the one rule F8, the page and discovery's note ask,
    asked nothing of such a banner. Measured before, through ``build.py`` on the
    season with the Rockets and the Aces printed HILLTOP A and KENMORE 3, those two,
    the Spinners and the Wanderers declared, and a round-four card against the
    Spinners bannered HILLTOP AA (/tmp/t7/scratch/TL/probe/before-builds.txt): exit
    1, and F8 said ``'hilltop-aa' plays in R4 hilltop-aa v lakeside-spinners but is
    not in the declared team list for tuesday-division-b.`` and asked nothing, nor
    did the page; so for HILLTOP 1 beside Hilltop A and KENMORE E beside Kenmore 3.
    Over the 2,903 one-edit slips in letters and ``-`` of Hilltop A, Hilltop B, the
    Spinners and the Wanderers, and ``hilltop``, 125 were asked nothing: ``hilltop``,
    the 24 other one-letter tags, and 100 two-letter tags. Over the 3,993 slips with
    digits too, 705 were asked nothing, 580 of them for a digit, ``1lakeside-spinners``
    and ``hill1top-a`` among them (/tmp/t7/scratch/TL/probe/before-6.txt).

    So a side is taken to be one only in the club's own scheme: a tag of the same
    shape as the side's, a letter beside a letter, two beside two, a letter and a
    number beside a letter and a number; a number beside a number in the same place,
    of any length, because numbered sides run past nine and ``kenmore-33`` beside
    ``kenmore-3`` may be a thirty-third; and any tag beside a side printed with none,
    as 4.142 left ``hilltop`` beside Hilltop A and Hilltop B. A two-letter tag beside
    a one-letter side is never a side: a club that letters its sides adds no side AA.
    Rejected: any short tail as a side's tag, and any digit as a side's number, as
    before, which read a letter doubled or a digit struck by mistake as evidence of a
    side nobody declared, and silenced the one question that finds the slip.
    """

    def test_a_doubled_letter_beside_a_clubs_one_side_is_asked_about_it(self):
        run = self.banner_run("HILLTOP AA", teams=self.ONE_SIDE, expect=1)
        self.assertIn(f"'hilltop-aa' plays in R4 hilltop-aa v lakeside-spinners but "
                      f"is not in the declared team list for {self.COMP}. Did you "
                      f"mean hilltop-a?", self.f8(run))
        self.assertEqual(
            [warning for match in self.season(self.COMP)["matches"]
             for warning in match.get("warnings") or ()
             if "is not one of the teams declared" in warning],
            [f"'HILLTOP AA' is not one of the teams declared for {self.COMP}. Did you "
             f"mean 'Hilltop A' (hilltop-a)?"])

    def test_a_tag_of_another_shape_than_the_sides_is_asked_about_the_side(self):
        for key, side in (("hilltop-aa", "hilltop-a"), ("hilltop-ab", "hilltop-a"),
                          ("hilltop-1", "hilltop-a"), ("hilltop-12", "hilltop-a"),
                          ("hilltop-a1", "hilltop-a"), ("hilltop-a", "hilltop-aa"),
                          ("hilltop-a1", "hilltop-1a"),
                          ("kenmore-e", "kenmore-3"), ("kenmore-3a", "kenmore-3")):
            with self.subTest(key=key, side=side):
                self.assertEqual(discover_mod.nearest_team(
                    key, [side, "lakeside-spinners"]), [side])

    def test_a_digit_struck_by_mistake_is_no_sides_number(self):
        for key, side in (("1lakeside-spinners", "lakeside-spinners"),
                          ("lakeside-spinners1", "lakeside-spinners"),
                          ("hill1top-a", "hilltop-a"), ("ken3more-3", "kenmore-3")):
            with self.subTest(key=key):
                self.assertEqual(discover_mod.nearest_team(
                    key, [side, "parkview-wanderers"]), [side])

    def test_a_side_in_the_clubs_own_scheme_is_still_asked_nothing(self):
        for key, known in (("hilltop-b", ["hilltop-a"]),
                           ("hilltop-c", ["hilltop-a", "hilltop-b"]),
                           ("hilltop-ac", ["hilltop-ab"]),
                           ("hilltop-2b", ["hilltop-2a"]),
                           ("kenmore-4", ["kenmore-3"]),
                           ("kenmore-33", ["kenmore-3"]),
                           ("kenmore-12", ["kenmore-1"]),
                           ("kenmore-4-mixed", ["kenmore-3-mixed"]),
                           ("hilltop", ["hilltop-a", "hilltop-b"]),
                           ("kenmore", ["kenmore-3"]),
                           ("riverside-rockets-b", ["riverside-rockets"])):
            with self.subTest(key=key):
                self.assertEqual(discover_mod.nearest_team(
                    key, [*known, "lakeside-spinners"]), [])

    def test_of_every_slip_beside_two_lettered_sides_only_their_letters_go_unasked(
            self):
        from matchcentre.slugs import slugify
        known = ["hilltop-a", "hilltop-b", "lakeside-spinners", "parkview-wanderers"]
        alphabet = "abcdefghijklmnopqrstuvwxyz0123456789-"
        keys = {"hilltop"}.union(*(one_edit_slips(slug, alphabet) for slug in known))
        keys = sorted(key for key in keys - set(known)
                      if key and slugify(key) == key)
        self.assertEqual(len(keys), 3993)
        unasked = [key for key in keys if not discover_mod.nearest_team(key, known)]
        self.assertEqual(unasked, ["hilltop"] + [f"hilltop-{letter}"
                                                 for letter in "cdefghijklmnopqrstuvwxyz"])


class TestADerivedListPairsABannerWithTheTeamNearestItAlone(BannerCase):
    """With no list declared, a banner is paired with the team nearest it, by F8's rule.

    ``discover._lookalike_notes`` paired two banners when either was within two edits
    of the other (``slugs.near_misses``), less siblings, where F8 and discovery's
    note under a declared list ask ``discover.nearest_team``, the nearest alone.
    Measured before, through ``build.py`` on the season with the Rockets and the Aces
    printed HILLTOP A and HILLTOP B, nothing declared, and a round-four card against
    the Spinners bannered HILTOP A (/tmp/t7/scratch/TL/probe/before-builds.txt): exit
    0 and two notes for the one banner, ``'HILLTOP A' (3 cards) and 'HILTOP A' (1
    card) are within a character or two of each other`` and the same of 'HILLTOP B',
    two edits off. Over the 2,903 one-edit slips of the four slugs and ``hilltop``,
    beside the four, the note paired 840 with two or more teams, and paired
    differently from ``nearest_team`` for all 840.

    So two banners are paired when one is the other's ``nearest_team`` among the
    rest, the one rule for a banner, which leaves each slip its nearest team alone
    and a side of the club none. Rejected: every banner within two edits, as before,
    which asked a club with HILTOP A on a card whether Hilltop B was meant too.
    """

    def test_a_misspelt_banner_is_paired_with_the_team_it_is_nearest_alone(self):
        run = self.banner_run("HILTOP A", teams=None, expect=0)
        self.assertEqual(
            [note for note in report_notes(run.out) if "'HILTOP A'" in note],
            [f"{self.COMP}: 'HILLTOP A' (3 cards) and 'HILTOP A' (1 card) are within "
             f"a character or two of each other, so one of them may be a misspelt "
             f"banner that has become a team of its own. If it is, add hilltop-a = "
             f"hiltop-a (or the other way round) under [aliases]; if they are two "
             f"real teams, declaring teams under [competitions.{self.COMP}] stops "
             f"the question being asked."])

    def test_every_slip_is_paired_with_the_teams_nearest_team_gives_it(self):
        from collections import Counter
        from matchcentre.slugs import slugify
        known = ["hilltop-a", "hilltop-b", "lakeside-spinners", "parkview-wanderers"]
        keys = {"hilltop"}.union(*(one_edit_slips(slug, "abcdefghijklmnopqrstuvwxyz-")
                                   for slug in known))
        keys = sorted(key for key in keys - set(known)
                      if key and slugify(key) == key)
        self.assertEqual(len(keys), 2903)
        differ = []
        for key in keys:
            printed = {slug: slug for slug in (*known, key)}
            notes = discover_mod._lookalike_notes(
                "c", printed, Counter(dict.fromkeys(printed, 1)))
            paired = sorted(slug for slug in known
                            if any(f"'{slug}'" in note and f"'{key}'" in note
                                   for note in notes))
            if paired != discover_mod.nearest_team(key, known):
                differ.append((key, paired))
        self.assertEqual(differ, [])

    def test_two_sides_of_a_club_are_paired_with_nothing(self):
        from collections import Counter
        printed = {"hilltop-a": "HILLTOP A", "hilltop-b": "HILLTOP B",
                   "kenmore-3": "KENMORE 3", "kenmore-33": "KENMORE 33",
                   "hilltop": "HILLTOP"}
        self.assertEqual(discover_mod._lookalike_notes(
            "c", printed, Counter(dict.fromkeys(printed, 2))), [])

    def test_a_slip_is_paired_with_its_team_though_the_team_has_a_nearer_side(self):
        from collections import Counter
        # HILTOPA is two edits from Hilltop A and three from Hilltop B, and Hilltop A
        # is one from Hilltop B, its own other side: the slip's nearest is Hilltop A
        # and Hilltop A's is no slip. Pairing only two banners each nearest the
        # other would leave the one a declared list's F8 asks about unnamed. The
        # slip on more cards than the team is paired all the same: the cards a
        # banner is on say which spelling the club uses, not which is nearest.
        printed = {"hilltop-a": "HILLTOP A", "hilltop-b": "HILLTOP B",
                   "hiltopa": "HILTOPA"}
        for cards, said in ((1, "1 card"), (5, "5 cards")):
            with self.subTest(slip_on=cards):
                notes = discover_mod._lookalike_notes("c", printed, Counter(
                    {"hilltop-a": 3, "hilltop-b": 3, "hiltopa": cards}))
                self.assertEqual([note.partition(" are within")[0] for note in notes],
                                 [f"c: 'HILLTOP A' (3 cards) and 'HILTOPA' ({said})"])


class TestABannerTheDeclaredListLacksIsReportedOnceByF8WithItsLine(BannerCase):
    """F8 alone reports a banner the declared list lacks, and hands over the line.

    Discovery wrote a note for every banner a declared list lacked, and F8 an error
    for the same team, so one mistake was reported twice with two questions and two
    remedies. Measured before, through ``build.py`` on the season with the Rockets and
    the Aces printed HILLTOP A and HILLTOP B, the four teams declared, and a
    round-four card against the Spinners bannered HILTOP A
    (/tmp/t7/scratch/TL/probe/before-builds2.txt): exit 1, 162 lines, and the report
    asked ``Did you mean`` twice, in the note ``a card names 'HILTOP A', which is not
    in the declared team list. Did you mean 'Hilltop A' (hilltop-a)? ... An [aliases]
    entry hiltop-a = <the right slug> is the one-line version.`` and in F8, ``Did
    you mean hilltop-a?`` with no remedy at all. The note also said the team's matches
    sat outside the ladder, where the Spinners were credited with theirs. Under
    ``--quiet`` the note went and F8 stayed, so the club told the least was told no
    remedy.

    So F8 owns the banner: it is an error, it reaches season.json and the page, and
    ``--quiet`` keeps it, where a note does none of these. It keeps its question and
    gains the remedy, a line to paste when one team is nearest, keyed and valued by
    ``config.toml_key`` and ``toml_value``. Pasted, the line builds clean with
    Hilltop A under its own slug; swapped, ``"hilltop-a" = "hiltop-a"``, it builds
    clean too, with Hilltop A's four matches filed under ``hiltop-a``
    (/tmp/t7/scratch/TL/probe/swap.txt), so a clean build is not enough to hold the
    line to its direction, and the teams are read as well. The note is dropped, not
    kept as a pointer: a pointer is a second line about one mistake. The page's
    warning on the match is kept, a reader's note on the card itself. Rejected: the
    note owning the banner, which leaves the report's one error without its remedy
    and the page with neither.

    No line is offered where pasting it would do more than the message says. The
    first fix offered one for every banner, and ``[aliases]`` folds a slug on every
    card of every competition. Measured on it, through ``build.py`` with Division C,
    Kenmore 4 one of its teams, beside a Division B whose list has Kenmure 3 and whose
    round-four card is bannered KENMORE 4 (/tmp/t7/scratch/TL/fixup/club3-before.txt,
    club2-before.txt): F8 said ``kenmore-4 = "kenmure-3" under [aliases] is the
    one-line fix``, and pasted, the build exited 0 with Division C's Kenmore 4 filed
    under ``kenmure-3``, and nothing said so, whether C's list was declared or read
    off its cards. So a banner that is a team of another competition the club runs is
    told so, and why no line is offered. And where no team is nearest, or two are,
    the first fix gave the line's shape, ``hilltop = "<the declared team it is>"``,
    and called it the one-line fix; filled in with the only team near, it did the
    same to a Kenmore 4 beside Kenmore 3 (club-before.txt). The cards do not say
    which team such a banner is, if it is any, and a side of the club is asked
    nothing for that reason (``discover.nearest_team``), so the message says what
    ``[aliases]`` would do and that no line is offered, as the house says of two
    players whose right spelling the cards do not give. Rejected: the line whatever
    else the slug names, and the placeholder.
    """

    def test_a_misspelt_banner_is_asked_one_question_by_f8_alone(self):
        run = self.banner_run("HILTOP A", teams=self.TWO_SIDES, expect=1)
        self.assertEqual(flat(run.out).count("Did you mean"), 1, run.out)
        self.assertEqual([note for note in report_notes(run.out)
                          if "HILTOP A" in note or "hiltop-a" in note], [])
        remedy = (f"'hiltop-a' plays in R4 hiltop-a v lakeside-spinners but is not in "
                  f"the declared team list for {self.COMP}. Did you mean hilltop-a? "
                  f"Either the banner or the list is wrong; if it is the banner, "
                  f"hiltop-a = \"hilltop-a\" under [aliases] is the one-line fix.")
        self.assertIn(remedy, self.f8(run))
        self.assertEqual([issue["message"] for issue in
                          self.season(self.COMP)["validation"]["errors"]
                          if issue["rule"] == "F8"], [remedy])

    def test_the_line_f8_hands_over_is_the_line_that_clears_it(self):
        run = self.banner_run("HILTOP A", teams=self.TWO_SIDES, expect=1)
        line, = re.findall(r"if it is the banner, (\S+ = \"[^\"]+\") under \[aliases\]",
                           self.f8(run))
        with (self.cwd / "config.toml").open("a", encoding="utf-8") as config:
            config.write(f"\n[aliases]\n{line}\n")
        again = self.build(expect=0)
        self.assertNotIn("F8", again.out)
        self.assertNotIn("not in the declared team list", flat(again.out))
        self.assertEqual({team["slug"]: team["played"]
                          for team in self.season(self.COMP)["teams"]},
                         {"hilltop-a": 4, "hilltop-b": 3, "lakeside-spinners": 4,
                          "parkview-wanderers": 3})

    NO_LINE = ("Either the banner or the list is wrong; if it is the banner, "
               "[aliases] files it under the declared team it is, and the cards do "
               "not say which that is, so no line is offered.")

    def test_a_banner_near_no_one_team_is_offered_no_line(self):
        run = self.banner_run("HILLTOP", teams=self.TWO_SIDES, expect=1)
        self.assertNotIn("Did you mean", flat(run.out))
        self.assertEqual([note for note in report_notes(run.out)
                          if "HILLTOP" in note and "declared" in note], [])
        self.assertIn(f"'hilltop' plays in R4 hilltop v lakeside-spinners but is not in "
                      f"the declared team list for {self.COMP}. {self.NO_LINE}",
                      self.f8(run))

    def test_a_tie_is_offered_no_line_and_a_derived_list_none(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=("zed-quill",), away_players=("yan-oss",),
                               rule=shape.set_rule) for slot in shape.slots)
        played = Match(competition="c", round="4", home="rickets", away="wrens",
                       fmt=shape, rules=scoring.ruleset("games-bonus"), sets=sets)
        said = {}
        for declared in (True, False):
            issue, = validate._check_team_list(SimpleNamespace(
                matches=[played], club=None, competition=SimpleNamespace(
                    id="c", teams=dict.fromkeys(("rackets", "rockets", "wrens")),
                    teams_declared=declared, rounds={})))
            said[declared] = issue.message.partition("?")[2]
        self.assertEqual(said, {True: f" {self.NO_LINE}", False: ""})

    def test_a_banner_another_competition_has_for_a_team_is_offered_no_line(self):
        for declared in (True, False):
            with self.subTest(thursday_declared=declared):
                run = self.banner_run("KENMORE 4", teams=self.KENMURE, expect=1,
                                      thursday=declared)
                told = (f"'kenmore-4' plays in R4 kenmore-4 v lakeside-spinners but is "
                        f"not in the declared team list for {self.COMP}. Did you mean "
                        f"kenmure-3? Either the banner or the list is wrong. No "
                        f"[aliases] line is offered: kenmore-4 is also a team of "
                        f"{self.THURSDAY}, and [aliases] applies to every competition, "
                        f"so a line filing it here would refile it there. If it is the "
                        f"banner, correct the card in Match Centre and export it again.")
                self.assertEqual([issue["message"] for issue in
                                  self.season(self.COMP)["validation"]["errors"]
                                  if issue["rule"] == "F8"], [told])
                self.assertIn(told, flat(run.out))
                self.assertNotIn("one-line fix", flat(run.out))
                self.assertIn("kenmore-4", {team["slug"] for team in
                                            self.season(self.THURSDAY)["teams"]})

    def test_a_slug_other_competitions_have_is_offered_no_line_however_near(self):
        from types import SimpleNamespace
        from matchcentre import validate
        from matchcentre.model import Match, SetResult
        shape = fmt_mod.match_format("doubles-singles-doubles")
        sets = tuple(SetResult(slot=slot, home_games=6, away_games=2,
                               home_players=("zed-quill",), away_players=("yan-oss",),
                               rule=shape.set_rule) for slot in shape.slots)
        here = SimpleNamespace(id="c", teams_declared=True, teams=dict.fromkeys(
            ("kenmure-3", "rackets", "rockets", "wrens")), rounds={})
        # One team nearest, two as near, and none: the other competitions decide
        # first, their lists declared or, as last season's is, derived.
        for slug in ("kenmore-4", "rickets", "wombles"):
            with self.subTest(slug=slug):
                club = SimpleNamespace(competitions=(
                    here,
                    SimpleNamespace(id="thursday-division-c", teams={slug: None},
                                    teams_declared=True),
                    SimpleNamespace(id="friday-division-a", teams={"wrens": None},
                                    teams_declared=True),
                    SimpleNamespace(id="2025-tuesday-division-b", teams={slug: None},
                                    teams_declared=False)))
                played = Match(competition="c", round="4", home=slug, away="wrens",
                               fmt=shape, rules=scoring.ruleset("games-bonus"),
                               sets=sets)
                issue, = validate._check_team_list(SimpleNamespace(
                    matches=[played], club=club, competition=here))
                self.assertEqual(
                    issue.message.partition(" the list is wrong")[2],
                    f". No [aliases] line is offered: {slug} is also a team of "
                    f"2025-tuesday-division-b and thursday-division-c, and [aliases] "
                    f"applies to every competition, so a line filing it here would "
                    f"refile it there. If it is the banner, correct the card in Match "
                    f"Centre and export it again.")


class TestTheFolderRuleAndTheArgumentRuleAreOneRule(unittest.TestCase):
    """The name ``--only`` takes is turned into a season key by the router's own
    function, so the two cannot come to disagree.

    Compared as typed, ``--only 2026-Winter`` would name no season, although the
    router files ``data/2026-Winter/`` as ``2026-winter`` and the picker shows it
    so. A second slugify in build.py was the other way to agree today, and the way to
    disagree the first time either copy is changed.
    """

    TABLE = (("2026-Winter", "2026-winter"), (" 2026 winter ", "2026-winter"),
             ("Été 2026", "ete-2026"), ("!!!", ""), ("", ""))

    def test_a_folder_name_becomes_the_key_the_router_files_it_under(self):
        for name, key in self.TABLE:
            with self.subTest(name=name):
                self.assertEqual(discover_mod.season_key_of_folder(name), key)

    def test_a_card_under_each_folder_is_filed_by_that_rule(self):
        from matchcentre.card import Card
        root = Path("data")
        for name, key in self.TABLE[:4]:
            with self.subTest(name=name):
                source = str(root / name / "Round1" / "card.pdf")
                card = Card(source=source, page=0, date="2026-08-18")
                filed = discover_mod.season_key_for(card, root=root, multi=True)
                self.assertEqual(discover_mod.season_key_of_path(source, root=root),
                                 key)
                # A folder with nothing to slug falls back to the card's year, as
                # it did before the rule moved.
                self.assertEqual(filed, key or "2026")

    def test_a_card_directly_in_the_folder_has_no_folder_key(self):
        self.assertEqual(discover_mod.season_key_of_path("data/card.pdf",
                                                         root=Path("data")), "")

    def test_seasons_are_ordered_the_way_the_front_page_orders_them(self):
        keys = ["season-10", "2026-winter", "season-2", "2025-winter", "2026-summer"]
        self.assertEqual(sorted(keys, key=site.season_order_key),
                         ["2025-winter", "2026-summer", "2026-winter", "season-2",
                          "season-10"])


class TestEveryNoteSaysWhichSeasonItBelongsTo(OnlyCase):
    """A discovery note carries its season from where it is made.

    Notes are the longest part of the cards section: measured on four demo seasons
    in /tmp/t4/scratch/y88/m4, 134 of its 142 lines, 26 notes, six for each
    competition on every run. A note is prose and a string cannot be traced back to
    its season, so leaving notes unnarrowed and reading the season out of the text
    were the alternatives, and a list built beside the notes was the third: two lists
    that have to stay in step are two lists that one day do not.
    """

    def discovered(self, where: Path):
        cfg = config_mod.load(where / "config.toml")
        cards, rejected = scorecard.read_tree(where / "data",
                                              expect=cfg.declared_format())
        return discover_mod.discover(cards, rejected, config=cfg, root=where / "data")

    def test_each_note_is_tagged_with_the_season_it_is_about(self):
        # One card whose printed weekday its date contradicts, so that the third
        # place notes are made -- the day disputes -- has a note to tag as well.
        cardwriter.write_card_file(
            self.cwd / "data" / self.ARCHIVE / "wrong-night.pdf",
            cardwriter.CardSpec(when="Wed 18/08/2026 7:00 PM"))
        found = self.discovered(self.cwd)
        self.assertEqual(len(found.note_seasons), len(found.notes))
        tags = dict(zip(found.notes, found.note_seasons))
        by_id = {c.id: c.season_key for c in found.club.competitions}
        for note, tag in tags.items():
            with self.subTest(note=note[:60]):
                self.assertTrue(tag is None or tag in found.club.season_keys, tag)
                named = [cid for cid in by_id if note.startswith(f"{cid}:")]
                if named:
                    self.assertEqual(tag, by_id[named[0]])
        dispute = [n for n in found.notes if "but the card prints" in n]
        self.assertEqual(len(dispute), 1, found.notes)
        self.assertEqual(tags[dispute[0]], self.ARCHIVE)
        run_wide = [n for n in found.notes if n.startswith("Seasons are the folder")]
        self.assertEqual([tags[n] for n in run_wide], [None])

    def test_a_note_with_no_tag_is_shown_whatever_the_scope(self):
        from matchcentre.scope import Scope
        found = discover_mod.Discovery(
            club=Club(name="Example"), matches={}, cards={}, rejected=[],
            notes=["one", "two"], club_name="Example")
        self.assertEqual(build_mod._listed_notes(found, Scope(("a",))),
                         (["one", "two"], []))

    def test_a_hidden_note_is_counted_even_with_no_competition_to_hide(self):
        # A card whose competition was dropped at the filing can still leave a note
        # tagged with its season. Hidden and not counted, it would be a line of the
        # report that is simply gone.
        from matchcentre.scope import Scope
        found = discover_mod.Discovery(
            club=Club(name="Example"), matches={}, cards={}, rejected=[],
            notes=["shown", "hidden"], club_name="Example",
            note_seasons=(None, self.ARCHIVE))
        report = build_mod._Report()
        build_mod._not_listed_section(
            report, args=argparse.Namespace(data=Path("data"), out=Path("site"),
                                            config=Path("config.toml")),
            seasons=[], found=found, cfg=config_mod.load(Path("nonexistent.toml")),
            scope=Scope((self.WINTER,)), written=None)
        text = report.render(quiet=False)
        # The season is counted in the heading too. Counted from the competitions
        # hidden alone, it would read "in 0 other season(s)" over a line naming one,
        # and no test said otherwise (/tmp/t4/scratch/y88-review/mut/run.py R3).
        self.assertEqual(self.headings(text),
                         ["not listed: 0 competition(s) in 1 other season(s)"])
        self.assertRegex(text, r"notes +1\n")
        self.assertRegex(text, rf"seasons +{self.ARCHIVE}\n")

    def test_the_run_leaves_out_another_seasons_notes_and_counts_them(self):
        full = self.build_in(self.copy("full"))
        scoped = self.build("--only", self.WINTER)
        other = f"note: {self.comp(self.ARCHIVE)}:"
        self.assertIn(other, full.out)
        self.assertNotIn(other, scoped.out)
        # The run-wide notes are about every season, and stay.
        self.assertIn("note: Seasons are the folder names", scoped.out)
        hidden = (self.section(full.out, "cards").count("  note: ")
                  - self.section(scoped.out, "cards").count("  note: "))
        self.assertGreater(hidden, 0)
        self.assertRegex(self.section(scoped.out, "not listed"),
                         rf"\n  notes +{hidden}\n")


class TestOnlyChangesNoFileTheRunWrites(OnlyCase):
    """``build.py --only X`` writes exactly the bytes ``build.py`` writes.

    Narrowing the reading or the writing was measured and rejected: on four demo
    seasons in /tmp/t4/scratch/y88/m4, one refused card in the oldest season
    rewrote files in every season, so a season's document depends on the whole run,
    and an ``--only`` run that read one season would write a different document
    than the full run beside it -- and every run after that would rewrite it back.
    """

    def test_the_site_and_the_config_are_byte_for_byte_the_full_runs(self):
        plain = self.build_in(self.copy("plain"))
        scoped = self.build("--only", self.WINTER)
        self.assertEqual(scoped.code, plain.code)
        self.assertEqual(self.tree(self.cwd), self.tree(plain.cwd))
        self.assertIn(self.SUMMER, (self.cwd / "site" / "index.html").read_text(
            encoding="utf-8"))
        self.assertEqual((self.cwd / "config.toml").read_bytes(),
                         (plain.cwd / "config.toml").read_bytes())
        self.assertEqual(self.section(scoped.out, "result"),
                         self.section(plain.out, "result"))

    def test_alternating_with_and_without_it_rewrites_nothing(self):
        self.build("--only", self.WINTER)
        stamps = {p: p.stat().st_mtime_ns for p in (self.cwd / "site").rglob("*")
                  if p.is_file()}
        for argv in (("--only", self.WINTER), ()):
            with self.subTest(argv=argv):
                run = self.build(*argv)
                self.assertIn("wrote        nothing:", self.section(run.out, "result"))
        self.assertEqual({p: p.stat().st_mtime_ns for p in stamps}, stamps)


class TestUnderQuietOnlyChangesNoLineOfTheReport(OnlyCase):
    """Everything ``--only`` leaves out is something ``--quiet`` already leaves out.

    So ``--quiet --only`` prints what ``--quiet`` prints, on a run with a refused
    card, a validation error and a fixture gone, each in a season it does not list:
    the proof that nothing loud is hidden. Marking the ``only`` field or the "not
    listed" counts ``always`` was the alternative, and it would make a quiet run
    longer for saying less.
    """

    def test_a_failing_run_prints_the_same_quiet_report_either_way(self):
        # In one folder, the one run after the other: from outside the project the
        # doctor's line under the refused card goes there first and names the card
        # in full, so two folders would be two reports.
        runs = []
        for argv in ((), ("--only", self.SUMMER)):
            where = self.copy("run")
            self.break_two_seasons(where)
            self.build_in(where, expect=1)
            (where / "data" / self.WINTER / "Round3"
             / "HilltopAces-LakesideSpinners.pdf").unlink()
            runs.append(self.build_in(where, "--quiet", *argv, expect=1))
            shutil.rmtree(where)
        plain, scoped = runs
        self.assertIn("gone", plain.out)
        self.assertIn("F9", plain.out)
        self.assertEqual(scoped.out, plain.out)
        self.assertEqual(scoped.err, plain.err)


class TestOnlyListsOneSeasonAndCountsTheRest(OnlyCase):
    """The report of a ten-season club was mostly about nine seasons nobody plays.

    Measured before, on four demo seasons in /tmp/t4/scratch/y88/m4: 724 lines, and
    every competition's block, review items, warnings and notes every run. ``--only``
    lists one season's and counts the others in one section, after the warnings and
    before the change report, so that the change report stays the last thing said
    about the figures and the dashboards left behind stay next to ``result``.
    """

    PER_COMPETITION = ("the team list for", "the season length for",
                       "the season name for", "the draw for", "the match format for")

    def runs(self) -> tuple[Run, Run]:
        return self.build_in(self.copy("full")), self.build("--only", self.WINTER)

    def test_no_other_seasons_competition_is_listed(self):
        full, scoped = self.runs()
        self.assertIn(self.comp(self.WINTER), self.headings(scoped.out))
        for season in (self.SUMMER, self.ARCHIVE):
            comp = self.comp(season)
            self.assertIn(comp, self.headings(full.out))
            self.assertNotIn(comp, self.headings(scoped.out))
            review = self.section(scoped.out, "review")
            for subject in self.PER_COMPETITION:
                self.assertNotIn(f"{subject} {comp}", review)
            self.assertNotIn(f"{comp}:", self.warnings(scoped.out))
            self.assertIn(f"{comp}:", self.warnings(full.out))

    def test_the_only_field_says_how_much_of_the_run_is_listed(self):
        _, scoped = self.runs()
        listed = len(self.cards_of(self.cwd, self.WINTER))
        total = len(sorted((self.cwd / "data").rglob("*.pdf")))
        self.assertIn(f"only 2026-winter: 1 of 3 competition(s), {listed} of {total} "
                      f"card(s) scored. Every season was read, checked and written; "
                      f"only this one is listed below, and the others are counted "
                      f'under "not listed".',
                      self.flat(self.section(scoped.out, "cards")))

    def test_the_rest_are_counted_under_not_listed(self):
        full, scoped = self.runs()
        counted = self.section(scoped.out, "not listed")
        self.assertIn("not listed: 2 competition(s) in 2 other season(s)", counted)
        self.assertRegex(counted, r"\n  seasons +2026-summer, 2025-winter\n")
        review = (self.counted(full.out, r"review: (\d+)")
                  - self.counted(scoped.out, r"review: (\d+)"))
        warnings = (self.counted(full.out, r"(\d+) warnings?$")
                    - self.counted(scoped.out, r"(\d+) warnings?$"))
        self.assertGreater(review, 0)
        self.assertGreater(warnings, 0)
        self.assertRegex(counted, rf"\n  review +{review} value\(s\) worked out, "
                                  rf"not declared\n")
        self.assertRegex(counted, rf"\n  warnings +{warnings}\n")
        self.assertIn("Their dashboards were written like every other, and anything "
                      "in them that fails the run is listed above. Run without --only "
                      "to list these too.", self.flat(counted))

    def test_not_listed_comes_after_the_warnings_and_before_the_changes(self):
        self.build()
        self.cards_of(self.cwd, self.SUMMER)[0].unlink()
        run = self.build("--only", self.WINTER)
        order = [re.sub(r"^\d+ warnings?$", "warnings", h.split(":")[0])
                 for h in self.headings(run.out)]
        wanted = ("review", "warnings", "not listed", "since the last build", "result")
        self.assertEqual([h for h in order if h in wanted], list(wanted))


class TestAFailureInAnotherSeasonIsNeverHidden(OnlyCase):
    """A refused card or a validation error is listed whatever ``--only`` names.

    They set the exit status, and the exit status is the whole run's, because the
    run writes every season: an ``--only 2026-summer`` run from a script of the
    club's own that went green over a site holding a refused 2025 card would be a
    green light over a wrong figure. Counting them without naming them was the
    alternative, and it costs the club a second run to find out what failed.
    """

    def test_the_refused_card_and_the_error_are_both_listed(self):
        plain = self.copy("plain")
        for where in (plain, self.cwd):
            self.break_two_seasons(where)
        full = self.build_in(plain, expect=1)
        # The precondition: the error really is in a season the scoped run hides.
        self.assertIn(f"{self.comp(self.WINTER)}:",
                      "\n".join(printed_finding(self, full.out, "F9")))
        scoped = self.build("--only", self.SUMMER, expect=1)
        self.assertIn("data/2025-winter/half.pdf", self.section(scoped.out, "refused"))
        self.assertIn(f"{self.comp(self.WINTER)}:",
                      "\n".join(printed_finding(self, scoped.out, "F9")))
        exit_line = [line for line in full.out.splitlines() if line.startswith("  exit ")]
        self.assertEqual([line for line in scoped.out.splitlines()
                          if line.startswith("  exit ")], exit_line)

    def test_a_season_whose_every_card_was_refused_can_still_be_named(self):
        """A season with no card scored has no competition, so only the folder its
        refused cards sit in says it exists.

        2026-summer, because config.toml does not name it. Written first against
        2025-winter, which config.toml labels, this passed with the refused cards
        never asked (/tmp/mutate124.py: SURVIVED). Knowing a season only from the
        cards scored was the alternative, and it refuses the season a club most
        needs to look at as a name that is not a season.
        """
        for card in self.cards_of(self.cwd, self.SUMMER):
            card.write_bytes(b"%PDF-1.4\n1 0 obj\n<<")
        run = self.build("--only", self.SUMMER, expect=1)
        self.assertIn("only 2026-summer: 0 of 2 competition(s)", self.flat(run.out))
        self.assertIn("data/2026-summer/", self.section(run.out, "refused"))


class TestTheChangeReportIsNeverNarrowed(OnlyCase):
    """What changed since the last build is listed from every season.

    A change is printed by the run that makes it and by no later run: the next
    run's "last build" no longer holds it. So a ``gone`` line left out by ``--only``
    would never be printed anywhere. Narrowing it was the alternative, and so was a
    new state file holding the changes a scoped run did not show, which is a second
    record of the figures beside the cards.
    """

    EVERY = ("Every season is in this section whatever --only says: a change is "
             "reported by the run that makes it and by no later run, so a line left "
             "out here would never be printed.")

    def test_a_fixture_gone_from_another_season_is_printed_once(self):
        loud = self.copy("loud")
        for where in (self.cwd, loud):
            self.build_in(where)
            self.cards_of(where, self.SUMMER)[0].unlink()
        run = self.build("--only", self.WINTER)
        changes = self.section(run.out, "since the last build")
        self.assertIn(f"  {self.comp(self.SUMMER)}\n", changes)
        self.assertIn("gone", changes)
        self.assertIn(self.EVERY, self.flat(changes))
        quiet = self.build_in(loud, "--quiet", "--only", self.WINTER)
        self.assertIn(f"  {self.comp(self.SUMMER)}\n", quiet.out)
        self.assertNotIn("whatever --only says", quiet.out)
        again = self.build("--only", self.WINTER)
        self.assertNotIn("since the last build", again.out)

    def test_a_change_inside_the_season_listed_needs_no_sentence(self):
        self.build()
        (self.cwd / "data" / self.WINTER / "Round3"
         / "HilltopAces-LakesideSpinners.pdf").unlink()
        run = self.build("--only", self.WINTER)
        self.assertIn(self.comp(self.WINTER), self.section(run.out, "since the last build"))
        self.assertNotIn("whatever --only says", run.out)


class TestAnOnlyRunThatWritesNothingGivesABuildsReasonForEverySeason(OnlyCase):
    """Why every season is listed, said of a run that made no change.

    Measured before (/tmp/t6/scratch/m6/before.txt): a withheld run refused for
    a name, with ``--only 2025-winter`` over a change to 2026-winter, printed
    "a change is reported by the run that makes it and by no later run, so a
    line left out here would never be printed". That run made no change, and the
    build after it prints the line, so the reason was untrue there and under
    ``--check``. The list is still every season's, because it is the list that
    build will print; only the reason is the run's. Rejected: narrowing the
    section on those runs, which would have a ``--check`` print a shorter list
    than the build it is checking.
    """

    WOULD = ("Every season is in this section whatever --only says, because a "
             "build writes every season and this is the list that build would "
             "print.")

    EVERY = TestTheChangeReportIsNeverNarrowed.EVERY
    # A title that is a player's full name in 2026-winter's cards, which the
    # guard refuses under withheld names: the run then writes nothing at all.
    REFUSED = ONLY_CONFIG.replace('seasons = "multi"\n',
                                  'seasons = "multi"\ntitle = "Kit Vasse Plate"\n')

    def test_a_check_run_gives_the_builds_reason(self):
        self.build()
        self.cards_of(self.cwd, self.SUMMER)[0].unlink()
        run = self.build("--check", "--only", self.WINTER)
        changes = self.flat(self.section(run.out, "changes a build would make"))
        self.assertIn(self.comp(self.SUMMER), changes)
        self.assertIn(self.WOULD, changes)
        self.assertNotIn("by no later run", changes)

    def test_a_refused_run_gives_the_builds_reason(self):
        """The run the row measured: not --check, and still no change made."""
        self.build()
        self.cards_of(self.cwd, self.SUMMER)[0].unlink()
        (self.cwd / "config.toml").write_text(self.REFUSED, encoding="utf-8")
        run = self.build("--players", "numbered", "--only", self.WINTER, expect=2)
        self.assertIn("== players: no dashboard written", run.out)
        changes = self.flat(self.section(run.out, "changes a build would make"))
        self.assertIn(self.comp(self.SUMMER), changes)
        self.assertIn(self.WOULD, changes)
        self.assertNotIn("by no later run", changes)

    def test_the_build_after_it_gives_the_reason_it_writes_by(self):
        """And the build, which is the run that makes the change, says so."""
        self.build()
        self.cards_of(self.cwd, self.SUMMER)[0].unlink()
        self.build("--check", "--only", self.WINTER)
        run = self.build("--only", self.WINTER)
        changes = self.flat(self.section(run.out, "since the last build"))
        self.assertIn(self.comp(self.SUMMER), changes)
        self.assertIn(self.EVERY, changes)
        self.assertNotIn(self.WOULD, changes)


class TestAWriteThatStopsPartWaySaysWhatItFinishedAsMade(OnlyCase):
    """A write that stopped part way said nothing it had finished as made.

    Measured (/tmp/t6/scratch/m6/probe8.impl.txt): the three seasons built, the
    first card of each removed, and 2026-summer's season.json made read-only.
    ``write_site`` goes one competition at a time, so 2025-winter's document was
    rewritten before 2026-summer's refused, and the run exited 2 with all three
    gone fixtures under ``changes a build would make``: 2025-winter's "would not
    be on the dashboard a build wrote", on a dashboard that already did not show
    it, and the run after it listed only the other two. With the front page
    read-only instead, every dashboard was written and every line was headed as a
    build's to make, and the run after it listed none of them. Three fixtures gone
    from the published site, and no run said so as done. Before 4.94
    (probe8.base.txt) the tree said all three as made, and the run after it listed
    two of them again.

    So the section is split by what the write reached, each document read back
    the way ``previous`` was read: what the run finished is said as made, once,
    and the rest is what a build would make, which is the list the next build
    prints as made. Rejected: one heading for the run, which is untrue of one half
    of it whichever it is; and working out what was finished from the error, which
    names only the file the write stopped at.

    Since 4.67 a read-only file is replaced like any other, so the write is stopped
    here by a folder at 2026-summer's season-data.js, the first file its dashboard
    writes, which leaves that season's season.json as the last build left it.
    """

    MADE = "since the last build"
    WOULD = "changes a build would make"
    WROTE_GONE = TestARunThatWritesNoDashboardSaysWhatABuildWouldChange.WROTE_GONE
    WOULD_GONE = TestARunThatWritesNoDashboardSaysWhatABuildWouldChange.WOULD_GONE

    def document(self, season: str) -> Path:
        return self.cwd / "site" / season / self.comp(season) / "season.json"

    def page_data(self, season: str) -> Path:
        return self.document(season).with_name("season-data.js")

    def stopped_at(self, locked: Path) -> tuple[Run, dict[str, bytes]]:
        """A card gone from every season, and a run whose write stops at *locked*.

        With the documents as they were before that run, so a test can say which
        of them it rewrote. Stopped by a folder at that name: since 4.67 a
        read-only file is replaced like any other.
        """
        self.build()
        for season in (self.ARCHIVE, self.SUMMER, self.WINTER):
            self.cards_of(self.cwd, season)[0].unlink()
        before = {season: self.document(season).read_bytes()
                  for season in (self.ARCHIVE, self.SUMMER, self.WINTER)}
        locked.unlink()
        locked.mkdir()
        try:
            run = self.build(expect=2)
        finally:
            locked.rmdir()
        self.assertIn("could not write the dashboard to site", run.out)
        return run, before

    def listed(self, run: Run, head: str) -> list[str]:
        """The competitions a section lists, in its order; none without it."""
        if f"== {head}" not in run.out:
            return []
        comps = {self.comp(season) for season in (self.ARCHIVE, self.SUMMER,
                                                  self.WINTER)}
        return [line.strip() for line in self.section(run.out, head).splitlines()
                if line.strip() in comps]

    def changes(self, run: Run, head: str) -> list[str]:
        """A section's list, without its heading and the paragraph under it."""
        lines = self.section(run.out, head).splitlines()[1:]
        cut = next(at for at, line in enumerate(lines)
                   if line.startswith("  A fixture listed as gone"))
        return [line for line in lines[:cut] if line.strip()]

    def test_what_it_finished_is_said_as_made_and_the_rest_as_a_builds(self):
        run, before = self.stopped_at(self.page_data(self.SUMMER))
        self.assertNotEqual(self.document(self.ARCHIVE).read_bytes(),
                            before[self.ARCHIVE],
                            "the write did not reach 2025-winter, so the fixture "
                            "cannot tell the two headings apart")
        self.assertEqual(self.document(self.SUMMER).read_bytes(),
                         before[self.SUMMER])
        self.assertEqual(self.document(self.WINTER).read_bytes(),
                         before[self.WINTER])
        self.assertEqual(self.listed(run, self.MADE), [self.comp(self.ARCHIVE)])
        self.assertEqual(self.listed(run, self.WOULD),
                         [self.comp(self.SUMMER), self.comp(self.WINTER)])
        # What is done, and then what is left, which is what the next build lists.
        self.assertLess(run.out.index(f"== {self.MADE}"),
                        run.out.index(f"== {self.WOULD}"))
        self.assertIn(self.WROTE_GONE, self.flat(self.section(run.out, self.MADE)))
        self.assertIn(self.WOULD_GONE, self.flat(self.section(run.out, self.WOULD)))

    def test_the_build_after_it_says_as_made_what_it_had_not_reached(self):
        """Every change said as made by one run: the one that made it."""
        stopped, _ = self.stopped_at(self.page_data(self.SUMMER))
        after = self.build()
        self.assertEqual(self.changes(after, self.MADE),
                         self.changes(stopped, self.WOULD))

    def test_a_write_that_stops_at_the_front_page_says_every_change_as_made(self):
        """The case that lost all three: every dashboard written, then the page."""
        run, before = self.stopped_at(self.cwd / "site" / "index.html")
        self.assertTrue(all(self.document(season).read_bytes() != before[season]
                            for season in before))
        self.assertEqual(self.listed(run, self.MADE),
                         [self.comp(season) for season in (self.ARCHIVE,
                                                           self.SUMMER,
                                                           self.WINTER)])
        self.assertNotIn(f"== {self.WOULD}", run.out)
        self.assertNotIn(f"== {self.MADE}", self.build().out)


class TestSingleSeasonModeRefusesOnlyBeforeReadingACard(OnlyCase):
    """In single-season mode there is no other season to leave out.

    Every card is one season, keyed by nothing. Ignoring the flag was the
    alternative, and it prints a report that looks narrowed and is not; so is
    treating the one season as a name, which nobody could type. Refused as soon as
    the config is read, before any card is.
    """

    ERROR = "error: --only needs multi-season mode, and this run is a single season"

    def test_with_no_config_file_it_says_there_is_none(self):
        (self.cwd / "config.toml").unlink()
        run = self.build("--only", self.WINTER, expect=2)
        self.assertEqual(run.err.splitlines()[0], self.ERROR)
        self.assertIn("There is no config.toml yet, and without one every card under "
                      "data/ is one season, so there is no other season to leave out. "
                      "Run it again without --only.", self.flat(run.err))
        self.assertFalse((self.cwd / "site").exists())
        self.assertFalse((self.cwd / "config.toml").exists())

    def test_with_a_single_season_config_it_names_the_setting(self):
        config = self.cwd / "config.toml"
        config.write_text('[build]\nseasons = "single"\n', encoding="utf-8")
        run = self.build("--only", self.WINTER, expect=2)
        self.assertEqual(run.err.splitlines()[0], self.ERROR)
        self.assertIn('config.toml does not set seasons = "multi" under [build], so '
                      'every card under data/ is one season', self.flat(run.err))
        self.assertIn('see "Several seasons" in README.md.', self.flat(run.err))
        self.assertFalse((self.cwd / "site").exists())
        self.assertEqual(config.read_text(encoding="utf-8"),
                         '[build]\nseasons = "single"\n')

    def test_the_refusal_comes_before_any_card_is_read(self):
        import contextlib
        import io
        (self.cwd / "config.toml").unlink()
        out, err = io.StringIO(), io.StringIO()
        with mock.patch.object(build_mod.scorecard, "read_tree",
                               side_effect=AssertionError("a card was read")), \
                contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = build_mod.main(["--data", str(self.cwd / "data"),
                                   "--out", str(self.cwd / "site"),
                                   "--config", str(self.cwd / "config.toml"),
                                   "--only", self.WINTER])
        self.assertEqual(code, 2)
        self.assertIn("needs multi-season mode", err.getvalue())


class TestAnUnknownSeasonIsRefusedWithTheSeasonsThatExist(OnlyCase):
    """A name that is not a season is refused, with the list of names that are.

    Narrowed to a season nothing is filed in, a report lists nothing and says
    nothing is wrong: absence of evidence printed as a clean week. Listing the
    folders under ``data/`` before reading was the alternative, and it misses a
    season keyed by its cards' year and can disagree with the router, so the check
    waits for the reading -- and comes before the config is rewritten or a file
    written.
    """

    def test_it_lists_the_seasons_newest_first_with_their_labels(self):
        run = self.build("--only", "2026-wintr", expect=2)
        self.assertEqual(run.err.rstrip("\n"), ONLY_REFUSAL)
        self.assertFalse((self.cwd / "site").exists())

    def test_it_is_refused_before_discover_rewrites_the_config(self):
        """A pin, and the one test of this item that passes on the tree before it:
        there argparse refused the flag before ``--discover`` could write. Once the
        flag is accepted it holds the order, because the name is checked after the
        cards are read and has to be checked before the config is rewritten.
        """
        before = (self.cwd / "config.toml").read_bytes()
        self.build("--discover", "--force", "--only", "2026-wintr", expect=2)
        self.assertEqual((self.cwd / "config.toml").read_bytes(), before)

    def test_a_name_that_is_no_season_is_echoed_as_it_would_be_typed(self):
        """The name refused is given back in the one rule's quotes, spelt out.

        It went through the build's rule already, and nothing held its spelling:
        put back in hand-made double quotes, it passed every test there was
        (/tmp/t6/scratch/m12-review/mutants.log, R5). A name with a quote in it
        is the one that the rule, those double quotes and ``shlex.quote`` each
        spell differently: ``'\\''``, a bare ``'`` and ``'"'"'``.
        """
        run = self.build("--only", "quoll's wintr", expect=2)
        self.assertEqual(run.err.splitlines()[0],
                         "error: --only 'quoll'\\''s wintr': not a season this run "
                         "found")

    def test_two_bad_names_are_both_named(self):
        run = self.build("--only", "2026-wintr", "--only", self.SUMMER,
                         "--only", "2025-sumer", expect=2)
        self.assertEqual(run.err.splitlines()[0],
                         "error: --only 2026-wintr, 2025-sumer: not seasons this run "
                         "found")

    def test_the_list_is_in_the_front_pages_order(self):
        config = self.cwd / "config.toml"
        config.write_text(ONLY_CONFIG + '"season-2" = "Second"\n'
                                        '"season-10" = "Tenth"\n', encoding="utf-8")
        run = self.build("--only", "2026-wintr", expect=2)
        rows = [line.split()[0] for line in run.err.splitlines()
                if line.startswith("    ") and not line.startswith("     ")]
        self.assertEqual(rows, ["season-10", "season-2", self.WINTER, self.SUMMER,
                                self.ARCHIVE])
        self.assertIn("season-10 Tenth (named in config.toml; no card is filed in it)",
                      self.flat(run.err))

    def test_with_no_season_filed_there_is_nothing_to_choose_between(self):
        """No card filed and no season named in config.toml: the refusal says so,
        and says nothing about how a name is spelt, since there is no name to spell.

        A blank list under "The seasons this run found" was the alternative, and so
        was the advice about capitals printed after "nothing to choose between",
        which is how it read first (/tmp/t4/scratch/y88-review/p2, an empty
        ``data/``).
        """
        shutil.rmtree(self.cwd / "data")
        (self.cwd / "data").mkdir()
        (self.cwd / "config.toml").write_text('[build]\nseasons = "multi"\n',
                                              encoding="utf-8")
        run = self.build("--only", self.WINTER, expect=2)
        self.assertEqual(run.err.rstrip("\n"),
                         "error: --only 2026-winter: not a season this run found\n"
                         "  No card under data/ has been filed into a season yet, so "
                         "there is nothing to\n"
                         "  choose between. Nothing was written.")

    def test_a_key_the_folder_rule_reads_as_nothing_is_not_offered(self):
        """A ``season_key`` with nothing in it to key by is listed as no season.

        The loader keeps ``season_key = "!!!"`` as typed, since it matches no
        folder either way, and the refusal listed it as a season named in
        config.toml -- one that ``--only '!!!'`` then refused
        (/tmp/t4/scratch/y88-review/p4).
        Every key the config declares is read by the folder rule instead, which
        reads that one as nothing.
        """
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG + '\n[competitions.odd]\nlabel = "Odd"\nseason_key = "!!!"\n',
            encoding="utf-8")
        run = self.build("--only", "2026-wintr", expect=2)
        rows = [line.split()[0] for line in run.err.splitlines()
                if line.startswith("    ") and not line.startswith("     ")]
        self.assertEqual(rows, [self.WINTER, self.SUMMER, self.ARCHIVE])


class TestALabelOrACompetitionIsRefusedWithTheSeasonNamed(OnlyCase):
    """A season's label or a competition's id is not a season, and the refusal says
    which season was meant.

    Accepting a label when only one season carries it was the alternative: labels
    repeat ("Season 1" is on every card this fixture's summer season has), and a
    rule that works only while they happen to be unique is a rule a club learns
    twice.
    """

    def test_a_label_names_the_season_that_carries_it(self):
        for label in ("2026 Winter Season", "2026 winter season"):
            with self.subTest(label=label):
                run = self.build("--only", label, expect=2)
                self.assertIn(f'"{label}" is the label of 2026-winter, and --only '
                              "takes the folder's name: python3 build.py --only "
                              "2026-winter", self.flat(run.err))

    def test_a_label_two_seasons_share_names_both(self):
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG.replace("2025 Winter Season", "Season 1"), encoding="utf-8")
        run = self.build("--only", "Season 1", expect=2)
        self.assertIn('"Season 1" is the label of 2026-summer and 2025-winter; --only '
                      "takes the folder's name, which tells them apart.",
                      self.flat(run.err))

    def test_a_competition_names_its_season(self):
        run = self.build("--only", self.comp(self.WINTER), expect=2)
        self.assertIn(f"{self.comp(self.WINTER)} is a competition in 2026-winter, and "
                      f"--only picks whole seasons: python3 build.py --only 2026-winter",
                      self.flat(run.err))

    def test_a_label_keyed_with_capitals_is_its_seasons_label(self):
        """``"2027-Winter" = …`` under ``[seasons]`` labels the season the folder
        rule makes of that key, in the list and in the hint.

        The season was known by the folder rule and its label looked up as typed,
        so the list gave 2027-winter no label and the label was refused as nothing
        (/tmp/t4/scratch/y88-review/p3). The label is looked up by the key the
        season is known by.
        """
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG + '"2027-Winter" = "Winter Twenty-Seven"\n', encoding="utf-8")
        said = self.flat(self.build("--only", "Winter Twenty-Seven", expect=2).err)
        self.assertIn('"Winter Twenty-Seven" is the label of 2027-winter, and --only '
                      "takes the folder's name: python3 build.py --only 2027-winter",
                      said)
        self.assertIn("2027-winter Winter Twenty-Seven (named in config.toml; no card "
                      "is filed in it)", said)

    def test_a_path_to_a_seasons_folder_names_the_folder(self):
        """``data/2026-winter``, which is what a shell completes, is a path and not a
        name, and the refusal says which name it holds.

        Accepting it was the alternative, and it is a second way to spell a season,
        with rules of its own for a round's folder inside it and for a path outside
        ``data/``.
        """
        for path in ("data/2026-winter", "./data/2026-Winter/"):
            with self.subTest(path=path):
                run = self.build("--only", path, expect=2)
                self.assertIn(f"{path} is the path to a season's folder, and --only "
                              f"takes the folder's name alone: python3 build.py "
                              f"--only 2026-winter", self.flat(run.err))

    def test_a_folder_named_with_a_dash_first_keeps_its_dot_slash_in_the_hint(self):
        """``Path("./-cards")`` is ``-cards``, which the build reads as a flag.

        Measured before on a copy of the tree (/tmp/t6/scratch/m12/before.txt):
        `--data ./-cards --out ./-site --only ./-cards/2026-winter` printed
        `python3 build.py --only 2026-winter --data -cards --out -site`, and pasted
        that is `argument --data: expected one argument`. The folders are named by
        the function the demo names its folder with, which gives a name that
        begins with a dash its ``./``.
        """
        (self.cwd / "data").rename(self.cwd / "-cards")
        run = self.build("--data", "./-cards", "--out", "./-site",
                         "--only", "./-cards/2026-winter", expect=2)
        command = "python3 build.py --only 2026-winter --data ./-cards --out ./-site"
        self.assertIn("./-cards/2026-winter is the path to a season's folder, and "
                      f"--only takes the folder's name alone: {command}",
                      self.flat(run.err))
        # The line is for a club standing in its project, so it is pasted in one.
        shutil.copy2(BUILD, self.cwd / "build.py")
        for folder in ("matchcentre", "tools"):
            shutil.copytree(ROOT / folder, self.cwd / folder,
                            ignore=shutil.ignore_patterns("__pycache__"))
        done = subprocess.run(
            ("sh", "-c", command), cwd=self.cwd, capture_output=True, text=True,
            timeout=600,
            env=with_this_python(Path(self._tmp.name) / "bin", {
                **os.environ, "PYTHONDONTWRITEBYTECODE": "1"}))
        self.assertEqual(done.returncode, 0, done.stdout[-2000:] + done.stderr)
        self.assertTrue((self.cwd / "-site" / "index.html").is_file())


class TestACommandIsHandedOverOnLinesOfItsOwnAndNotInsideASentence(OnlyCase):
    """The ``--only`` and ``--prune`` hints end their sentence at a colon, and the
    command follows it on lines of its own, as the cd hint's always did.

    Measured before (/tmp/t7/scratch/PL/before.txt, section B), the refusal of
    ``--only 'Season 2'`` wrapped its command with the sentence, and with an
    ``--out`` of 76 columns holding a space it broke the line inside the quotes,
    at ``--out 'our club'\\''s``: pasted, that line break is part of the folder's
    name. With one of 99 and no space, the wrap cut the path itself in two. The
    stale ``--only`` note and the prune retry flowed theirs across four lines each,
    and the note ended in a full stop behind the config's name. Every hint is
    printed by the function that prints every command now, from the line after
    the colon. Rejected: the command kept inside its sentence, wrapped so as not
    to break inside it, which still hands a club a command to pick out of the
    prose, with a full stop behind it.
    """

    OUT = "our club's dashboards/the seasons we publish"

    @staticmethod
    def command(text: str) -> tuple[list[str], list[str], list[str]]:
        """*text*'s lines before the one command in it, its own, and those after."""
        lines = text.splitlines()
        starts = [i for i, line in enumerate(lines)
                  if line.startswith("    python3 build.py")]
        assert len(starts) == 1, text
        end = starts[0]
        while lines[end].endswith(" \\"):
            end += 1
        return lines[:starts[0]], lines[starts[0]:end + 1], lines[end + 1:]

    def assertTheSeasonsCommand(self, text: str, colon: str) -> list[str]:
        """The command in *text* is ``--only 2026-winter`` for this run's ``--out``,
        on lines within the width after a sentence ending at *colon*."""
        from matchcentre import pasteable
        before, command, after = self.command(text)
        said = " ".join(" ".join(before).split())
        self.assertTrue(said.endswith(colon), said)
        self.assertEqual((before[-1], after[0]), ("", ""))
        self.assertEqual(unfolded("\n".join(command)).strip(),
                         f"python3 build.py --only 2026-winter "
                         f"--out {pasteable(self.OUT)}")
        for line in command:
            self.assertLessEqual(len(line), build_mod.WIDTH, command)
        return command

    def test_the_label_s_command_follows_its_colon_and_pastes(self):
        run = self.build("--only", "2026 Winter Season", "--out", self.OUT, expect=2)
        command = self.assertTheSeasonsCommand(
            run.err, "is the label of 2026-winter, and --only takes the folder's name:")
        self.assertFalse((self.cwd / self.OUT).exists())
        # Pasted in the project it names its folders from, so a copy of the program.
        shutil.copy2(BUILD, self.cwd / "build.py")
        for folder in ("matchcentre", "tools"):
            shutil.copytree(ROOT / folder, self.cwd / folder,
                            ignore=shutil.ignore_patterns("__pycache__"))
        done = subprocess.run(
            ("sh", "-c", "\n".join(command)), cwd=self.cwd, capture_output=True,
            text=True, timeout=600,
            env=with_this_python(Path(self._tmp.name) / "bin", {
                **os.environ, "PYTHONDONTWRITEBYTECODE": "1"}))
        self.assertEqual(done.returncode, 0, done.stdout[-2000:] + done.stderr)
        self.assertTrue((self.cwd / self.OUT / "index.html").is_file())

    def test_a_path_longer_than_the_line_is_given_one_of_its_own_whole(self):
        out = "published/" + "y" * 89
        run = self.build("--only", "2026 Winter Season", "--out", out, expect=2)
        self.assertEqual(self.command(run.err)[1],
                         ["    python3 build.py --only 2026-winter --out \\",
                          f"        {out}"])

    def test_the_path_and_the_competition_hints_end_at_their_colons_too(self):
        for value, colon in (("data/2026-winter", "takes the folder's name alone:"),
                             (self.comp(self.WINTER), "--only picks whole seasons:")):
            with self.subTest(value):
                run = self.build("--only", value, "--out", self.OUT, expect=2)
                self.assertTheSeasonsCommand(run.err, colon)

    def test_the_stale_only_note_ends_at_run_and_the_command_follows(self):
        run = self.build("--only", self.SUMMER, "--out", self.OUT)
        section = self.section(run.out, "not listed")
        self.assertTheSeasonsCommand(section, "If 2026-winter is the season being "
                                              "played, run:")
        self.assertTrue(self.command(section)[2][1].startswith("  Their dashboards"))

    def test_the_prune_retry_is_the_left_behind_command_after_its_colon(self):
        self.build("--out", self.OUT)
        comp = next(path for path in (self.cwd / self.OUT).rglob(self.comp(self.SUMMER))
                    if path.is_dir())
        kept = comp.with_name(f"{comp.name}-old")
        shutil.copytree(comp, kept)
        (kept / "notes.txt").write_text("club notes\n", encoding="utf-8")
        offered = self.command(self.section(self.build("--out", self.OUT).out,
                                            "left behind"))[1]
        run = self.build("--out", self.OUT, "--prune", expect=1)
        before, command, after = self.command(self.section(run.out, "pruned"))
        said = " ".join(" ".join(before).split())
        self.assertTrue(said.endswith("Delete the directory yourself, or move that "
                                      "file out of it and prune again:"), said)
        self.assertEqual(before[-1], "")
        self.assertEqual(command, offered)
        self.assertEqual(len(command), 2, command)
        self.assertTrue((kept / "notes.txt").is_file())


class TestTheSeasonIsNamedTheWayItsFolderIs(OnlyCase):
    """``--only`` takes a season's folder name the way the router reads it.

    Capitals and spaces do not matter to the router or the picker, so they do not
    matter here; a card sitting directly in ``data/`` is in the season its year
    names, and that key is a season too.
    """

    def test_capitals_and_spaces_name_the_same_season(self):
        runs = [self.build("--check", "--only", name)
                for name in (self.WINTER, "2026-Winter", " 2026 winter ")]
        self.assertEqual(runs[1].out, runs[0].out)
        self.assertEqual(runs[2].out, runs[0].out)

    def test_a_card_in_no_season_folder_is_named_by_its_year(self):
        cardwriter.write_card_file(self.cwd / "data" / "loose.pdf",
                                   cardwriter.CardSpec())
        full = self.build("--check", expect=None)
        run = self.build("--check", "--only", "2026", expect=full.code)
        self.assertIn("2026-tuesday-division-c", self.headings(run.out))
        self.assertNotIn(self.comp(self.WINTER), self.headings(run.out))


class TestASeasonNamedInTheConfigButNotPlayedIsAccepted(OnlyCase):
    """A season ``config.toml`` names and no card is filed in yet is not a typo.

    A club's own script set up with ``--only`` the week before a season starts
    should not fail before its first card arrives. Refusing it was the alternative;
    saying "no cards yet" was the other, and it presumes a future and mislabels a
    season whose cards were moved to an archive.
    """

    def test_it_is_accepted_and_said_to_have_no_card(self):
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG + '"2027-winter" = "2027 Winter Season"\n', encoding="utf-8")
        full = self.build_in(self.cwd, expect=None)
        run = self.build("--only", "2027-winter", expect=full.code)
        said = self.flat(self.section(run.out, "cards"))
        self.assertIn("2027-winter: no card under data is filed in it; config.toml "
                      "names it.", said)
        counted = self.section(run.out, "not listed")
        self.assertIn("not listed: 3 competition(s) in 3 other season(s)", counted)
        # No date in the season listed is not evidence that anything is later.
        self.assertNotIn("later than every card", self.flat(counted))

    def test_a_season_the_config_spells_with_capitals_is_the_same_season(self):
        # The router files data/2027-Winter/ as 2027-winter, so a key written that
        # way in config.toml is read by the same rule. Compared as typed, it would
        # be refused although the config names it.
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG + '"2027-Winter" = "2027 Winter Season"\n', encoding="utf-8")
        run = self.build("--check", "--only", "2027-winter", expect=None)
        self.assertNotEqual(run.code, 2, run.err)
        self.assertIn("2027-winter: no card under data is filed in it; config.toml "
                      "names it.", self.flat(run.out))

    def test_a_season_only_a_competitions_section_names_is_accepted(self):
        """A ``[competitions.…]`` section's ``season_key`` names a season too.

        A club declaring next season's division before its first card declares it
        there and not always under ``[seasons]``, and no test had it
        (/tmp/t4/scratch/y88-review/mut/run.py R5, which forgets those keys:
        SURVIVED).
        """
        (self.cwd / "config.toml").write_text(
            ONLY_CONFIG + '\n[competitions.sunday-league]\nlabel = "Sunday League"\n'
            'season_key = "2027-Summer"\n', encoding="utf-8")
        run = self.build("--check", "--only", "2027-summer", expect=None)
        self.assertNotEqual(run.code, 2, run.err)
        self.assertIn("2027-summer: no card under data is filed in it; config.toml "
                      "names it.", self.flat(run.out))


def config_warnings(text: str) -> list[str]:
    """Every ``config`` line a report printed, each with its wrap joined back up."""
    label = "  config       "
    said: list[str] = []
    inside = False
    for line in text.splitlines():
        if line.startswith(label):
            said.append(line[len(label):].strip())
            inside = True
        elif inside and line.startswith(" " * len(label)) and line.strip():
            said[-1] += " " + line.strip()
        else:
            inside = False
    return said


class TestASeasonsLabelIsLookedUpTheWayItsFolderIsRead(OnlyCase):
    """A ``[seasons]`` key with capitals or a space in it labels its season.

    The router files ``data/2026-Summer/`` as ``2026-summer`` by the folder rule,
    and ``Config.season_label`` looked the label up under the key as typed, so
    ``"2021-Winter" = …`` and ``"2021 winter" = …`` labelled nothing and said
    nothing: measured in /tmp/t6/scratch/m14/before.txt on a three-season demo
    archive, the label was in 0 of the site's files against 5 for the key spelt
    ``2021-winter`` (index.html, picker-data.js, season-data.js, season.json and
    careers.html), and a folder renamed ``2021-Winter`` was labelled by the
    lower-case key and by no other. The label is looked up by the rule the folder
    is read by. Rejected: folding the keys as the loader reads them, since
    ``--discover`` writes the loaded keys back and would rewrite the club's own
    spelling of every line.
    """

    LABEL = "Summer Twenty-Six"
    CARRIERS = ["careers.html", "index.html", "picker-data.js",
                "season-data.js", "season.json"]

    def labelled(self, name: str, lines: str, *, folder: str = "") -> Path:
        """A copy of the fixture with *lines* under ``[seasons]``, built."""
        where = self.copy(name)
        if folder:
            (where / "data" / self.SUMMER).rename(where / "data" / folder)
        (where / "config.toml").write_text(ONLY_CONFIG + lines, encoding="utf-8")
        self.build_in(where)
        return where

    def differing(self, got: Path, want: Path) -> list[str]:
        mine, theirs = self.tree(got), self.tree(want)
        return sorted(name for name in set(mine) | set(theirs)
                      if mine.get(name) != theirs.get(name))

    def carriers(self, where: Path, text: str) -> list[str]:
        return sorted(Path(name).name for name, body in self.tree(where).items()
                      if text.encode() in body)

    def test_a_key_the_folder_rule_reads_as_its_season_builds_the_exact_keys_site(self):
        # Punctuation and accents too, not only capitals and spaces: a second fold
        # that lowered the key and turned spaces into hyphens passed with those two
        # (/tmp/t6/scratch/m14-review/mut.log, A: SURVIVED).
        want = self.labelled("exact", f'"2026-summer" = "{self.LABEL}"\n')
        self.assertEqual(self.carriers(want, self.LABEL), self.CARRIERS)
        for key in ("2026-Summer", "2026 summer", "2026_summer", "2026-sümmer"):
            with self.subTest(key=key):
                got = self.labelled(key, f'"{key}" = "{self.LABEL}"\n')
                self.assertEqual(self.differing(got, want), [])

    def test_a_key_with_nothing_in_it_labels_no_season(self):
        # The folder rule reads "!!!" as "", which is no season: a card with no
        # season key is not one this line labels.
        cfg = config_mod.Config(path=Path("config.toml"), seasons_mode="multi",
                                season_labels={"!!!": "Nothing"})
        self.assertEqual(cfg.season_label_keys(""), set())
        self.assertEqual(cfg.season_label(""), "")

    def test_a_folder_named_with_capitals_is_labelled_by_either_spelling(self):
        want = self.labelled("exact", f'"2026-summer" = "{self.LABEL}"\n',
                             folder="2026-Summer")
        self.assertEqual(self.carriers(want, self.LABEL), self.CARRIERS)
        got = self.labelled("typed", f'"2026-Summer" = "{self.LABEL}"\n',
                            folder="2026-Summer")
        self.assertEqual(self.differing(got, want), [])

    def test_a_key_that_labels_its_season_is_not_warned_about(self):
        run = self.build_in(self.labelled("typed", f'"2026 Summer" = "{self.LABEL}"\n'),
                            "--quiet", "--check")
        self.assertEqual(config_warnings(run.out), [])

    def test_discover_writes_no_second_line_for_the_season_it_labels(self):
        """``--discover`` writes the typed line back and no commented one beside it.

        The render offered each season no key labels as a commented line, and asked
        the question as typed, so measured it wrote ``# 2021-winter = "Season 1"``
        under ``2021-Winter = …``: a line that, uncommented, is a second label for
        the season. Two lines whose labels differ give the season no label, and a
        third line offered beside them is one more to choose between
        (/tmp/t6/scratch/m14-review/mut.log, E: SURVIVED).
        """
        for name, lines in (("typed", f'"2026-Summer" = "{self.LABEL}"\n'),
                            ("differing", f'"2026-Summer" = "{self.LABEL}"\n'
                                          f'"2026 summer" = "Other Summer"\n')):
            with self.subTest(name):
                where = self.labelled(name, lines)
                self.build_in(where, "--discover", "--force")
                written = (where / "config.toml").read_text(encoding="utf-8")
                block = written.split("[seasons]\n", 1)[1].split("\n\n", 1)[0]
                self.assertIn(f'2026-Summer = "{self.LABEL}"\n', block)
                self.assertNotRegex(block, r"(?m)^# 2026-summer = ")


def unread(key: str, advice: str, season: str = "") -> str:
    """The warning for a ``[seasons]`` *key* naming no season: *advice*, then how
    to make it a season still to come, where the key names one to make."""
    later = (f" If the line is for a season still to come, make its folder, "
             f"data/{season}/, and the run only notes that the label waits for "
             f"the season's first card." if season else "")
    return (f"[seasons] labels {key}, but no card this run read is filed in a "
            f"season of that name, so no page shows the label.{advice}{later}")


CHECK_THE_KEY = " Check the key against the name of the season's folder."


class TestASeasonsKeyNamingNoSeasonReadIsSaidOnce(OnlyCase):
    """A ``[seasons]`` key no card this run read is filed under is a config warning.

    A key a letter out, ``"2021-wintr"``, or the wrong way round, ``"winter-2021"``,
    labelled nothing and the run said nothing: measured in
    /tmp/t6/scratch/m14/before.txt, ``--quiet --check`` printed the same five lines
    for either as for no label at all. It is a config warning, so ``--quiet`` prints
    it, and the season nearest the key is asked about by :func:`slugs.nearest`, the
    rule ``[player_names]`` is answered by. Only a season no key labels is offered:
    rejected, every season the run read, which asks a club declaring next winter
    "Did you mean 2026-winter?" about a season with its own line already. The
    warning says how to make the line a season still to come, which is only noted
    (``TestASeasonsLineForASeasonStillToComeIsOnlyNoted``).
    """

    def said(self, lines: str, *, config: str = ONLY_CONFIG,
             where: Path | None = None) -> list[str]:
        where = where or self.cwd
        (where / "config.toml").write_text(config + lines, encoding="utf-8")
        return config_warnings(self.build_in(where, "--quiet", "--check",
                                             expect=None).out)

    def noted(self, where: Path | None = None) -> list[str]:
        """The ``[seasons]`` notes the full report prints, the config as it is."""
        run = self.build_in(where or self.cwd, "--check", expect=None)
        return [note for note in report_notes(run.out) if note.startswith("[seasons]")]

    def test_a_key_a_letter_out_is_asked_about_the_nearest_season(self):
        for key in ("2026-sumer", "2026-Sumer"):
            with self.subTest(key=key):
                self.assertEqual(self.said(f'"{key}" = "Summer"\n'), [
                    unread(key, " Did you mean 2026-summer?", "2026-sumer")])

    def test_a_key_near_no_unlabelled_season_is_told_what_to_check(self):
        for key, season in (("2027-winter", "2027-winter"),
                            ('"winter 2026"', "winter-2026")):
            with self.subTest(key=key):
                self.assertEqual(self.said(f'{key} = "Winter"\n'), [
                    unread(key, CHECK_THE_KEY, season)])

    def test_a_season_a_key_labels_is_not_offered_whatever_the_keys_spelling(self):
        # 2026-Summer labels 2026-summer, so a stray key beside it is near no season
        # without a label. Judged by the keys as typed, 2026-summer was offered
        # (/tmp/t6/scratch/m14-review/mut.log, B: SURVIVED).
        self.assertEqual(self.said('"2026-Summer" = "Summer"\n'
                                   '"2026-sumer" = "Other Summer"\n'), [
            unread("2026-sumer", CHECK_THE_KEY, "2026-sumer")])

    def test_only_the_nearest_season_is_offered(self):
        # 2025-winter is one edit from the key and 2026-winter two: every season
        # within two edits named both (/tmp/t6/scratch/m14-review/mut.log, C:
        # SURVIVED), which asks the club to choose where the nearest has chosen.
        self.assertEqual(self.said('"2025-wintr" = "Winter"\n',
                                   config='[build]\nseasons = "multi"\n\n[seasons]\n'),
                         [unread("2025-wintr", " Did you mean 2025-winter?",
                                 "2025-wintr")])

    def test_a_run_that_read_no_season_judges_no_key(self):
        for season in (self.WINTER, self.SUMMER, self.ARCHIVE):
            shutil.rmtree(self.cwd / "data" / season)
        self.assertEqual(self.said('"2026-sumer" = "Summer"\n'), [])

    def test_a_season_whose_every_card_was_refused_is_one_its_key_names(self):
        # Refused in its folder, the season is still one the run read, and the
        # refusal is what the report says about it: refused as it was read, or
        # refused as it was filed, a card with no date to take the night from. Nor
        # is it a season still to come because its folder is made: a note that no
        # card read is filed in it would be false.
        for how, write in (("read", lambda card: card.write_bytes(b"not a scorecard")),
                           ("filed", lambda card: cardwriter.write_card_file(
                               card, cardwriter.CardSpec(when="")))):
            with self.subTest(refused=how):
                where = self.copy(how)
                for card in self.cards_of(where, self.SUMMER):
                    write(card)
                self.assertEqual(self.said('"2026-Summer" = "Summer"\n', where=where),
                                 [])
                self.assertEqual(self.noted(where), [])

    def test_a_key_with_nothing_in_it_to_key_by_names_no_season(self):
        # The folder rule reads "!!!" as nothing, and a card refused loose in data/
        # is in no season either, nor is a folder called "---": neither is evidence
        # for the key. No folder can be the season it names, so none is suggested.
        (self.cwd / "data" / "loose.pdf").write_bytes(b"not a scorecard")
        (self.cwd / "data" / "---").mkdir()
        self.assertEqual(self.said('"!!!" = "Nothing"\n'),
                         [unread('"!!!"', CHECK_THE_KEY)])

    def test_a_single_season_run_is_told_only_that_labels_need_the_mode(self):
        # A card refused in a season's folder is a season read in either mode, so
        # the mode is what keeps this to the loader's one warning, and keeps the
        # labelled seasons, whose folders are made, from a note that a label waits.
        self.cards_of(self.cwd, self.SUMMER)[0].write_bytes(b"not a scorecard")
        said = self.said("", config=ONLY_CONFIG.replace('seasons = "multi"',
                                                        'seasons = "single"'))
        self.assertEqual(len(said), 1, said)
        self.assertIn('[build] seasons is "single"', said[0])
        self.assertEqual(self.noted(), [])

    def test_a_mode_written_among_the_labels_is_warned_about_once(self):
        said = self.said('mode = "multi"\n')
        self.assertEqual(len(said), 1, said)
        self.assertIn("not as the mode", said[0])

    def test_the_readme_quotes_what_the_quiet_run_printed(self):
        (self.cwd / "config.toml").write_text(ONLY_CONFIG + '"2026-sumer" = "Summer"\n',
                                              encoding="utf-8")
        run = self.build("--quiet", "--check")
        self.assertEqual(
            readme_block(self, TestALineOfPlayerNamesThatReachesNobodyIsSaidUnderQuiet
                         .HEADING, contains="[seasons] labels"),
            printed_finding(self, run.out, "config"))


def report_notes(text: str) -> list[str]:
    """Every note a report printed, each with its wrap joined back up."""
    said: list[str] = []
    inside = False
    for line in text.splitlines():
        if line.startswith("  note: "):
            said.append(line[len("  note: "):].strip())
            inside = True
        elif inside and line.startswith(" " * 8) and line.strip():
            said[-1] += " " + line.strip()
        else:
            inside = False
    return said


class TestASeasonsLineForASeasonStillToComeIsOnlyNoted(OnlyCase):
    """A ``[seasons]`` line for a season with its folder or its section is noted.

    A season ``config.toml`` names is a season before its first card
    (``TestASeasonNamedInTheConfigButNotPlayedIsAccepted``), and a club labelling
    next winter was warned every run, ``--quiet`` included, that its line named no
    season: measured in /tmp/t6/scratch/m14/fix/nmid.txt, four lines a week about a
    line nobody has to change. A line only its own key names cannot be told from a
    typo, and stays a warning; a season with its folder under ``data/`` or a
    ``[competitions.…]`` section giving it as its ``season_key`` is one the club
    has made, so its line waits for the season's first card, which is a note, the
    way a ``[player_names]`` line waiting for a card that counts is one. Rejected:
    no word at all, which leaves a line that took no effect unsaid in the full
    report; and a note for every key naming no season read, which says nothing
    under ``--quiet`` about a key a letter out.
    """

    NOTE = ("[seasons] labels 2027-winter, a season no card this run read is filed "
            "in yet, so the label waits for the season's first card.")
    LINE = '"2027-winter" = "Winter Twenty-Seven"\n'
    SECTION = ('\n[competitions.2027-winter-tuesday-division-4]\nlabel = "Division 4"\n'
               'season_key = "2027-Winter"\n')

    def made(self, how: str, lines: str = LINE) -> Path:
        """A copy whose ``[seasons]`` has *lines*, the season made *how*.

        The folder and the section's key are each spelt with a capital, which the
        folder rule reads as ``2027-winter``, as it reads a folder with cards in it.
        """
        where = self.copy(how)
        config = ONLY_CONFIG + lines
        if how == "folder":
            (where / "data" / "2027-Winter").mkdir()
        elif how == "section":
            config += self.SECTION
        (where / "config.toml").write_text(config, encoding="utf-8")
        return where

    def test_a_season_with_its_folder_or_its_section_is_noted_not_warned(self):
        for how in ("folder", "section"):
            with self.subTest(made=how):
                where = self.made(how)
                quiet = self.build_in(where, "--quiet", "--check", expect=None)
                self.assertEqual(config_warnings(quiet.out), [])
                full = self.build_in(where, "--check", expect=None)
                self.assertEqual(report_notes(full.out).count(self.NOTE), 1,
                                 report_notes(full.out))
                self.assertEqual(config_warnings(full.out), [])

    def test_the_note_is_listed_with_the_season_it_waits_for(self):
        where = self.made("folder")
        other = self.build_in(where, "--check", "--only", self.WINTER, expect=None)
        self.assertNotIn(self.NOTE, report_notes(other.out))
        # Counted with the seasons left out, as every note tagged with one is.
        self.assertIn("2027-winter", self.flat(self.section(other.out, "not listed")))
        own = self.build_in(where, "--check", "--only", "2027-winter", expect=None)
        self.assertEqual(report_notes(own.out).count(self.NOTE), 1)

    def test_a_key_a_letter_out_of_a_season_still_to_come_is_asked_about_it(self):
        where = self.made("folder", '"2027-wintr" = "Winter Twenty-Seven"\n')
        run = self.build_in(where, "--quiet", "--check", expect=None)
        self.assertEqual(config_warnings(run.out), [
            unread("2027-wintr", " Did you mean 2027-winter?", "2027-wintr")])

    def test_two_lines_for_a_season_still_to_come_are_one_warning(self):
        # Two lines for one season are a mistake whether or not a card has come,
        # and the warning says which label the pages will carry, so a note that
        # the label waits would be a second line about the same two.
        where = self.made("folder", '"2027-Winter" = "Winter Twenty-Seven"\n'
                                    '"2027 winter" = "Other Winter"\n')
        quiet = self.build_in(where, "--quiet", "--check", expect=None)
        self.assertEqual(config_warnings(quiet.out), [
            '[seasons] keys "2027 winter" and 2027-Winter are one season, '
            "2027-winter, because a key is read the way a folder's name is. They "
            "give it different labels and none is keyed 2027-winter, as the season "
            "is, so it has none: keep the one it is for, keyed 2027-winter."])
        full = self.build_in(where, "--check", expect=None)
        self.assertEqual([note for note in report_notes(full.out)
                          if note.startswith("[seasons]")], [])

    def test_a_section_the_front_page_lists_is_said_to_be_headed_by_the_label(self):
        """The note says the label heads the card the front page shows for it.

        A section that gives a day and a division is on the front page before its
        first card, headed by the name its season's first card would be given. The
        note still said the label waited for that card. Measured in
        /tmp/t7/scratch/SEASON/fix/mid.txt, a section for 2023-winter was headed
        ``Winter Twenty-Three - Tuesday`` in the same build whose report said
        ``the label waits for the season's first card``. Its own ``season =`` heads
        such a section instead, and then the label still waits; two sections are
        one list, as the report joins every list, and another season's section is
        not on it whatever it is named. Rejected: no note, which leaves the
        season's pages, which the label does wait for, unsaid.
        """
        listed = ('\n[competitions.2027-winter-tuesday-division-4]\n'
                  'season_key = "2027-Winter"\nday = "Tuesday"\ndivision = "4"\n')
        heads = ("[seasons] labels 2027-winter, a season no card this run read is "
                 "filed in yet, so for now the label heads only the front page's "
                 "card for [competitions.2027-winter-tuesday-division-4], and the "
                 "season's pages wait for its first card.")
        monday = ('\n[competitions.2027-winter-monday-division-1]\n'
                  'season_key = "2027-winter"\nday = "Monday"\ndivision = "1"\n')
        both = ("[seasons] labels 2027-winter, a season no card this run read is "
                "filed in yet, so for now the label heads only the front page's "
                "cards for [competitions.2027-winter-monday-division-1] and "
                "[competitions.2027-winter-tuesday-division-4], and the season's "
                "pages wait for its first card.")
        # Another season's section, named the same by its own line, is its own.
        other = ('\n[competitions.2028-winter-monday-division-1]\n'
                 'season_key = "2028-winter"\nday = "Monday"\ndivision = "1"\n'
                 'season = "Winter Twenty-Seven"\n')
        # What follows the Tuesday section: nothing, its own season, a second one,
        # and one of another season.
        for more, note, heading in (
                ("", heads, "Winter Twenty-Seven"),
                ('season = "Own Winter"\n', self.NOTE, "Own Winter"),
                (monday, both, "Winter Twenty-Seven"),
                (other, heads, "Winter Twenty-Seven")):
            with self.subTest(more=more):
                where = self.copy(f"listed{len(more)}")
                (where / "config.toml").write_text(
                    ONLY_CONFIG + self.LINE + listed + more, encoding="utf-8")
                run = self.build_in(where, expect=None)
                self.assertEqual([said for said in report_notes(run.out)
                                  if said.startswith("[seasons]")], [note])
                page = (where / "site" / "index.html").read_text(encoding="utf-8")
                self.assertIn(f"<h2>{heading} - Tuesday<span", page)


class TestTwoKeysForOneSeasonAreSettledWhateverTheirOrder(OnlyCase):
    """Two ``[seasons]`` keys the folder rule reads as one season give one answer.

    Once a key is read by the folder rule, ``2026-summer`` and ``2026-Summer`` are
    two lines for one season, and nothing said which one labels it. Measured in
    /tmp/t6/scratch/m14/before.txt, the page took the line spelt exactly as the
    season is in either order, and the ``--only`` refusal took the first line of
    the file for a season with no card. The line spelt as the season is labels it,
    which keeps every site that worked before the same bytes; without one, a label
    every line agrees on; otherwise none. One warning names every line. Rejected:
    the first in the file, which makes a rebuild depend on the order of two lines;
    the first in the alphabet, which is guessing which one was meant; and no label
    whenever the lines differ, which takes a label off pages it was on.
    """

    def built(self, name: str, lines: str) -> Path:
        where = self.copy(name)
        (where / "config.toml").write_text(ONLY_CONFIG + lines, encoding="utf-8")
        self.build_in(where)
        return where

    def pair(self, first: str, second: str) -> tuple[Path, Path]:
        """The fixture built with two lines, in the one order and the other."""
        return (self.built("forward", first + second),
                self.built("backward", second + first))

    def said(self, where: Path) -> list[str]:
        return config_warnings(self.build_in(where, "--quiet", "--check").out)

    def test_the_line_spelt_as_the_season_is_labels_it_in_either_order(self):
        forward, backward = self.pair('"2026-summer" = "Summer Twenty-Six"\n',
                                      '"2026-Summer" = "Other Summer"\n')
        alone = self.built("alone", '"2026-summer" = "Summer Twenty-Six"\n')
        self.assertEqual(self.tree(forward), self.tree(alone))
        self.assertEqual(self.tree(backward), self.tree(alone))
        for where in (forward, backward):
            self.assertEqual(self.said(where), [
                "[seasons] keys 2026-Summer and 2026-summer are one season, "
                "2026-summer, because a key is read the way a folder's name is. "
                "The one keyed 2026-summer, as the season is, gives it its label, "
                "and 2026-Summer can go."])

    def test_lines_spelt_otherwise_label_it_only_when_they_agree(self):
        forward, backward = self.pair('"2026-Summer" = "Summer Twenty-Six"\n',
                                      '"2026 summer" = "Other Summer"\n')
        (self.cwd / "config.toml").write_text(ONLY_CONFIG, encoding="utf-8")
        self.build()
        self.assertEqual(self.tree(forward), self.tree(self.cwd))
        self.assertEqual(self.tree(backward), self.tree(self.cwd))
        self.assertEqual(self.said(forward), [
            '[seasons] keys "2026 summer" and 2026-Summer are one season, '
            "2026-summer, because a key is read the way a folder's name is. They "
            "give it different labels and none is keyed 2026-summer, as the season "
            "is, so it has none: keep the one it is for, keyed 2026-summer."])
        agreed = self.built("agreed", '"2026-Summer" = "Summer Twenty-Six"\n'
                                      '"2026 summer" = "Summer Twenty-Six"\n')
        alone = self.built("alone", '"2026-summer" = "Summer Twenty-Six"\n')
        self.assertEqual(self.tree(agreed), self.tree(alone))
        self.assertEqual(self.said(agreed), [
            '[seasons] keys "2026 summer" and 2026-Summer are one season, '
            "2026-summer, because a key is read the way a folder's name is. They "
            'agree on "Summer Twenty-Six", so that is its label, and one line is '
            "enough."])

    def test_the_only_refusal_lists_the_label_the_pages_would_carry(self):
        for first, second in (('"2027-winter" = "Winter Twenty-Seven"\n',
                               '"2027-Winter" = "Other Winter"\n'),
                              ('"2027-Winter" = "Other Winter"\n',
                               '"2027-winter" = "Winter Twenty-Seven"\n')):
            with self.subTest(first=first):
                (self.cwd / "config.toml").write_text(ONLY_CONFIG + first + second,
                                                      encoding="utf-8")
                said = self.flat(self.build("--only", "2026-wintr", expect=2).err)
                self.assertIn("2027-winter Winter Twenty-Seven (named in "
                              "config.toml; no card is filed in it)", said)


class TestASeasonsNameFromItsSeasonsLineIsLeftToThatLineByDiscover(OnlyCase):
    """``--discover`` writes a name ``[seasons]`` gave a season commented out.

    ``discover`` records a label a ``[seasons]`` line gives as declared, and the
    config render wrote any declared season live into the competition's own
    section, where it outranks that line. Measured in
    /tmp/t7/scratch/SEASON/before.txt on a three-season demo archive: after
    ``--discover --force``, ``[competitions.2021-winter-tuesday-division-3]`` held a
    live ``season = "Winter Twenty-One"`` copied from its ``[seasons]`` line, keyed
    ``2021-winter`` or ``2021-Winter``, and with that line then edited the rebuild
    put the new name in 0 of the site's 20 files and the old one in 5. So a section
    is written ``season =`` live only where the section itself names its season; a
    name from ``[seasons]`` is written commented, under a comment saying which line
    gives it. Rejected: writing no line at all, which leaves a club naming one
    competition apart from its season nothing to uncomment; and warning about a
    section that repeats its season's label, which is a warning about a line this
    program wrote.
    """

    NAMED = "2025 Winter Season"
    EDITED = "Winter Twenty-Five"
    COMMENT = ("This season's name comes from its line under [seasons], which "
               "names every competition of the season. Remove the # to give this "
               "competition a name of its own, which that line then no longer "
               "changes.")

    def discovered(self, name: str, config: str = ONLY_CONFIG) -> Path:
        """A copy with *config*, after ``--discover --force``."""
        where = self.copy(name)
        (where / "config.toml").write_text(config, encoding="utf-8")
        self.build_in(where, "--discover", "--force")
        return where

    def section_of(self, where: Path, comp_id: str) -> list[str]:
        lines = (where / "config.toml").read_text(encoding="utf-8").splitlines()
        start = lines.index(f"[competitions.{comp_id}]")
        end = next((at for at in range(start + 1, len(lines))
                    if lines[at].startswith("[")), len(lines))
        return lines[start:end]

    @staticmethod
    def season_lines(section: list[str]) -> list[str]:
        return [line for line in section if re.match(r"(# )?season = ", line)]

    def carriers(self, where: Path, text: str) -> list[str]:
        return sorted(Path(name).name for name, body in self.tree(where).items()
                      if text.encode() in body)

    def test_a_name_its_seasons_line_gives_is_written_commented(self):
        for key in ("2025-winter", "2025-Winter"):
            with self.subTest(key=key):
                where = self.discovered(key, ONLY_CONFIG.replace(
                    '"2025-winter" =', f'"{key}" =', 1))
                section = self.section_of(where, self.comp(self.ARCHIVE))
                self.assertEqual(self.season_lines(section),
                                 [f'# season = "{self.NAMED}"'])

    def test_a_second_discover_leaves_it_commented_in_the_section_it_wrote(self):
        # The second run reads the section the first wrote, with no season of its
        # own, beside the season's line: the section is declared, and still does
        # not name the season.
        where = self.discovered("twice")
        first = (where / "config.toml").read_bytes()
        self.build_in(where, "--discover", "--force")
        self.assertEqual((where / "config.toml").read_bytes(), first)
        section = self.section_of(where, self.comp(self.ARCHIVE))
        self.assertEqual(self.season_lines(section), [f'# season = "{self.NAMED}"'])

    def test_the_comment_says_which_line_names_it(self):
        for key in ("2025-winter", "2025-Winter"):
            with self.subTest(key=key):
                section = self.section_of(self.discovered(f"comment-{key}", (
                    ONLY_CONFIG.replace('"2025-winter" =', f'"{key}" =', 1))),
                    self.comp(self.ARCHIVE))
                self.assertIn(f'# season = "{self.NAMED}"', section)
                at = section.index(f'# season = "{self.NAMED}"')
                above = []
                for line in reversed(section[:at]):
                    if not line.startswith("# "):
                        break
                    above.insert(0, line[2:])
                self.assertEqual(" ".join(above), self.COMMENT)
                self.assertTrue(all(len(line) <= 78 for line in section), section)

    def test_the_line_edited_after_discover_renames_the_season(self):
        where = self.discovered("edited")
        # Every file the name reached, which the edited name has to reach as well.
        reached = self.carriers(where, self.NAMED)
        self.assertIn("season.json", reached)
        path = where / "config.toml"
        written = path.read_text(encoding="utf-8")
        edited = re.sub(rf'(?m)^2025-winter = "{self.NAMED}"$',
                        f'2025-winter = "{self.EDITED}"', written, count=1)
        self.assertNotEqual(edited, written, "--discover wrote no [seasons] line")
        path.write_text(edited, encoding="utf-8")
        self.build_in(where)
        self.assertEqual(self.carriers(where, self.EDITED), reached)
        self.assertEqual(self.carriers(where, self.NAMED), [])

    def test_a_section_that_names_its_own_season_is_still_written_live(self):
        # The club's own line, whether or not it repeats the season's label: one
        # that does cannot be told from the copy an earlier --discover wrote, and
        # the section is where a club pins one competition's name.
        for own in ("Own Winter", self.NAMED):
            with self.subTest(season=own):
                where = self.discovered(f"own-{len(own)}", ONLY_CONFIG + (
                    f"\n[competitions.{self.comp(self.ARCHIVE)}]\n"
                    'season_key = "2025-winter"\nday = "Tuesday"\ndivision = "3"\n'
                    f'season = "{own}"\n'))
                section = self.section_of(where, self.comp(self.ARCHIVE))
                self.assertEqual(self.season_lines(section), [f'season = "{own}"'])
                self.assertFalse(any("[seasons]" in line for line in section),
                                 section)

    def test_a_season_its_cards_name_is_offered_as_before(self):
        section = self.section_of(self.discovered("cards"), self.comp(self.SUMMER))
        self.assertEqual(self.season_lines(section), ['# season = "Season 1"'])
        self.assertIn("# What your association calls this season. Scorecards do not",
                      section)
        self.assertFalse(any("[seasons]" in line for line in section), section)


def write_two_unnamed_rounds(data: Path, *, season_line: str = "",
                             dates: tuple[str, str] = ("2026-08-18", "2026-08-25"),
                             when: str | None = None, flat: bool = False) -> None:
    """Two cards of a Tuesday Division B, home and away, printing *season_line*.

    Hilltop Aces and Bramble Finches, a round each, with no season printed unless
    one is given. *when* is the date line each card prints in place of its date:
    a weekday and a time alone gives a card no date at all. Each card is in a
    round's folder under *data*, or *flat*, directly in it.
    """
    aces, finches = ("Ada Quill", "Bea Rook"), ("Cy Wren", "Di Lark")
    for rnd, played, (home, away), (ours, theirs) in (
            (1, dates[0], ("HILLTOP ACES", "BRAMBLE FINCHES"), (aces, finches)),
            (2, dates[1], ("BRAMBLE FINCHES", "HILLTOP ACES"), (finches, aces))):
        folder = data if flat else data / f"Round{rnd}"
        folder.mkdir(parents=True, exist_ok=True)
        cardwriter.write_card_file(folder / f"r{rnd}.pdf", cardwriter.CardSpec(
            season_line=season_line, date=played, round_label=str(rnd),
            division="B", match_id=f"300000{rnd}", home_name=home, away_name=away,
            rows=(cardwriter.SetRow(6, 2, True, ours, theirs),
                  cardwriter.SetRow(6, 3, False, ours[:1], theirs[:1]),
                  cardwriter.SetRow(2, 6, False, ours[1:], theirs[1:]),
                  cardwriter.SetRow(6, 1, True, ours, theirs)),
            home_roster=tuple(cardwriter.RosterRow(name, 2.5, 2.5, captain=not at)
                              for at, name in enumerate(ours)),
            away_roster=tuple(cardwriter.RosterRow(name, 2.5, 2.5, captain=not at)
                              for at, name in enumerate(theirs)),
            **({} if when is None else {"when": when})))


def flagged_by_the_page() -> tuple[str, ...]:
    """The provenance values app.js's isDerived flags, read off its source.

    So that a test counting the values the page lists as worked out counts them as
    the page does, rather than by a copy of the rule that can fall out of step.
    """
    source = (ROOT / "matchcentre" / "web" / "app.js").read_text(encoding="utf-8")
    start = source.index("\nfunction isDerived(")
    return tuple(re.findall(r"v === '(\w+)'",
                            source[start:source.index("\n}\n", start)]))


class UnnamedSeasonCase(unittest.TestCase):
    """Projects of :func:`write_two_unnamed_rounds`, built once for the class.

    Each class says in ``runs`` what it builds; nothing a test does changes them.
    """

    SINGLE = "[competitions.tuesday-division-b]"
    MULTI = "[competitions.2026-winter-tuesday-division-b]"

    @classmethod
    def setUpClass(cls):
        cls._tmp = tempfile.TemporaryDirectory()
        cls.base = Path(cls._tmp.name)
        cls.runs()

    @classmethod
    def tearDownClass(cls):
        cls._tmp.cleanup()

    @classmethod
    def runs(cls):
        """Build what the class's tests read."""

    @classmethod
    def project(cls, name: str, *, multi: bool = False, flat: bool = False,
                **cards) -> Path:
        """Two cards in a project of their own; in multi-season mode under
        data/2026-winter, or *flat* directly in data/, with the file
        ``--discover --force`` writes there."""
        cwd = cls.base / name
        write_two_unnamed_rounds(cwd / "data" / "2026-winter" if multi and not flat
                                 else cwd / "data", flat=flat, **cards)
        if multi:
            (cwd / "config.toml").write_text('[build]\nseasons = "multi"\n',
                                             encoding="utf-8")
            cls.run_in(cwd, "--discover", "--force")
        return cwd

    @staticmethod
    def run_in(cwd: Path, *argv: str) -> Run:
        return ShortOfResultCase.run_build(cwd, *argv)

    @staticmethod
    def written(cwd: Path) -> str:
        return (cwd / "config.toml").read_text(encoding="utf-8")

    @staticmethod
    def edit(cwd: Path, pattern: str, new: str) -> None:
        """The one line of the file *pattern* matches made *new*, as a club edits."""
        path = cwd / "config.toml"
        text, count = re.subn(pattern, new, path.read_text(encoding="utf-8"),
                              count=1, flags=re.M)
        assert count == 1, (pattern, path)
        path.write_text(text, encoding="utf-8")

    @staticmethod
    def section_of(text: str, header: str) -> list[str]:
        """A written file's lines from *header* to the next header, live or not."""
        lines = text.splitlines()
        start = lines.index(header)
        end = next((at for at in range(start + 1, len(lines))
                    if lines[at].startswith(("[", "# ["))), len(lines))
        return lines[start:end]

    @staticmethod
    def season_lines(section: list[str]) -> list[str]:
        return [line for line in section if re.match(r"(# )?season =", line)]

    @staticmethod
    def comment_above(section: list[str], line: str) -> str:
        """The comment directly above *line*, its marks taken out and one line."""
        above: list[str] = []
        for entry in reversed(section[:section.index(line)]):
            if not entry.startswith("# ") or re.match(r'# (\[|[\w"-]+ =)', entry):
                break
            above.insert(0, entry[2:])
        return " ".join(above)

    @staticmethod
    def season_item(run: Run) -> tuple[str, list[str]]:
        """The review's season name item: its status and its TOML."""
        found = [(status, [line for line in toml if line])
                 for subject, status, toml in review_items(run.text)
                 if subject.startswith("the season name for ")]
        assert len(found) == 1, run.text[-3000:]
        return found[0]

    @staticmethod
    def document(cwd: Path) -> dict:
        found = sorted((cwd / "site").rglob("season.json"))
        assert len(found) == 1, found
        return json.loads(found[0].read_text(encoding="utf-8"))

    @staticmethod
    def worked_out(document: dict) -> list[str]:
        """The aspects the page lists under "values we worked out", as app.js's
        isDerived picks them."""
        flagged = flagged_by_the_page()
        return sorted(aspect for aspect, value
                      in document["meta"]["provenance"].items() if value in flagged)


class TestASeasonsNameIsOfferedAsItsPagesShowItOrNotAtAll(UnnamedSeasonCase):
    """4.461: every offer of a season's name is the one ``export.season_offer`` gives.

    When no card printed a season, the file offered ``# season = "2026 Season 2"``
    in each competition's section, a name nothing gave, while the review offered
    only what the cards support, and the [seasons] table offered a third value,
    the folder's key as it stands. Measured through build.py on cards printing no
    season, two runs each (/tmp/mcf/scratch/STUB/out-before-season.txt): dated
    2026 and dated 2027, config.toml:115 held ``# season = "2026 Season 2"``
    against the review's ``season = "2026"`` and ``season = "2027"``, which then
    said "not in it; add the lines below to the [competitions.tuesday-division-b]
    it has already, to adopt it" of a section holding a ``# season =`` line, on
    both runs; with a weekday and no date, the same line against ``season = ""``
    and "fill this in"; in data/2026-winter under multi, ``# 2026-winter =
    "2026-winter"`` and ``# season = "2026 Season 2"`` against the review's
    ``"2026 Winter"``, the name every page shows. Adopted as the file says, the
    section's line declared "2026 Season 2" and the [seasons] line headed the
    front page "2026-winter - Tuesday"; the review's ``season = ""`` added as
    printed was "live already, so the next run reads it as declared", and
    declared nothing. Now the file, the review and the [seasons] table all offer
    the name the pages show, else the year or years the dates give; where there
    is neither, the file writes a comment and no line, and the review a bare
    ``season =`` that does not load until a name is typed after it. Rejected: a
    sample name kept as an example, which a club adopts by deleting a # and then
    publishes; and ``# season = ""``, which uncommented declares nothing and is
    then called live.
    """

    NO_NAME = ("What your association calls this season. No card printed it and "
               "no date gave a year, so the dashboard leaves it out until you "
               "say: add season = and the name in double quotes.")

    @classmethod
    def runs(cls):
        cls.dated = cls.project("dated")
        cls.dated_runs = (cls.run_in(cls.dated), cls.run_in(cls.dated))
        cls.dated_file = cls.written(cls.dated)
        cls.later = cls.project("later", dates=("2027-08-17", "2027-08-24"))
        cls.later_run = cls.run_in(cls.later)
        cls.later_file = cls.written(cls.later)
        cls.edit(cls.later, r"^# (season = .*)$", r"\1")
        cls.later_adopted = cls.run_in(cls.later)
        cls.undated = cls.project("undated", when="Tue 7:00 PM")
        cls.undated_runs = (cls.run_in(cls.undated), cls.run_in(cls.undated))
        cls.undated_file = cls.written(cls.undated)
        _, toml = cls.season_item(cls.undated_runs[0])
        # The review's lines added under the section the file has, as printed.
        cls.edit(cls.undated, rf"^{re.escape(cls.SINGLE)}$",
                 "\n".join([cls.SINGLE, *toml[1:]]))
        cls.undated_pasted = cls.run_in(cls.undated)
        cls.edit(cls.undated, r"^season =.*$", 'season = "Winter 2026"')
        cls.undated_typed = cls.run_in(cls.undated)
        cls.winter = cls.project("winter", multi=True)
        cls.winter_run = cls.run_in(cls.winter)
        cls.winter_file = cls.written(cls.winter)
        cls.edit(cls.winter, r"^# (2026-winter = .*)$", r"\1")
        cls.winter_adopted = cls.run_in(cls.winter)
        cls.printed = cls.project("printed", season_line="Season 1")
        cls.printed_run = cls.run_in(cls.printed)
        cls.printed_file = cls.written(cls.printed)

    def test_a_season_its_dates_give_a_year_is_offered_that_year_on_every_run(self):
        for name, text, runs, year in (
                ("dated", self.dated_file, self.dated_runs, "2026"),
                ("later", self.later_file, (self.later_run,), "2027")):
            with self.subTest(project=name):
                self.assertEqual(self.season_lines(self.section_of(text, self.SINGLE)),
                                 [f'# season = "{year}"'])
                for run in runs:
                    self.assertEqual(run.code, 0, run.text[-2000:])
                    self.assertEqual(self.season_item(run),
                                     (f"in config.toml: {ADOPT}",
                                      [self.SINGLE, f'season = "{year}"']))

    def test_deleting_its_hash_names_the_season_that_year(self):
        self.assertEqual(self.later_adopted.code, 0, self.later_adopted.text[-2000:])
        meta = self.document(self.later)["meta"]
        self.assertEqual((meta["season_label"], meta["provenance"]["season"]),
                         ("2027", "declared"))

    def test_no_file_offers_a_season_nothing_gave(self):
        for name, text in (("dated", self.dated_file), ("later", self.later_file),
                           ("undated", self.undated_file),
                           ("winter", self.winter_file)):
            with self.subTest(project=name):
                self.assertNotIn("2026 Season 2", text)

    def test_a_season_no_card_or_date_names_is_offered_no_name(self):
        section = self.section_of(self.undated_file, self.SINGLE)
        self.assertEqual(self.season_lines(section), [])
        self.assertIn(self.NO_NAME, written_flat("\n".join(section)))
        self.assertTrue(all(len(line) <= 78 for line in section), section)
        for run in self.undated_runs:
            self.assertEqual(run.code, 0, run.text[-2000:])
            self.assertEqual(self.season_item(run), (
                f"in config.toml: not in it; add the lines below to the "
                f"{self.SINGLE} it has already, with the season's name in double "
                f"quotes typed after the =, to adopt it",
                [self.SINGLE, "season ="]))

    def test_its_lines_stop_the_next_run_until_a_name_is_typed_after_the_equals(self):
        # Measured before this: "live already, so the next run reads it as
        # declared -- check it now", of a season = "" that declared nothing.
        run = self.undated_pasted
        self.assertEqual(run.code, 2, run.text[-2000:])
        self.assertIn("config.toml: not valid TOML", run.err)
        self.assertNotIn("live already", run.text)
        self.assertEqual(self.undated_typed.code, 0, self.undated_typed.text[-2000:])
        meta = self.document(self.undated)["meta"]
        self.assertEqual((meta["season_label"], meta["provenance"]["season"]),
                         ("Winter 2026", "declared"))

    def test_a_seasons_folder_name_made_readable_is_offered_in_every_place(self):
        self.assertEqual(self.winter_run.code, 0, self.winter_run.text[-2000:])
        table = self.section_of(self.winter_file, "[seasons]")
        self.assertIn('# 2026-winter = "2026 Winter"', table)
        self.assertTrue(all(len(line) <= 78 for line in table), table)
        self.assertEqual(self.season_lines(self.section_of(self.winter_file,
                                                           self.MULTI)),
                         ['# season = "2026 Winter"'])
        self.assertEqual(self.season_item(self.winter_run),
                         (f"in config.toml: {ADOPT}",
                          [self.MULTI, 'season = "2026 Winter"']))
        self.assertEqual(self.document(self.winter)["meta"]["season_label"],
                         "2026 Winter")

    def test_deleting_the_hash_of_its_seasons_line_keeps_the_name_shown(self):
        self.assertEqual(self.winter_adopted.code, 0,
                         self.winter_adopted.text[-2000:])
        meta = self.document(self.winter)["meta"]
        self.assertEqual((meta["season_label"], meta["provenance"]["season"]),
                         ("2026 Winter", "declared"))
        front = (self.winter / "site" / "index.html").read_text(encoding="utf-8")
        self.assertRegex(front, r"<h2[^>]*>2026 Winter - Tuesday<")

    def test_a_season_its_cards_print_is_offered_as_before(self):
        section = self.section_of(self.printed_file, self.SINGLE)
        self.assertEqual(self.season_lines(section), ['# season = "Season 1"'])
        self.assertEqual(self.comment_above(section, '# season = "Season 1"'),
                         "What your association calls this season. Scorecards do "
                         "not reliably print it, so the dashboard leaves it out "
                         "until you say. Remove the # to use it.")
        self.assertEqual(self.season_item(self.printed_run),
                         (f"in config.toml: {ADOPT}",
                          [self.SINGLE, 'season = "Season 1"']))


class TestEachMessageAboutASeasonsNameSaysWhereTheNameShownCameFrom(
        UnnamedSeasonCase):
    """4.462: a folder's name is said to be a folder's, and no name is not a value.

    For a season nobody named, every message about its name described something
    that was not happening. Measured through build.py on cards printing no season,
    the pages read in headless Chrome (/tmp/mcf/scratch/STUB/out-before-season.txt):
    in data/2026-winter under multi, every page showed "2026 Winter", its folder's
    name made readable, yet the file's comment and the review's why said the
    dashboard leaves it out until you say, and the page's flag on it said "No
    season label was declared, so this one was worked out from the cards" of a
    name no card holds; in single mode no page shows a season, yet the panel read
    "3 values we worked out" with the season among them, where the printed-season
    control read 2. Now the folder's case is worded as a folder's, and a season
    no page names is provenance "empty", which the page does not list. Rejected:
    "worked out from the cards" kept for a folder, which is not a card; showing no
    name in multi mode until one is declared, against the naming order the front
    page is built on; and "derived" kept for an empty label, which lists a value
    the page does not show.

    In multi-season mode a season's cards that sit in no season folder are keyed
    by the year on them, and the first cut of this said of that year too that it
    was the folder's name: measured on the same cards directly in data/
    (/tmp/mcf/scratch/STUB/fix/before.txt), the file's comment, the review's why
    and the page's flag all said "folder" of ``2026`` beside the run's own note
    that the cards sit in no season folder. Now ``meta.season_label_from`` says
    which the name shown is, "folder" or "date", and each message says that.
    Rejected: one wording for both, "the name worked out", which tells the club
    nothing about where to look.
    """

    FLAT = "[competitions.2026-tuesday-division-b]"
    FOLDER_COMMENT = ("What your association calls this season. No card prints it, "
                      "so the dashboard shows its folder's name made readable until "
                      "you say, here or by the season's line under [seasons]. "
                      "Remove the # to use it.")
    FOLDER_WHY = ("no card prints it, so the dashboard shows the season's folder "
                  "name made readable until a human says what it is")
    DATE_COMMENT = ("What your association calls this season. No card prints it, "
                    "so the dashboard shows the year on its cards until you say, "
                    "here or by the season's line under [seasons]. Remove the # to "
                    "use it.")
    DATE_WHY = ("no card prints it, so the dashboard shows the year on the "
                "season's cards until a human says what it is")

    @classmethod
    def runs(cls):
        cls.winter = cls.project("winter", multi=True)
        cls.winter_run = cls.run_in(cls.winter)
        cls.no_folder = cls.project("no-folder", multi=True, flat=True)
        cls.no_folder_run = cls.run_in(cls.no_folder)
        cls.dated = cls.project("dated")
        cls.dated_run = cls.run_in(cls.dated)
        cls.undated = cls.project("undated", when="Tue 7:00 PM")
        cls.undated_run = cls.run_in(cls.undated)
        cls.printed = cls.project("printed", season_line="Season 1")
        cls.printed_run = cls.run_in(cls.printed)
        cls.printed_winter = cls.project("printed-winter", multi=True,
                                         season_line="Season 1")
        cls.printed_winter_run = cls.run_in(cls.printed_winter)

    def test_the_file_says_a_folders_name_is_shown_until_the_club_says(self):
        section = self.section_of(self.written(self.winter), self.MULTI)
        self.assertEqual(self.comment_above(section, '# season = "2026 Winter"'),
                         self.FOLDER_COMMENT)
        self.assertTrue(all(len(line) <= 78 for line in section), section)

    def test_and_so_does_the_review(self):
        self.assertEqual(self.winter_run.code, 0, self.winter_run.text[-2000:])
        self.assertIn("the season name for 2026-winter-tuesday-division-b why: "
                      f"{self.FOLDER_WHY} in config.toml:", flat(self.winter_run.text))

    def test_the_page_still_flags_a_folders_name_as_worked_out(self):
        document = self.document(self.winter)
        self.assertEqual((document["meta"]["season_label"],
                          document["meta"]["season_label_from"],
                          document["meta"]["provenance"]["season"]),
                         ("2026 Winter", "folder", "derived"))
        self.assertEqual(self.worked_out(document), ["rounds_total", "season",
                                                     "teams"])

    def test_the_file_says_the_year_on_cards_in_no_season_folder_is_shown(self):
        section = self.section_of(self.written(self.no_folder), self.FLAT)
        self.assertEqual(self.comment_above(section, '# season = "2026"'),
                         self.DATE_COMMENT)
        self.assertTrue(all(len(line) <= 78 for line in section), section)

    def test_and_so_does_the_review_of_that_year(self):
        run = self.no_folder_run
        self.assertEqual(run.code, 0, run.text[-2000:])
        self.assertIn("the season name for 2026-tuesday-division-b why: "
                      f"{self.DATE_WHY} in config.toml:", flat(run.text))
        self.assertNotIn("folder name made readable", flat(run.text))

    def test_the_document_says_the_name_shown_is_the_year_on_its_cards(self):
        document = self.document(self.no_folder)
        self.assertEqual((document["meta"]["season_label"],
                          document["meta"]["season_label_from"],
                          document["meta"]["provenance"]["season"]),
                         ("2026", "date", "derived"))
        self.assertEqual(self.worked_out(document), ["rounds_total", "season",
                                                     "teams"])

    def test_a_name_printed_or_absent_is_said_to_come_from_neither(self):
        for name, cwd in (("dated", self.dated), ("printed", self.printed),
                          ("printed-winter", self.printed_winter)):
            with self.subTest(project=name):
                self.assertEqual(self.document(cwd)["meta"]["season_label_from"], "")

    def test_a_season_no_page_names_is_not_counted_among_the_values_worked_out(self):
        for name, cwd, run in (("dated", self.dated, self.dated_run),
                               ("undated", self.undated, self.undated_run)):
            with self.subTest(project=name):
                self.assertEqual(run.code, 0, run.text[-2000:])
                document = self.document(cwd)
                self.assertEqual((document["meta"]["season_label"],
                                  document["meta"]["provenance"]["season"]),
                                 ("", export_mod.EMPTY))
                self.assertEqual(self.worked_out(document), ["rounds_total", "teams"])

    def test_a_season_its_cards_print_reads_as_the_cards_did(self):
        # The printed season's wording is 4.349's, and stands until it lands.
        for name, cwd, header in (("printed", self.printed, self.SINGLE),
                                  ("printed-winter", self.printed_winter, self.MULTI)):
            with self.subTest(project=name):
                document = self.document(cwd)
                self.assertEqual(document["meta"]["provenance"]["season"], "card")
                self.assertEqual(self.worked_out(document), ["rounds_total", "teams"])
                section = self.section_of(self.written(cwd), header)
                self.assertIn("# What your association calls this season. "
                              "Scorecards do not", section)
        self.assertIn("the season name for tuesday-division-b why: scorecards do "
                      "not reliably print it, so the dashboard leaves it out until "
                      "a human says what it is in config.toml:",
                      flat(self.printed_run.text))


class TestPruneAndOnlyAreRefusedTogether(OnlyCase):
    """``--prune --only`` is refused during the parse, the way ``--prune --check`` is.

    The dashboards left behind are listed whatever ``--only`` says, and plain
    ``--prune`` removes exactly those. Pruning inside the season named was the
    alternative, and it is a second rule for the one destructive action, for a
    convenience nobody asked for; pruning everything anyway would ignore half of
    the command line on a run that deletes folders.
    """

    def plant(self) -> list[Path]:
        self.build()
        site_dir = self.cwd / "site"
        planted = [site_dir / self.ARCHIVE / "old", site_dir / "old"]
        shutil.copytree(site_dir / self.ARCHIVE / self.comp(self.ARCHIVE), planted[0])
        shutil.copytree(site_dir / self.WINTER / self.comp(self.WINTER), planted[1])
        return planted

    def test_the_combination_is_refused_and_nothing_is_removed(self):
        planted = self.plant()
        before = [self.tree(p.parent, p.name) for p in planted]
        run = self.build("--prune", "--only", self.WINTER, expect=2)
        self.assertIn("build.py: error: --only shortens the report and --prune removes "
                      "folders from every season; run --prune without --only",
                      self.flat(run.err))
        self.assertEqual([self.tree(p.parent, p.name) for p in planted], before)

    def test_left_behind_is_listed_in_full_with_a_hint_that_prunes_it(self):
        planted = self.plant()
        scoped = self.build("--only", self.WINTER)
        plain = self.build()
        behind = self.section(scoped.out, "left behind")
        for path in planted:
            self.assertIn(str(path.relative_to(self.cwd)), behind)
        self.assertIn("    python3 build.py --prune\n", behind)
        self.assertEqual(behind, self.section(plain.out, "left behind"))


class TestSingleFileWithOnlyFoldsOnlyThatSeason(OnlyCase):
    """``--single-file --only X`` adds a one-file page to X's competitions only.

    A fold is sticky -- once written, every later run keeps it up to date -- so a
    fold added to the whole archive by accident would be permanent. Folding
    everything was the alternative; not refreshing a fold outside X was the other,
    and that leaves a stale one-file page in a club's outbox.
    """

    def folds(self, where: Path) -> dict[str, bytes]:
        return {name: data for name, data in self.tree(where).items()
                if Path(name).name == site.single_file_name(Path(name).parent)}

    def test_only_the_season_named_gets_a_new_one_file_page(self):
        self.build("--single-file", "--only", self.WINTER)
        self.assertEqual([Path(name).parts[0] for name in self.folds(self.cwd)],
                         [self.WINTER])

    def test_a_fold_that_already_exists_elsewhere_is_still_refreshed(self):
        plain = self.copy("plain")
        for where in (self.cwd, plain):
            self.build_in(where, "--single-file")
            self.cards_of(where, self.ARCHIVE)[0].unlink()
        before = self.folds(self.cwd)
        self.build("--single-file", "--only", self.WINTER)
        self.build_in(plain)
        after = self.folds(self.cwd)
        archive = [name for name in after if name.startswith(self.ARCHIVE)]
        self.assertEqual(len(archive), 1)
        self.assertNotEqual(after[archive[0]], before[archive[0]])
        self.assertEqual(after, self.folds(plain))


class TestAStaleOnlyNamesTheSeasonWithLaterCards(OnlyCase):
    """A script of the club's own keeps its ``--only`` into the next season; the
    report says so from the cards' dates.

    Ordering by folder name was the first draft, and its comparison was inverted;
    even corrected, it tells every club that ``2026-winter`` sits above
    ``2026-summer``, including the club whose summer is the later season, and a
    season that crosses New Year misorders. Swapped folders tell the two rules
    apart. A tie is not later: 2025-winter and 2026-summer end on the same day.
    """

    LATER = "later than every card in"

    def test_a_hidden_season_with_later_cards_is_named_with_the_command(self):
        run = self.build("--only", self.SUMMER)
        said = self.flat(self.section(run.out, "not listed"))
        self.assertIn(f"2026-winter has a card dated {DATES['3']}, {self.LATER} "
                      f"2026-summer. If 2026-winter is the season being played, run: "
                      f"python3 build.py --only 2026-winter", said)
        self.assertNotIn("2025-winter has", said)
        self.assertNotIn(self.LATER, self.flat(self.build("--only", self.WINTER).out))

    def test_the_rule_is_the_dates_and_not_the_names(self):
        self.swap(self.cwd, self.WINTER, self.SUMMER)
        said = self.flat(self.build("--only", self.SUMMER).out)
        self.assertNotIn(self.LATER, said)
        said = self.flat(self.section(self.build("--only", self.WINTER).out,
                                      "not listed"))
        self.assertIn(f"2026-summer has a card dated {DATES['3']}, {self.LATER} "
                      f"2026-winter. If 2026-summer is the season being played, run: "
                      f"python3 build.py --only 2026-summer", said)
        self.assertNotIn("2025-winter has", said)
        self.assertNotIn("one too", said)

    def test_a_second_later_season_is_named_beside_the_first(self):
        """With 2025-winter's last round gone, both other seasons end after it,
        and the sentence names the second in brackets.

        Every test above has one later season at most, so the bracket was printed
        by no test (/tmp/t4/scratch/y88-review/mut/run.py R1, which blanks it:
        SURVIVED). Naming only the latest was the alternative, and it sends a club
        to one season when two have been played since.
        """
        shutil.rmtree(self.cwd / "data" / self.ARCHIVE / "round-03")
        said = self.flat(self.section(self.build("--only", self.ARCHIVE).out,
                                      "not listed"))
        self.assertIn(f"2026-winter has a card dated {DATES['3']}, {self.LATER} "
                      f"2025-winter (2026-summer has one too). If 2026-winter is the "
                      f"season being played, run: python3 build.py --only 2026-winter",
                      said)

    def test_every_later_season_is_named_and_two_of_them_have_one(self):
        # A copy of 2025-winter, one round short, filed as 2024-winter: the three
        # other seasons all end after it, and 2026-summer and 2025-winter end on
        # one day, so they follow in the front page's order.
        data = self.cwd / "data"
        shutil.copytree(data / self.ARCHIVE, data / "2024-winter")
        shutil.rmtree(data / "2024-winter" / "round-03")
        said = self.flat(self.section(self.build("--only", "2024-winter").out,
                                      "not listed"))
        self.assertIn(f"2026-winter has a card dated {DATES['3']}, {self.LATER} "
                      f"2024-winter (2026-summer and 2025-winter have one too).", said)

    def test_its_command_carries_the_folders_this_run_was_given(self):
        """The command in the sentence is one a club can paste.

        A bare ``python3 build.py --only 2026-winter`` pasted by a club that keeps
        its cards, its site and its config somewhere else reads the wrong folders,
        which is why every hint in the report is built by one function that carries
        them; the sentence spelling its own command was the alternative
        (/tmp/t4/scratch/y88-review/mut/run.py R2, which does: SURVIVED).
        """
        (self.cwd / "data").rename(self.cwd / "cards")
        (self.cwd / "config.toml").rename(self.cwd / "club.toml")
        run = self.build("--data", "cards", "--out", "published", "--config",
                         "club.toml", "--only", self.SUMMER)
        self.assertIn("If 2026-winter is the season being played, run: python3 "
                      "build.py --only 2026-winter --data cards --out published "
                      "--config club.toml",
                      self.flat(unfolded(self.section(run.out, "not listed"))))

    @staticmethod
    def doc(key: str, *dates: object) -> dict:
        return {"meta": {"season_key": key, "competition": f"{key}-c"},
                "matches": [{"date": d} for d in dates]}

    def later(self, only: tuple[str, ...], *docs: dict):
        from matchcentre.scope import Scope
        return build_mod._played_after_scope(list(docs), Scope(only))

    def test_a_tie_is_not_later(self):
        self.assertEqual(self.later(("a",), self.doc("a", "2026-02-17"),
                                    self.doc("b", "2026-02-17")), [])

    def test_a_season_listed_with_no_date_is_no_evidence(self):
        self.assertEqual(self.later(("a",), self.doc("a"), self.doc("a", "no date"),
                                    self.doc("b", "2026-02-17")), [])

    def test_a_date_that_does_not_read_is_skipped(self):
        self.assertEqual(self.later(("a",), self.doc("a", "2026-02-17"),
                                    self.doc("b", "2026-13-40", None, "")), [])

    def test_later_seasons_come_latest_first_and_ties_in_front_page_order(self):
        found = self.later(("a",), self.doc("a", "2026-02-17", "2026-01-01"),
                           self.doc("season-2", "2026-03-01"),
                           self.doc("season-10", "2026-03-01"),
                           self.doc("c", "2026-02-18", "2026-04-01"))
        self.assertEqual(found, [("c", date(2026, 4, 1)),
                                 ("season-10", date(2026, 3, 1)),
                                 ("season-2", date(2026, 3, 1))])

    def test_later_means_later_than_every_season_listed(self):
        """With two seasons listed, a season whose last card falls between their
        last cards is not named.

        The sentence says "later than every card in a and b". With one season
        listed, the latest of the listed seasons' last cards and the earliest are
        one date, so every other test here passed with the rule comparing against
        the earliest (/tmp/mutate124.py: SURVIVED). That was the alternative, and
        it tells a club listing two seasons that a third, played before the later
        of them finished, is the season being played.
        """
        a, b = self.doc("a", "2026-02-17"), self.doc("b", "2026-04-01")
        self.assertEqual(self.later(("a", "b"), a, b, self.doc("c", "2026-03-01")), [])
        self.assertEqual(self.later(("a", "b"), a, b, self.doc("c", "2026-04-02")),
                         [("c", date(2026, 4, 2))])


class TestOnlyCanBeGivenMoreThanOnce(OnlyCase):
    """``--only`` repeats, and a name given twice is one season.

    A single value was the alternative, and argparse's last-one-wins would keep the
    second of two seasons and drop the first without a word.
    """

    def test_two_seasons_are_both_listed(self):
        run = self.build("--only", self.WINTER, "--only", self.ARCHIVE)
        for season in (self.WINTER, self.ARCHIVE):
            self.assertIn(self.comp(season), self.headings(run.out))
        self.assertIn("only 2026-winter and 2025-winter: 2 of 3 competition(s)",
                      self.flat(run.out))
        self.assertIn("; only these are listed below", self.flat(run.out))
        self.assertRegex(self.section(run.out, "not listed"),
                         r"\n  seasons +2026-summer\n")

    def test_one_season_named_twice_is_one_season(self):
        once = self.build("--check", "--only", self.WINTER)
        twice = self.build("--check", "--only", self.WINTER, "--only", "2026-Winter")
        self.assertEqual(twice.out, once.out)

    def test_every_season_named_leaves_nothing_to_count(self):
        run = self.build("--only", self.WINTER, "--only", self.SUMMER,
                         "--only", self.ARCHIVE)
        self.assertNotIn("not listed", run.out)
        self.assertIn("3 of 3 competition(s)", self.flat(run.out))

    def test_a_blank_name_is_a_usage_error(self):
        for blank in ("", "   "):
            with self.subTest(blank=blank):
                run = self.build("--only", blank, expect=2)
                self.assertIn("--only needs a season's name: the name of its folder "
                              "under data/", self.flat(run.err))


class TestOnlyWithCheckWritesNothingAndStillNarrows(OnlyCase):
    """``--check --only`` writes nothing, lists one season, and says no season was
    written.

    The report's "every season was read, checked and written" is a claim about the
    run, so under ``--check`` it is "read and checked"; the change report keeps
    every season as it does without ``--check``.
    """

    def test_nothing_is_written_and_the_report_is_narrowed(self):
        run = self.build("--check", "--only", self.WINTER)
        self.assertFalse((self.cwd / "site").exists())
        self.assertNotIn(self.comp(self.SUMMER), self.headings(run.out))
        said = self.flat(run.out)
        self.assertIn("Every season was read and checked; only this one", said)
        self.assertNotIn("written like every other", said)
        self.assertIn("They were read and checked like every other", said)

    def test_the_changes_a_build_would_make_are_not_narrowed(self):
        self.build()
        self.cards_of(self.cwd, self.SUMMER)[0].unlink()
        before = self.tree(self.cwd)
        run = self.build("--check", "--only", self.WINTER)
        self.assertIn(self.comp(self.SUMMER),
                      self.section(run.out, "changes a build would make"))
        self.assertEqual(self.tree(self.cwd), before)


class TestOnlyWithDiscoverWritesTheWholeClubsConfig(OnlyCase):
    """``--discover --force --only X`` writes the config ``--discover --force`` does.

    The config describes the club, not the season being read; rendering it from X
    alone would drop every other season's sections from the file.
    """

    def test_the_config_is_the_full_runs_and_the_review_is_narrowed(self):
        plain = self.copy("plain")
        self.build_in(plain, "--discover", "--force")
        run = self.build("--discover", "--force", "--only", self.WINTER)
        self.assertEqual((self.cwd / "config.toml").read_bytes(),
                         (plain / "config.toml").read_bytes())
        review = self.section(run.out, "review")
        self.assertIn(self.comp(self.WINTER), review)
        self.assertNotIn(self.comp(self.SUMMER), review)


class TestTheReadmeQuotesWhatOnlyPrints(OnlyCase):
    """The README's two quotes of ``--only`` are what it prints on this fixture."""

    def test_the_not_listed_quote_is_the_real_section(self):
        run = self.build("--only", self.WINTER)
        quoted = readme_block(self, "## Several seasons", contains="not listed:")
        self.assertEqual(self.flat("\n".join(quoted)),
                         self.flat(self.section(run.out, "not listed")))

    def test_the_refusal_quote_is_the_real_refusal(self):
        quoted = readme_block(self, "## Several seasons",
                              contains="not a season this run found")
        self.assertEqual("\n".join(quoted), ONLY_REFUSAL)
        run = self.build("--only", "2026-wintr", expect=2)
        self.assertEqual(run.err.rstrip("\n"), ONLY_REFUSAL)


class TestTwoSeasonsWhoseNumbersAreEqualAreListedOneWayUnderEverySeed(OnlyCase):
    """``season-1`` and ``season-01``: one order in every list, whatever the seed.

    The fixture's summer and archive seasons, renamed ``season-1`` and
    ``season-01``, with a Wednesday grade added to ``season-1``. Two folders are
    two seasons, and the season order gave these one place. The seasons are found
    in a set, so the tie came out in the order the hash seed left it: measured
    before on the three seasons alone (``/tmp/t4/scratch/f3/probes/onlyseeds.py``,
    ``before-onlyseeds.log``), of seeds 0 to 7 the not-listed section read
    ``season-01, season-1`` under 0 and 3 and the other way under the rest, and
    the refusal of an unknown season put ``season-01`` first under 0, 3, 6 and 7.
    The front page sorts its sections by competition and then, keeping that
    order, by season, so a tie there left the competitions' order standing: here
    ``season-1``'s Tuesday, ``season-01``'s Tuesday, then ``season-1``'s
    Wednesday (``probes/frontonly.py``, ``before-frontonly.log``). Now the key
    itself breaks the tie, and newest first puts ``season-1`` above
    ``season-01``.

    Rejected: breaking the tie in each list, which is three places to keep in
    step and the front page's second sort left to find out for itself.
    """

    SEEDS = (0, 1, 2, 3)
    TIED = ("season-1", "season-01")

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        data = cls.pristine / "data"
        (data / cls.SUMMER).rename(data / cls.TIED[0])
        (data / cls.ARCHIVE).rename(data / cls.TIED[1])
        done = subprocess.run(
            (sys.executable, str(ROOT / "tools" / "demo.py"), "--day", "Wednesday",
             "--division", "4", "--teams", "4", "--rounds", "3",
             "--out", str(data / cls.TIED[0] / "wednesday")),
            capture_output=True, text=True, timeout=600)
        if done.returncode != 0:
            raise AssertionError(f"tools/demo.py failed:\n{done.stdout}{done.stderr}")
        (cls.pristine / "config.toml").write_text(MULTI_CONFIG, encoding="utf-8")

    def seeded(self, seed: int, *argv: str, expect: int = 0) -> Run:
        done = subprocess.run(
            (sys.executable, str(BUILD), "--generated", STAMP, *argv), cwd=self.cwd,
            env=dict(os.environ, PYTHONHASHSEED=str(seed)), capture_output=True,
            text=True, timeout=600)
        run = Run(done.returncode, done.stdout, done.stderr, self.cwd)
        self.assertEqual(run.code, expect, run.text[-3000:])
        return run

    def test_the_seasons_not_listed_are_named_one_way(self):
        for seed in self.SEEDS:
            with self.subTest(seed=seed):
                run = self.seeded(seed, "--only", self.WINTER)
                self.assertIn(f"seasons {', '.join(self.TIED)}",
                              self.flat(self.section(run.out, "not listed")))

    def test_the_refusal_lists_them_one_way(self):
        for seed in self.SEEDS:
            with self.subTest(seed=seed):
                run = self.seeded(seed, "--only", "nosuch", expect=2)
                rows = [line.split()[0] for line in run.err.splitlines()
                        if line.startswith("    ") and not line.startswith("     ")]
                self.assertEqual(rows, [*self.TIED, self.WINTER])

    def test_the_front_page_keeps_each_seasons_sections_together(self):
        # Every season's default name is Season 1, so a heading that would read
        # like another's says whose it is.
        self.seeded(0)
        page = (self.cwd / "site" / "index.html").read_text(encoding="utf-8")
        self.assertEqual(re.findall(r"<h2>([^<]*)<span", page), [
            "Season 1 - Tuesday (season-1)", "Season 1 - Wednesday",
            "Season 1 - Tuesday (season-01)", "Season 1 - Tuesday (2026-winter)"])


class DeclaredCase(CliCase):
    """The standard season, plus a ``[competitions.…]`` section with no cards.

    The section declares the second division these tests can write cards for on
    demand, because the pair of questions the class exists to answer is what the
    front page says before those cards arrive and what it says after -- and the
    answer has to be the *same* competition both times, not two entries that happen
    to share a label. A section is matched to cards by its day and division, so the
    two are declared to agree with :func:`write_second_competition`.

    A config file written by hand, rather than one a first run wrote and a test
    edited: the sections a run writes describe competitions that already have cards,
    which is the one shape this class is not about.
    """

    SECTION = "tuesday-division-c"
    LABEL = "Tuesday Division C"
    DIVISION = "C"

    def declare(self, *extra: str, teams: bool = True) -> None:
        body = (f'[competitions.{self.SECTION}]\n'
                f'label = "{self.LABEL}"\n'
                f'day = "Tuesday"\n'
                f'division = "{self.DIVISION}"\n'
                f'rounds_total = 7\n')
        if teams:
            body += 'teams = ["Northside Nets", "Southside Sets"]\n'
        (self.cwd / "config.toml").write_text(body + "".join(extra),
                                              encoding="utf-8")

    def front_page(self) -> str:
        return (self.cwd / "site" / "index.html").read_text(encoding="utf-8")

    def subtitle(self) -> str:
        """The one line of arithmetic under the site's title.

        Read out of the page rather than from ``_subtitle``, because the page is
        where a club reads it and the substitution in between is the part that has
        been written wrongly before.
        """
        page = self.front_page()
        at = page.index("<small>", page.index('class="brand"'))
        return page[at + len("<small>"):page.index("</small>", at)]

    def entries(self) -> dict[str, dict]:
        """``picker-data.js``, keyed by competition id.

        The island the front page's own script reads, so an entry missing here is a
        competition the season navigation cannot see even when the markup lists it.
        """
        text = (self.cwd / "site" / "picker-data.js").read_text(encoding="utf-8")
        body = json.loads(text[text.index("{"):text.rindex("}") + 1])
        return {entry["id"]: entry for entry in body["competitions"]}

    def card_for(self, label: str) -> str:
        """The one card on the front page for *label*, asserted to be one.

        Sliced from the label back to the element that opens it, because what these
        tests are about is which element that is: an ``<a>`` is a dashboard a reader
        can open and a ``<div>`` is a competition that has none.
        """
        page = self.front_page()
        at = page.find(f">{label}<")
        self.assertGreater(at, 0, f"the front page does not name {label!r}:\n"
                                  f"{page[:2000]}")
        self.assertEqual(page.count(f">{label}<"), 1,
                         f"the front page lists {label!r} more than once")
        opens = max(page.rfind("<a class=\"pick\"", 0, at),
                    page.rfind("<div class=\"pick", 0, at))
        self.assertGreater(opens, 0, f"{label!r} is not inside a card")
        ends = [end for end in (page.find("\n      </a>", at),
                               page.find("\n      </div>", at)) if end > 0]
        self.assertTrue(ends, f"the card holding {label!r} is never closed")
        return page[opens:min(ends)]

    def cards_named(self, label: str) -> list[str]:
        """Every card on the front page named *label*, in the order the page lists them.

        :meth:`card_for` asserts there is exactly one, which is what most of these
        tests want and the one thing a test of two cards that read alike cannot have.
        Sliced the same way, so either kind of card comes back whole.
        """
        page, out = self.front_page(), []
        at = page.find(f">{label}<")
        while at > 0:
            opens = max(page.rfind("<a class=\"pick\"", 0, at),
                        page.rfind("<div class=\"pick", 0, at))
            ends = [end for end in (page.find("\n      </a>", at),
                                   page.find("\n      </div>", at)) if end > 0]
            out.append(page[opens:min(ends)])
            at = page.find(f">{label}<", at + 1)
        return out

    def inert_cards(self) -> list[tuple[str, str]]:
        """Each card with no dashboard behind it, as its name and its small print."""
        return re.findall(r'<div class="pick pick-empty"[^>]*>\s*'
                          r'<span class="pick-top"><span class="pick-name">(.*?)'
                          r'</span>.*?<span class="pick-facts">(.*?)</span>',
                          self.front_page(), re.S)

    def headings(self) -> list[str]:
        """The front page's headings, in order, as the page has them."""
        return re.findall(r"<h2>(.*?)<span", self.front_page())

    @staticmethod
    def facts(card: str) -> str:
        """The line of small print under a card's name, exactly as the page has it.

        The whole line rather than a phrase from it, because what these tests pin is
        what the line does *not* say as much as what it does: a phrase found inside it
        passes on a line with a clause nobody asked for, or a separator with nothing
        after it.
        """
        opening = '<span class="pick-facts">'
        at = card.index(opening) + len(opening)
        return card[at:card.index("</span>", at)]


class TestACompetitionDeclaredButNotPlayedYetIsOnTheFrontPage(DeclaredCase):
    """A club types next season's division in before its first night is played.

    Nothing was ever listed for it. The front page shows the competitions the run
    built, so a declared competition with no cards was invisible: from outside, "no
    results yet" and "this tool has never heard of it" look identical, and only one
    of them is something a reader can wait out. The tool's own answer to which it was
    lived in a note on the terminal, which is gone by the next morning.

    Listed, and inert: there is no dashboard behind it, so the card is not a link and
    the run writes no directory for it. What it says is what the club's own config
    file says -- the label, the teams they typed -- and where that came from, because
    the other way this entry appears is a misspelt division, and then the club needs
    to know why a competition they do not run is on their front page.
    """

    def setUp(self):
        super().setUp()
        self.declare()
        self.run_ = self.build()

    def test_the_front_page_names_it(self):
        self.assertIn(self.LABEL, self.front_page())

    def test_it_is_not_a_link_to_a_dashboard_that_was_never_written(self):
        # The worst version of this: a card that looks like every other card and
        # opens a folder listing, or nothing at all.
        self.assertNotIn(f"{self.SECTION}/index.html", self.front_page())
        self.assertIn("<div class=\"pick pick-empty\"",
                      self.card_for(self.LABEL))

    def test_the_run_writes_no_directory_for_a_competition_with_no_cards(self):
        self.assertFalse((self.cwd / "site" / self.SECTION).exists(),
                         "a declared competition with no cards got a dashboard "
                         "directory, which can only hold a fictional season")

    def test_the_card_says_there_are_no_results_and_where_it_came_from(self):
        card = " ".join(self.card_for(self.LABEL).split())
        self.assertIn("No results yet", card)
        self.assertIn("2 teams", card)
        self.assertIn("declared in config.toml", card)

    def test_a_section_that_names_no_teams_says_nothing_about_teams(self):
        """The commoner shape of this section, and the one "0 teams" libels.

        A club typing next season's division in has the day and the grade before it
        has the draw, so ``teams`` is the line they leave out. A card reading "0
        teams" describes a competition with nobody in it; what is true is that this
        tool has not been told, and a card has no room to say so.
        """
        self.declare(teams=False)
        shutil.rmtree(self.cwd / "site")
        self.build()
        card = " ".join(self.card_for(self.LABEL).split())
        self.assertNotIn("0 teams", card)
        self.assertIn("declared in config.toml", card)

    def test_a_section_with_no_label_is_named_by_its_day_and_division(self):
        """Not by the section's own name, which is an id the club made up.

        ``[competitions.next-summer]`` is a heading in a file, and a front page
        reading "next-summer" says this tool chose that name. The day and the
        division are facts about the competition, and they are put together by the
        same rule a competition that *has* been played uses -- so the card keeps its
        name when its cards arrive instead of being renamed by the run that builds
        it.
        """
        (self.cwd / "config.toml").write_text(
            '[competitions.next-summer]\nday = "Thursday"\ndivision = "5"\n',
            encoding="utf-8")
        shutil.rmtree(self.cwd / "site")
        self.build()
        self.assertNotIn("next-summer", self.front_page())
        card = " ".join(self.card_for("Thursday Division 5").split())
        self.assertIn("No results yet", card)

    def test_the_readme_describes_the_card_this_run_wrote(self):
        """The one new thing a club sees, checked against the page rather than read.

        A greyed card nobody documented is a defect report waiting to be filed --
        "there is a competition on my front page that I do not run" -- and the words
        in the README have to be the words on the card, because that is what
        somebody searching the README will type.
        """
        readme = (Path(__file__).resolve().parents[1] / "README.md").read_text(
            encoding="utf-8")
        card = " ".join(self.card_for(self.LABEL).split())
        for phrase in ("No results yet", "declared in config.toml"):
            self.assertIn(phrase, card)
            self.assertIn(phrase, readme,
                          f"the front page says {phrase!r} and the README does "
                          f"not, so a club reading it cannot look up the card "
                          f"they are looking at")

    def test_the_subtitle_counts_the_one_with_results_and_the_one_without(self):
        # The "N of M" the page has always printed, which until now could only ever
        # read "1 of 1": nothing without results reached the list to be counted.
        self.assertEqual(self.subtitle(), "1 of 2 competitions with results")

    def test_the_group_it_is_listed_under_counts_it_too(self):
        # Both competitions are played on a Tuesday, so single-season mode groups
        # them together and the heading's own count is the one a reader compares
        # against the cards in front of them.
        self.assertIn("Tuesday<span class=\"count\">1 of 2 with results</span>",
                      self.front_page())

    def test_the_island_the_page_reads_says_it_has_no_dashboard_behind_it(self):
        entry = self.entries()[self.SECTION]
        self.assertFalse(entry["has_data"])
        self.assertEqual(entry["href"], "",
                         "picker-data.js offers a link to a directory this run "
                         "did not write, so a page built from the island alone "
                         "would send a reader to a folder listing")
        self.assertEqual(entry["label"], self.LABEL)
        self.assertEqual(entry["teams"], 2)
        self.assertEqual(entry["cards"], 0)

    def test_the_report_says_it_has_no_dashboard_and_is_on_the_front_page(self):
        note = " ".join(self.run_.out.split())
        self.assertIn(f"describes [competitions.{self.SECTION}]", note)
        self.assertIn("no dashboard of its own", note)
        self.assertIn("front page", note)

    def test_the_competition_the_cards_do_describe_is_untouched(self):
        # A declaration for another competition is not allowed to cost this one
        # anything: same 7 cards, same ladder, same link.
        self.assertEqual(self.season()["meta"]["cards_scored"], len(self.cards))
        self.assertIn("tuesday-division-b/index.html", self.front_page())
        self.assertIn("exit 0", self.run_.text)

    def test_a_section_that_names_no_night_is_not_invented_onto_the_page(self):
        """The discriminating case for what reaches the list.

        A section naming only a division cannot be matched to a card -- the same
        division runs on more than one night at plenty of clubs -- so nothing will
        ever be filed under it. Putting it on the front page would mean choosing a
        night for it, which is the one thing this tool does not do.
        """
        (self.cwd / "config.toml").write_text(
            '[competitions.mystery]\nlabel = "Some Other Grade"\n'
            'division = "D"\n', encoding="utf-8")
        shutil.rmtree(self.cwd / "site")
        run = self.build()
        self.assertNotIn("Some Other Grade", self.front_page())
        self.assertEqual(self.subtitle(), "1 of 1 competition with results")
        flat = " ".join(run.out.split())
        self.assertIn("describes [competitions.mystery]", flat)
        self.assertIn("does not give both a day and a division", flat)

    def test_the_cards_arriving_turn_the_same_entry_into_a_link(self):
        """The whole point of listing it: the entry a club watches fills in.

        One entry, not two. The competition id is the section's own name, so the
        cards land under the id already on the page -- and a list that unioned the
        *generated* id with the declared one would show the same competition twice,
        once linked and once not.
        """
        write_second_competition(self.cwd / "data" / "division-c")
        shutil.rmtree(self.cwd / "site")
        self.build()
        card = self.card_for(self.LABEL)
        self.assertIn(f"href=\"{self.SECTION}/index.html\"", card)
        self.assertNotIn("No results yet", card)
        self.assertEqual(self.subtitle(), "2 of 2 competitions with results")


class TestADeclaredCompetitionInMultiSeasonModeSaysWhichSeasonItIsIn(DeclaredCase):
    """The same section, in the mode that groups the front page by season.

    A club that keeps its archives declares next season before it starts, and the
    front page then has to put the entry under that season rather than among the
    one being played. The season a card belongs to is read off its own link, which
    an entry with no dashboard has not got -- so the season is written onto the card
    itself, and the page's script reads it from there.
    """

    KEY = "2027-summer"
    SEASON = "2027 Summer"
    PLAYED = "2026-winter"

    def setUp(self):
        super().setUp()
        # The season being played, moved under a folder of its own. In multi-season
        # mode the first folder under data/ *is* the season, and these cards are
        # written one folder per round -- so left where they are they would be read
        # as three seasons of one round each, which is a different bug's fixture.
        season = self.cwd / "data" / self.PLAYED
        season.mkdir()
        for child in sorted((self.cwd / "data").iterdir()):
            if child != season:
                shutil.move(str(child), str(season / child.name))
        self.declare(f'season_key = "{self.KEY}"\n',
                     f'season = "{self.SEASON}"\n',
                     '\n[build]\nseasons = "multi"\n')
        self.run_ = self.build()

    def test_it_is_headed_by_the_season_the_club_named(self):
        self.assertIn(f"{self.SEASON} - Tuesday", self.front_page())

    def test_the_card_carries_the_season_so_the_buttons_can_filter_it(self):
        self.assertIn(f'data-season="{self.KEY}"', self.card_for(self.LABEL))

    def test_the_season_it_belongs_to_is_in_the_island_too(self):
        entry = self.entries()[self.SECTION]
        self.assertEqual(entry["season_key"], self.KEY)
        self.assertEqual(entry["season_label"], self.SEASON)

    def test_the_subtitle_counts_the_season_nobody_has_played(self):
        # Two seasons on the page, one of them entirely in the future. The count is
        # of seasons the page lists, not of seasons with results, because the
        # navigation it describes has a button for each.
        self.assertEqual(self.subtitle(),
                         "1 of 2 competitions with results across 2 seasons")

    def test_a_dashboard_that_has_one_is_still_placed_by_its_link(self):
        # The attribute is written only where there is nothing else to read: a
        # linked card's season comes from the link, which is unique by
        # construction, and two spellings of one fact is how they come to disagree.
        self.assertNotIn("data-season=", self.card_for("Tuesday Division B"))


class TestASectionWithNoCardIsHeadedByTheNameItsSeasonIsGiven(DeclaredCase):
    """A section with no card yet is headed as a card of its season would be.

    The front page named a competition with no card by the season its section
    gives, and nothing else: ``[seasons]`` and the folder's name, which name every
    other competition, were never asked. Measured in
    /tmp/t7/scratch/SEASON/before.txt on a three-season demo archive, a section for
    ``2023-winter`` with a ``[seasons]`` line ``"Winter Twenty-Three"`` was headed
    ``2023-winter - Tuesday``, the name in 0 of the site's 20 files and
    ``picker-data.js`` giving it ``""``, keyed exactly or as ``2023-Winter``. So the
    front page asks the question discovery asks, in its order -- the section's
    ``season``, then the season's ``[seasons]`` line -- and falls back to the key
    made readable as a season document does. Rejected: a third copy of that order
    in site.py, which is how the front page came to have an order of its own.
    """

    KEY = "2027-summer"
    PLAYED = "2026-winter"
    LINE = "Summer Twenty-Seven"

    def setUp(self):
        super().setUp()
        # The played season under a folder of its own, as multi-season mode reads
        # the first folder under data/ as the season.
        season = self.cwd / "data" / self.PLAYED
        season.mkdir()
        for child in sorted((self.cwd / "data").iterdir()):
            if child != season:
                shutil.move(str(child), str(season / child.name))

    def headed(self, *section: str, seasons: str = "") -> str:
        """The section keyed 2027-summer, built; what the island calls its season."""
        self.declare(f'season_key = "{self.KEY}"\n', *section,
                     '\n[build]\nseasons = "multi"\n',
                     f"\n[seasons]\n{seasons}" if seasons else "")
        shutil.rmtree(self.cwd / "site", ignore_errors=True)
        self.build()
        return self.entries()[self.SECTION]["season_label"]

    def assertHeaded(self, name: str, label: str) -> None:
        self.assertEqual(label, name)
        self.assertIn(f"<h2>{name} - Tuesday<span", self.front_page())

    def test_its_seasons_line_heads_it_however_the_key_is_spelt(self):
        for key in ("2027-summer", "2027-Summer"):
            with self.subTest(key=key):
                self.assertHeaded(self.LINE,
                                  self.headed(seasons=f'"{key}" = "{self.LINE}"\n'))

    def test_its_own_season_heads_it_over_the_seasons_line(self):
        self.assertHeaded("Own Summer", self.headed(
            'season = "Own Summer"\n', seasons=f'"{self.KEY}" = "{self.LINE}"\n'))

    def test_with_neither_it_is_headed_by_its_folder_name_made_readable(self):
        self.assertHeaded("2027 Summer", self.headed())

    def test_its_first_card_leaves_the_heading_as_it_was(self):
        before = self.headed(seasons=f'"{self.KEY}" = "{self.LINE}"\n')
        write_second_competition(self.cwd / "data" / self.KEY / "Round 1",
                                 division=self.DIVISION)
        self.build()
        after = self.entries()[self.SECTION]
        self.assertTrue(after["has_data"], after)
        self.assertEqual((before, after["season_label"]), (self.LINE, self.LINE))


class TestACardWithNoResultsGivesTheFirstRoundItsDrawDates(DeclaredCase):
    """The draw a club typed in before the first night, on the card for it.

    Measured before (``/tmp/t4/scratch/w425/measure.py``): a section with two teams
    and two rounds dated 2026-10-08 and 2026-10-15, no cards, built as of 2026-09-10,
    gave the card ``2 teams · declared in config.toml``, and ``picker-data.js`` held
    no round and no date either. The one thing the club had typed that a reader of
    the front page is waiting for was the one thing not on it.

    What the card gives is what the draw says -- ``round 1 on 6 Oct 2026``, the
    first round in the order the season runs that has a date -- and never "next".
    The only today this program has is ``--generated``, and a card choosing its round
    by that would decide from the calendar that a round nobody sent a card for has
    been played, which is the one thing the dashboard refuses to decide that way: a
    round is gone past only when a later round has a card, and a competition with no
    dashboard has no card at all. It would also make a rebuild on a later day rewrite
    the front page with no card changed, under a footer still giving the day its
    figures last moved.
    """

    def draw(self, *rounds: tuple[str, str]) -> str:
        """``[[…rounds]]`` blocks for the declared section, one per number and date.

        An empty date leaves the line out, which is how a club writes a round it has
        not been given a date for yet.
        """
        return "".join(
            f'\n[[competitions.{self.SECTION}.rounds]]\nnumber = "{number}"\n'
            + (f'date = "{date}"\n' if date else "")
            + 'fixtures = [["Northside Nets", "Southside Sets"]]\n'
            for number, date in rounds)

    def facts_for(self, *rounds: tuple[str, str]) -> str:
        """Declare *rounds*, build, and read the small print of the card."""
        self.declare(self.draw(*rounds))
        self.build()
        return self.facts(self.card_for(self.LABEL))

    def test_the_first_round_and_its_date_are_on_the_card(self):
        """``round 1 on 6 Oct 2026``: with the year, in the build's own year too.

        Rejected: the year only when it is not the build's, which is a today again.
        Measured on a copy with that rule (``/tmp/t4/scratch/w425/fix/yearvariant/
        run.py``), the card read ``round 1 on 6 Oct`` when built on 23 Sep 2026, a
        rebuild on 20 Dec wrote nothing, and a rebuild on 5 Jan 2027 with no card
        changed wrote ``index.html`` -- 1 of 8 files -- to add the year, under a
        footer still reading ``23 Sep, 12:00pm``. Always giving it wrote nothing on
        either night.
        """
        self.assertEqual(self.facts_for(("1", "2026-10-06"), ("2", "2026-10-13")),
                         "2 teams &middot; round 1 on 6 Oct 2026 &middot; declared "
                         "in config.toml")
        # The island carries the date as it was typed; the card is where it is
        # spelled for a reader, by the front page's one date formatter.
        self.assertEqual(self.entries()[self.SECTION]["first_round"],
                         {"number": "1", "date": "2026-10-06"})

    def test_a_round_whose_date_has_gone_by_with_no_card_is_still_round_1(self):
        """Last season's draw, left in: the card says round 1, and says which year.

        Dated before the build and before any day this suite will be run on, so a
        card that skipped a round because its date had passed -- by ``--generated``
        or by the machine's clock -- drops both rounds and fails here either way. A
        round with no card and a date behind it is not over; it is the case the card
        is most use in, since a date gone by above "No results yet" is how a club
        notices the cards were never exported, or the division was spelt wrongly.

        And with its year, because this is the draw that most needs one. Measured
        without it (``/tmp/t4/scratch/w425/fix/probe.py``), a draw dated 2025-10-07
        built on 2026-09-23 read ``round 1 on 7 Oct`` -- a fortnight ahead, to anybody
        reading it -- where the dashboard's own ``longDate`` gives the same date as
        ``Tue 7 Oct 2025``.
        """
        self.assertIn("round 1 on 7 Oct 2025",
                      self.facts_for(("1", "2025-10-07"), ("2", "2025-10-14")))

    def test_a_rebuild_on_a_later_day_writes_nothing(self):
        """The date is the draw's, so the page does not move when the calendar does.

        A rebuild that found no new card writes nothing, and the front page's own
        date is the newest of its documents'. A card that changed with the build's
        date would break the first, and a front page re-dated to the run to cover
        for it would break the second -- the page claiming the figures moved on a
        night nothing was read.
        """
        self.declare(self.draw(("1", "2026-10-06"), ("2", "2026-10-13")))
        self.build()
        before = {name: (self.cwd / "site" / name).read_bytes()
                  for name in self.files_in("site")}
        run = self.build("--generated", "2026-10-20T12:00:00")
        self.assertIn("wrote nothing:", " ".join(run.out.split()))
        after = {name: (self.cwd / "site" / name).read_bytes()
                 for name in self.files_in("site")}
        self.assertEqual(sorted(name for name in after
                                if after[name] != before.get(name)), [])

    def test_a_round_with_no_date_lends_its_name_to_no_other_rounds_date(self):
        """Round 1 not dated yet, rounds 2 to 10 weekly: the card says round 2.

        Not "round 1 on 13 Oct", which is round 2's date under round 1's name, and
        not nothing, which throws the draw away because its first line is blank. Ten
        rounds rather than two because the order is the season's: sorted as text, the
        first dated round of 2 to 10 is round 10.
        """
        weekly = [(str(n), (date(2026, 10, 13) + timedelta(weeks=n - 2)).isoformat())
                  for n in range(2, 11)]
        facts = self.facts_for(("1", ""), *weekly)
        self.assertIn("round 2 on 13 Oct 2026", facts)
        self.assertNotIn("round 1", facts)

    def test_the_first_round_is_the_first_the_season_plays_not_the_first_typed(self):
        # Round 1 added at the bottom of a draw typed from round 2, which is how a
        # club that was given the first night late writes it in.
        self.assertIn("round 1 on 6 Oct 2026",
                      self.facts_for(("2", "2026-10-13"), ("1", "2026-10-06")))

    def test_a_round_1_moved_behind_round_2_is_still_the_round_given(self):
        """Round 1 moved to 21 Oct and round 2 left on 14 Oct: the card says round 1.

        The first round the season runs that has a date, not the draw's earliest
        date. Measured (``/tmp/t4/scratch/w425/fix/probe.py``), this draw gave
        ``round 1 on 21 Oct`` while the class above, the README and the changelog all
        said the card gave "the first date its draw declares", which is the 14th: the
        rule was right and the sentence about it was not, so the sentence moved. The
        order is the one the dashboard lists a draw in and the one a round is gone
        past in, :func:`~matchcentre.competition.round_sort_key`, so the card gives the
        first line of the draw a club will read there. Rejected: the earliest date,
        which needs every date read as a date -- ``6 & 7 Oct`` has no place in that
        order, and would be put first or last by a rule nobody typed.
        """
        self.assertIn("round 1 on 21 Oct 2026",
                      self.facts_for(("1", "2026-10-21"), ("2", "2026-10-14")))

    def test_a_finals_draw_gives_the_first_night_of_its_series(self):
        """A section declaring only its finals: the card gives the semi-final.

        Measured before (``/tmp/t4/scratch/y437/c2_rounds.py``): a finals draw of an
        undated round 1, ``SF`` on 2026-12-01 and ``F`` on 2026-12-08 gave ``round F
        on 8 Dec 2026``, and ``QF``, ``SF``, ``GF`` on 24 Nov, 1 Dec and 8 Dec gave
        ``round GF on 8 Dec 2026`` -- the last night of the series under the first
        round's heading, because a named round was put in order by its letters (4.37).
        The order is still the one the season runs in, and the label is what says
        where a final comes in it; the dates play no part, as the class says.
        """
        self.assertIn("round SF on 1 Dec 2026",
                      self.facts_for(("1", ""), ("SF", "2026-12-01"),
                                     ("F", "2026-12-08")))
        self.assertIn("round QF on 24 Nov 2026",
                      self.facts_for(("GF", "2026-12-08"), ("QF", "2026-11-24"),
                                     ("SF", "2026-12-01")))

    def test_a_draw_with_no_dates_adds_nothing_to_the_card(self):
        """Rounds with numbers and nothing else: no date to give, so no clause.

        And no "round 1 on" with nothing after it, which a date of spaces gave
        (``/tmp/t4/scratch/w425/fix/probe.py``: ``round 1 on    · declared in
        config.toml``). Blank is decided once, where the file is read, as a round's
        number already was, so the card, the dashboard's draw and a declared round's
        fallback to its cards' date all get the same answer. Rejected: a ``strip()``
        of the card's own, which is a second rule for what counts as a date.
        """
        for blank in ("", "  "):
            with self.subTest(date=blank):
                self.assertEqual(self.facts_for(("1", blank), ("2", "")),
                                 "2 teams &middot; declared in config.toml")
                self.assertIsNone(self.entries()[self.SECTION]["first_round"])

    def test_a_round_dated_with_spaces_keeps_the_date_its_cards_give(self):
        """The blank date's other reader: a round with cards, declared ``date = "  "``.

        A declared round's date is given over its cards', which is right for a date
        and wrong for spaces. Measured before (``/tmp/t4/scratch/w425/fix/blankdate/
        run.py``), the season document's round 1 was dated ``"  "`` where both its
        cards say 2026-08-18; after, it is the cards' date. This is why blank is
        decided where the file is read and not by the front page's card alone: a
        ``strip()`` there mends the card and leaves this.
        """
        # rounds_total, because a draw declares the season's length (4.18) and this
        # one lists only the round it dates, of the three its cards were played in.
        # Kept, because without it F3 stops the run, and rightly: the draw makes the
        # season one round long and the cards have played three (4.40).
        (self.cwd / "config.toml").write_text(
            '[competitions.tuesday-division-b]\nday = "Tuesday"\ndivision = "B"\n'
            'rounds_total = 3\n'
            '[[competitions.tuesday-division-b.rounds]]\nnumber = "1"\ndate = "  "\n',
            encoding="utf-8")
        self.build()
        doc = json.loads((self.cwd / "site" / "tuesday-division-b" / "season.json")
                         .read_text(encoding="utf-8"))
        carded = {m["date"] for m in doc["matches"] if m["round"] == "1"}
        self.assertEqual(len(carded), 1, carded)
        self.assertEqual([r["date"] for r in doc["rounds"] if r["number"] == "1"],
                         sorted(carded))

    def test_a_date_typed_in_words_is_given_as_typed(self):
        """``number = "1 & 2"``, ``date = "6 & 7 Oct"``, a double round over two nights.

        A round's date is whatever the club wrote, and the dashboard gives one it
        cannot read as a date back as it was written; the card does the same, through
        the front page's one date formatter. Both halves are escaped, since both are
        text a club typed going into a page. Rejected: passing over a date that does
        not parse, which would turn the one round the club did date into a draw with
        no dates.
        """
        self.assertEqual(self.facts_for(("1 & 2", "6 & 7 Oct")),
                         "2 teams &middot; round 1 &amp; 2 on 6 &amp; 7 Oct "
                         "&middot; declared in config.toml")

    def test_once_its_cards_arrive_the_card_gives_its_rounds_and_not_the_date(self):
        """A card with a dashboard behind it says how far the season has got.

        The first round's date is for a competition nobody has played, and on a card
        with results it is last month's news above this week's figures. The island
        says the same, so a page built from it cannot differ.
        """
        self.declare(self.draw(("1", "2026-07-21"), ("2", "2026-07-28")))
        write_second_competition(self.cwd / "data" / "division-c")
        self.build()
        card = self.card_for(self.LABEL)
        self.assertIn(f'href="{self.SECTION}/index.html"', card)
        self.assertNotIn("21 Jul", card)
        self.assertIsNone(self.entries()[self.SECTION]["first_round"])

    def test_the_readme_quotes_the_card_this_run_wrote(self):
        readme = (Path(__file__).resolve().parents[1] / "README.md").read_text(
            encoding="utf-8")
        facts = self.facts_for(("1", "2026-10-06"), ("2", "2026-10-13"))
        self.assertIn(f"**{facts.replace(' &middot; ', ' · ')}**", readme,
                      "the README does not quote the small print a card with a "
                      "declared draw carries, so a club cannot look up the date "
                      "they are reading")


class TestAFinalsSeriesRunsInTheOrderItWasPlayed(CliCase):
    """The standard season, then a semi-final on 8 Sep and a grand final on 15 Sep.

    Measured before, on this season (``/tmp/t4/scratch/y437/proto/cli_proto.py``)
    and on the demo's with an ``SF`` and a ``GF`` card added
    (``/tmp/t4/scratch/y437/measure.py``): the season document's rounds ran ``1, 2,
    3, GF, SF``, the report said ``cards 8 across round(s) 1, 2, 3, GF, SF`` and
    ``rounds GF, SF are read as finals``, the review wrote the grand final's draw
    above the semi-final's, since the last build listed ``RGF`` above ``RSF``, and
    a player whose grand-final card printed 3.5 and semi-final card 3.0 was rated
    3.0. In the dashboard the Matches page ended ``Finals — GF``, ``Finals — SF``
    and the overview's Latest round was the semi-final. With the draw declared,
    the semi-final's card alone had the grand final's reported missing, a week
    before it was played, and the grand final's card alone left the semi-final's
    unreported, as a round nobody had played. Every one of those orders is
    :func:`~matchcentre.competition.round_sort_key`, which ordered a round that is
    not a number by its letters (4.37).

    A final's place is the one its label gives it in a series -- QF, SF, PF, then
    GF or F -- and not its date. Rejected: the date, which a declared round need
    not have, a club may type as words, and a card may print wrongly; and which
    most of these lists could not look up, since the one holding the last build's
    matches and a player's ratings holds a round's label and nothing else.
    """

    FINALS = (("SF", "2026-09-08", "riverside-rockets", "hilltop-aces", 3.0),
              ("GF", "2026-09-15", "riverside-rockets", "lakeside-spinners", 3.5))

    def write_finals(self, *labels: str) -> None:
        """A card for each of *labels*, the rockets' roster printing the given rating.

        A new rating on each card, so that which of the two a player ends the season
        on says which card the dashboard took for the later one.
        """
        folder = self.cwd / "data" / "Finals"
        folder.mkdir(parents=True, exist_ok=True)
        for index, (label, when, home, away, rating) in enumerate(self.FINALS):
            if label not in labels:
                continue
            (home_name, home_players), (away_name, away_players) = TEAMS[home], TEAMS[away]
            cardwriter.write_card_file(folder / f"{label}.pdf", cardwriter.CardSpec(
                date=when, round_label=label, division="B", court="50",
                match_id=f"600000{index}", home_name=home_name, away_name=away_name,
                rows=rows_for(((6, 2), (6, 3), (4, 6), (6, 1)), home_players,
                              away_players),
                home_roster=tuple(cardwriter.RosterRow(name=n, singles=rating,
                                                       doubles=rating, captain=not i)
                                  for i, n in enumerate(home_players)),
                away_roster=squad_for(away, away_players)[0]))

    def declare_draw(self, *, finals: bool = True,
                     rounds_total: int | None = 3) -> None:
        """The season as a declared draw, both finals in it with their fixtures.

        No dates, which is how a finals draw is typed before its nights are fixed,
        and the grand final first, which is how text order wrote it back. With
        *finals* false, the regular season alone, as it is typed before the finals
        are drawn. With *rounds_total* None, no length, so the draw gives it.
        """
        rounds = [(rnd, [(TEAMS[h][0], TEAMS[a][0]) for r, h, a, _ in FIXTURES
                         if r == rnd]) for rnd in ("1", "2", "3")]
        if finals:
            rounds += [(label, [(TEAMS[home][0], TEAMS[away][0])])
                       for label, _, home, away, _ in reversed(self.FINALS)]
        (self.cwd / "config.toml").write_text(
            '[competitions.tuesday-division-b]\nday = "Tuesday"\ndivision = "B"\n'
            + ('' if rounds_total is None else f'rounds_total = {rounds_total}\n')
            + f'teams = {json.dumps([name for name, _ in TEAMS.values()])}\n'
            + "".join(f'\n[[competitions.tuesday-division-b.rounds]]\n'
                      f'number = "{number}"\nfixtures = {json.dumps(fixtures)}\n'
                      for number, fixtures in rounds),
            encoding="utf-8")

    def test_the_season_document_lists_the_semi_final_before_the_grand_final(self):
        # The page orders every round it shows by its place in this list, so a round
        # the page sorts and the list leaves out would have no place to take.
        self.write_finals("SF", "GF")
        self.build()
        doc = self.season()
        self.assertEqual([r["number"] for r in doc["rounds"]],
                         ["1", "2", "3", "SF", "GF"])
        self.assertEqual([f["round"] for f in doc["fixtures"]][-2:], ["SF", "GF"])
        self.assertEqual([m["round"] for m in doc["matches"]][-2:], ["SF", "GF"])
        listed = {r["number"] for r in doc["rounds"]}
        sorted_by_page = ({m["round"] for m in doc["matches"]}
                          | {h["round"] for t in doc["teams"]
                             for h in t.get("ladder_history") or ()}
                          | {h["round"] for p in doc["players"]
                             for h in p.get("rating_history") or ()})
        self.assertLessEqual(sorted_by_page, listed)

    def test_a_card_dated_out_of_turn_is_still_the_round_its_label_says(self):
        """The semi-final's card printing a date a week after the grand final's.

        The page puts rounds in the order the document's ``rounds`` lists them, so
        that list is where a date must decide nothing. The finals above are dated in
        the order they are played, where the dates and the labels agree, and
        measured with the exporter's rounds sorted by date first
        (``/tmp/mutate129.py``) no other test failed. A card can print a wrong date,
        and a round put back a week is still the round it was.
        """
        self.FINALS = tuple((label, {"SF": "2026-09-22"}.get(label, when), *rest)
                            for label, when, *rest in self.FINALS)
        self.write_finals("SF", "GF")
        self.build()
        self.assertEqual([r["number"] for r in self.season()["rounds"]],
                         ["1", "2", "3", "SF", "GF"])

    def test_the_report_names_the_finals_in_the_order_they_were_played(self):
        self.write_finals("SF", "GF")
        run = self.build()
        flat = " ".join(run.out.split())
        self.assertIn("cards 8 across rounds 1, 2, 3, SF and GF", flat)
        # And says why they are finals: a label that is not a number need not be one.
        self.assertIn("rounds SF and GF are read as finals because the round label on "
                      "the cards names a final", flat)
        self.assertLess(flat.index("round SF is a finals round"),
                        flat.index("round GF is a finals round"))
        # The draw the review offers to paste into config.toml, which a club edits
        # from the top.
        review = " ".join(self.section(run.out, "review").split())
        self.assertLess(review.index('number = "SF"'), review.index('number = "GF"'))

    def test_a_players_rating_is_the_one_the_grand_final_printed(self):
        """Ana Fernandez: 3.0 on the semi-final's card, 3.5 on the grand final's.

        A rating is the newest one printed, and newest is the last round in the
        season's order. Measured before, it was 3.0, with ``GF`` above ``SF`` in her
        history.
        """
        self.write_finals("SF", "GF")
        self.build()
        ana = next(p for p in self.season()["players"]
                   if p["name"] == "Ana Fernandez")
        self.assertEqual([h["round"] for h in ana["rating_history"]][-2:],
                         ["SF", "GF"])
        self.assertEqual(ana["rating"], {"singles": 3.5, "doubles": 3.5})

    def test_since_the_last_build_lists_the_semi_final_first(self):
        self.build()
        self.write_finals("SF", "GF")
        since = " ".join(self.section(self.build().out,
                                      "since the last build").split())
        self.assertIn("new RSF Riverside Rockets v Hilltop Aces", since)
        self.assertLess(since.index("RSF"), since.index("RGF"))

    def test_a_grand_final_not_played_yet_is_not_missing_its_card(self):
        """The semi-final's card read and the grand final a week away: nothing missing.

        A round is gone past only when a later round has a card, and the grand
        final is not later than its own semi-final. Measured before, the run
        reported ``round GF: no scorecard was read for RIVERSIDE ROCKETS v LAKESIDE
        SPINNERS … while round SF has cards, so the season is past it``.
        """
        self.declare_draw()
        self.write_finals("SF")
        run = self.build()
        self.assertNotIn("card-missing", run.out)
        # And the note on the round says the same, from the same rule.
        self.assertIn("round GF is in the declared draw with no cards at all, which "
                      "is what a round nobody has played yet looks like",
                      " ".join(run.out.split()))
        self.assertEqual([(f["round"], f["card_missing"])
                          for f in self.season()["fixtures"]][-2:],
                         [("SF", False), ("GF", False)])

    def test_a_semi_final_with_no_card_is_missing_once_the_grand_final_has_one(self):
        """The grand final's card read and not the semi-final's: that card is missing.

        Measured before, the run said the semi-final had no cards at all, ``which is
        what a round nobody has played yet looks like``, and asked for nothing.
        """
        self.declare_draw()
        self.write_finals("GF")
        run = self.build()
        flat = " ".join(run.out.split())
        self.assertIn("round SF: no scorecard was read for RIVERSIDE ROCKETS v "
                      "HILLTOP ACES", flat)
        self.assertIn("round SF is in the declared draw with no cards at all, and "
                      "there are cards for later rounds", flat)
        self.assertEqual([(f["round"], f["card_missing"])
                          for f in self.season()["fixtures"]][-2:],
                         [("SF", True), ("GF", False)])

    def test_a_semi_final_spelt_out_is_played_after_the_quarter_final(self):
        """A draw of ``QF`` then ``Semi-Final``, and the quarter-final's card alone.

        Measured (``/tmp/t4/scratch/y437/fix/probe_hyphen.py``, after the review's
        probe): with the finals table read as typed, ``Semi-Final`` was a name with
        no week in the series and went ahead of every final, so the quarter-final's
        card put the season past it -- ``card-missing`` for its fixture, and ``round
        Semi-Final is in the declared draw with no cards at all, and there are cards
        for later rounds`` -- whether or not the club had set ``finals = true`` on
        it. The unfixed tree got the order right by the luck of its letters, Q
        before S, and scored the semi-final as a regular round.
        """
        self.FINALS = (("QF",) + self.FINALS[0][1:],
                       ("Semi-Final",) + self.FINALS[1][1:])
        self.declare_draw()
        self.write_finals("QF")
        run = self.build()
        self.assertNotIn("card-missing", run.out)
        doc = self.season()
        self.assertEqual([(r["number"], r["is_finals"]) for r in doc["rounds"]][-2:],
                         [("QF", True), ("Semi-Final", True)])
        self.assertEqual([(f["round"], f["card_missing"])
                          for f in doc["fixtures"]][-2:],
                         [("QF", False), ("Semi-Final", False)])

    def test_a_semi_final_spelt_out_is_a_final_with_no_draw_declared(self):
        """A card labelled ``Semi-Final``, and no draw: kept out of the ladder, as ``SF``.

        Measured before (``/tmp/t4/scratch/y437/fix/label_card.py``): the suite's
        season plus a ``Semi-Final`` card was scored as a regular round, the match
        counted for the ladder and Hilltop Aces on 4 played, with F11's ``round
        label 'Semi-Final' is neither a number nor a finals label this program
        recognises; it is being scored as a regular round``. The label a club's
        finals are printed under is read by its letters, as the order reads it.
        """
        self.FINALS = (("Semi-Final",) + self.FINALS[0][1:],)
        self.write_finals("Semi-Final")
        run = self.build()
        flat = " ".join(run.out.split())
        self.assertNotIn("neither a number nor a finals label", flat)
        self.assertIn("round Semi-Final is read as finals", flat)
        doc = self.season()
        self.assertEqual([(r["number"], r["is_finals"]) for r in doc["rounds"]][-1],
                         ("Semi-Final", True))
        self.assertEqual({m["counts_for_ladder"] for m in doc["matches"]
                          if m["round"] == "Semi-Final"}, {False})

    def test_a_semi_final_spelt_out_is_not_a_round_of_the_regular_season(self):
        """A draw of 1 to 3, ``QF`` and ``Semi-Final`` with no length: 3 rounds long.

        A season's length is the rounds its draw lists, finals left out. Measured
        before (``/tmp/t4/scratch/y437/fix/probe_length.py``), the semi-final was
        counted as a fourth regular round: ``meta.rounds_total`` 4, and ``the season
        is declared as 4 rounds long``.
        """
        self.FINALS = (("QF",) + self.FINALS[0][1:],
                       ("Semi-Final",) + self.FINALS[1][1:])
        self.declare_draw(rounds_total=None)
        self.write_finals("QF")
        self.build()
        self.assertEqual(self.season()["meta"]["rounds_total"], 3)

    # The notes on a declared draw, each of which lists rounds in the order it asks
    # the key for. Named together or one at a time, the finals come in the order
    # they are played.

    def test_a_draw_awaiting_its_finals_names_them_in_the_order_they_are_played(self):
        self.declare_draw()
        flat = " ".join(self.build().out.split())
        self.assertIn("rounds SF and GF are in the declared draw with no cards at all, "
                      "which is what rounds nobody has played yet looks like", flat)

    def test_the_rounds_with_cards_are_listed_in_the_order_they_were_played(self):
        self.declare_draw()
        self.write_finals("SF", "GF")
        flat = " ".join(self.build().out.split())
        # The finals apart from the regular rounds the length counts (4.69), and
        # still in the order they were played.
        self.assertIn("3 regular rounds (1, 2 and 3) and 2 finals rounds (SF and GF)",
                      flat)

    def test_finals_the_draw_does_not_list_are_named_in_the_order_they_were_played(self):
        self.declare_draw(finals=False)
        self.write_finals("SF", "GF")
        flat = " ".join(self.build().out.split())
        self.assertIn("cards were found for rounds SF and GF, which the declared draw "
                      "does not list", flat)

    def test_finals_built_from_two_years_of_cards_are_named_in_the_order_played(self):
        """Last season's finals cards left in the folder beside this season's.

        The note is the one reader of the order discovery sorts its matches in.
        Measured (``/tmp/t4/scratch/y437/fix/probe_years.py``), the unfixed tree
        said ``rounds GF and SF are built from cards played in more than one year``.
        The run's exit is not asserted: two seasons' cards on one ladder have errors
        of their own, which is why the note exists.
        """
        self.write_finals("SF", "GF")
        folder = self.cwd / "data" / "Finals"
        for label in ("SF", "GF"):
            (folder / f"{label}.pdf").rename(folder / f"{label}-2026.pdf")
        self.FINALS = (("SF", "2025-09-09", "lakeside-spinners", "parkview-wanderers", 3.0),
                       ("GF", "2025-09-16", "hilltop-aces", "lakeside-spinners", 3.5))
        self.write_finals("SF", "GF")
        flat = " ".join(self.build(expect=None).out.split())
        self.assertIn("rounds SF and GF are built from cards played in more than one "
                      "year", flat)


class TestAFinalTheDrawNamesItsOwnWayIsPlayedWhereTheDrawPutsIt(CliCase):
    """The standard season, then a draw of QF, ``Major Semi`` and GF, all typed finals.

    Measured before (``/tmp/t7/scratch/ROUNDS/probe.py``, ``before.out``), on the demo
    with rounds 1 to 3, ``QF``, ``Major Semi`` and ``GF`` declared, all three ``finals
    = true``, and the QF's card alone: the season document's rounds ran ``1, 2, 3,
    Major Semi, QF, GF``; ``card-missing`` said of the Major Semi's fixture that
    ``nothing at all was read for that round while round QF has cards, so the season
    is past it``, and it was ``card_missing``; and the note said the round was in the
    declared draw with no cards at all ``and there are cards for later rounds``. A
    card prints its round as one word, so the Major Semi's cards are a ``Playoff``'s
    here, and with all three read the report said ``cards 12 across round(s) 1, 2,
    3, Playoff, QF, GF``, the notes and F11 named the Playoff first, since the last
    build listed ``RPlayoff`` first, and a player's latest rating was the QF's. With
    a second section of those three finals dated and no card, the front page gave
    ``round Major Semi on 14 Oct 2026`` as its first night. Each of those orders is
    :func:`~matchcentre.competition.round_sort_key`, which read the label alone, and
    ``Major Semi`` names no week of a finals series: it went with the names, ahead
    of every final.

    The draw is the one place that says it is a final and where it comes, so every
    list of a competition's rounds asks the key with the draw (4.71). Rejected: the
    draw's order for every round, which would move every season whose rounds are
    typed out of turn, where the numbers already say the week; and the round's date,
    which 4.37 rejected, since a finals draw is typed before its nights are fixed.
    """

    # The rockets' roster prints a new rating on each card, so which one a player
    # ends on says which card came last; and loses the QF and wins the Playoff, so
    # the run a player is on says the same.
    FINALS = (("QF", "2026-09-08", "hilltop-aces", 3.0,
               ((2, 6), (3, 6), (4, 6), (1, 6))),
              ("Playoff", "2026-09-15", "lakeside-spinners", 3.5,
               ((6, 2), (6, 3), (6, 4), (6, 1))),
              ("GF", "2026-09-22", "parkview-wanderers", 4.0,
               ((6, 2), (6, 3), (4, 6), (6, 1))))
    COMP = "tuesday-division-b"

    def write_finals(self, *labels: str, against: dict[str, str] | None = None,
                     flipped: bool = False) -> None:
        """A card for each of *labels*: the rockets at home to the team it names.

        *against* names another team for a label, a fixture the draw does not list;
        *flipped* turns every set's score round, so the same fixture is rescored.
        """
        folder = self.cwd / "data" / "Finals"
        folder.mkdir(parents=True, exist_ok=True)
        home_name, home_players = TEAMS["riverside-rockets"]
        for index, (label, when, away, rating, scores) in enumerate(self.FINALS):
            if label not in labels:
                continue
            away = (against or {}).get(label, away)
            if flipped:
                scores = tuple((theirs, ours) for ours, theirs in scores)
            away_name, away_players = TEAMS[away]
            cardwriter.write_card_file(folder / f"{label}.pdf", cardwriter.CardSpec(
                date=when, round_label=label, division="B", court="50",
                match_id=f"700000{index}", home_name=home_name, away_name=away_name,
                rows=rows_for(scores, home_players, away_players),
                home_roster=tuple(cardwriter.RosterRow(name=n, singles=rating,
                                                       doubles=rating, captain=not i)
                                  for i, n in enumerate(home_players)),
                away_roster=squad_for(away, away_players)[0]))

    def declare(self, name: str = "Playoff", *, extra: str = "") -> None:
        """Rounds 1 to 3, then the QF, *name* and the GF, each typed ``finals = true``.

        Every round with its fixtures, as a club types a draw it was handed.
        *extra* is more config after it.
        """
        rounds = [(rnd, [[TEAMS[h][0], TEAMS[a][0]] for r, h, a, _ in FIXTURES
                         if r == rnd], "") for rnd in ("1", "2", "3")]
        rounds += [(name if label == "Playoff" else label,
                    [[TEAMS["riverside-rockets"][0], TEAMS[away][0]]],
                    "finals = true\n") for label, _, away, _, _ in self.FINALS]
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f'teams = {json.dumps([name for name, _ in TEAMS.values()])}\n'
            + "".join(f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "{number}"\n'
                      f"fixtures = {json.dumps(fixtures)}\n{typed}"
                      for number, fixtures, typed in rounds) + extra,
            encoding="utf-8")

    def named(self, flat: str, says: str) -> list[str]:
        """The finals the one sentence of *flat* that *says* names, in its order.

        By where each stands in the sentence and not by the list's commas: 4.169 is
        to join these lists as a sentence does, ``QF, Playoff and GF``, and what
        these tests pin is the order, not the join.
        """
        found = [s for s in flat.split(". ") if says in s]
        self.assertEqual(len(found), 1, f"{says!r} is said in {found}")
        return sorted((label for label in ("QF", "Major Semi", "Playoff", "GF")
                       if label in found[0]), key=found[0].index)

    # The row's own draw, and the QF's card alone.

    def test_the_season_document_lists_its_rounds_as_the_draw_declares_them(self):
        self.declare("Major Semi")
        self.write_finals("QF")
        self.build()
        doc = self.season()
        self.assertEqual([r["number"] for r in doc["rounds"]],
                         ["1", "2", "3", "QF", "Major Semi", "GF"])
        self.assertEqual([f["round"] for f in doc["fixtures"]][-3:],
                         ["QF", "Major Semi", "GF"])

    def test_a_final_nobody_has_played_yet_is_not_missing_its_card(self):
        self.declare("Major Semi")
        self.write_finals("QF")
        run = self.build()
        self.assertNotIn("card-missing", run.out)
        self.assertEqual([(f["round"], f["card_missing"])
                          for f in self.season()["fixtures"]][-3:],
                         [("QF", False), ("Major Semi", False), ("GF", False)])
        # And the note on the two rounds says the same, from the same rule.
        self.assertEqual(self.named(" ".join(run.out.split()),
                                    "which is what rounds nobody has played yet "
                                    "looks like"), ["Major Semi", "GF"])

    def test_it_is_missing_its_card_once_the_grand_final_has_one(self):
        """The QF's and the GF's cards and none for the Major Semi: that one is missing.

        Gone past once a later round has a card, and the later round the finding
        names is the grand final. Measured before, it named the QF, which is played
        the week before.
        """
        self.declare("Major Semi")
        self.write_finals("QF", "GF")
        flat = " ".join(self.build().out.split())
        self.assertIn("round Major Semi: no scorecard was read for RIVERSIDE ROCKETS "
                      "v LAKESIDE SPINNERS, which the declared draw lists, and "
                      "nothing at all was read for that round while round GF has "
                      "cards, so the season is past it", flat)
        self.assertEqual([(f["round"], f["card_missing"])
                          for f in self.season()["fixtures"]][-3:],
                         [("QF", False), ("Major Semi", True), ("GF", False)])

    def test_a_draw_awaiting_its_finals_names_them_in_the_order_they_are_played(self):
        self.declare("Major Semi")
        flat = " ".join(self.build().out.split())
        self.assertEqual(self.named(flat, "in the declared draw with no cards at all"),
                         ["QF", "Major Semi", "GF"])

    # A final a card can print, and every card read.

    def test_its_cards_are_listed_between_the_quarter_and_the_grand_final(self):
        self.declare()
        self.write_finals("QF", "Playoff", "GF")
        run = self.build()
        doc = self.season()
        played = ["1", "2", "3", "QF", "Playoff", "GF"]
        self.assertEqual([r["number"] for r in doc["rounds"]], played)
        self.assertEqual([m["round"] for m in doc["matches"]][-3:], played[-3:])
        self.assertEqual(doc["meta"]["rounds_present"], played)
        self.assertIn("cards 9 across rounds 1, 2, 3, QF, Playoff and GF",
                      " ".join(run.out.split()))

    def test_its_card_of_a_fixture_the_draw_does_not_list_follows_the_qf_s(self):
        """The QF's and the Playoff's cards each of the other's pair: the draw is wrong.

        The season document lists the draw's fixtures, then each card of a fixture
        the draw does not list, so the club is shown the card that proves it wrong,
        in the order the season runs. Measured with those cards sorted by the label
        alone, or handed a draw of nothing, the Playoff's came first.
        """
        self.declare()
        self.write_finals("QF", "Playoff", against={"QF": "lakeside-spinners",
                                                    "Playoff": "hilltop-aces"})
        self.build()
        self.assertEqual([(f["round"], f["away"], f["played"])
                          for f in self.season()["fixtures"]][-5:],
                         [("QF", "hilltop-aces", False),
                          ("Playoff", "lakeside-spinners", False),
                          ("GF", "parkview-wanderers", False),
                          ("QF", "lakeside-spinners", True),
                          ("Playoff", "hilltop-aces", True)])

    def test_the_notes_name_the_finals_in_the_order_they_were_played(self):
        self.declare()
        self.write_finals("QF", "Playoff", "GF")
        flat = " ".join(self.build().out.split())
        for says in ("3 finals rounds", "are declared as finals"):
            with self.subTest(says=says):
                self.assertEqual(self.named(flat, says), ["QF", "Playoff", "GF"])

    def test_the_checks_name_the_finals_in_the_order_they_were_played(self):
        self.declare()
        self.write_finals("QF", "Playoff", "GF")
        flat = " ".join(self.build().out.split())
        said = [flat.index(f"round {label} is a finals round")
                for label in ("QF", "Playoff", "GF")]
        self.assertEqual(said, sorted(said))

    def test_since_the_last_build_lists_its_card_between_the_others(self):
        """Built first with no draw typed, then with the draw and the three cards.

        So only this build's document says the Playoff is a final: the change list
        is ordered by the draw of the document being written. Rejected: the draw
        of the one it replaces, which lists no final at all here.
        """
        self.build()
        self.declare()
        self.write_finals("QF", "Playoff", "GF")
        since = " ".join(self.section(self.build().out,
                                      "since the last build").split())
        said = [since.index(f"new R{label} ") for label in ("QF", "Playoff", "GF")]
        self.assertEqual(said, sorted(said))

    def test_since_the_last_build_lists_what_changed_in_the_same_order(self):
        """The QF's and the Playoff's cards read with no draw, then rescored under it.

        What is new, what changed and what is gone are one list in one order, and
        each part is sorted on its own. Measured with only what changed sorted by
        the draw of the document it replaces, the Playoff's line came first, and
        every other test of this class passed.
        """
        self.write_finals("QF", "Playoff")
        self.build()
        self.declare()
        self.write_finals("QF", "Playoff", flipped=True)
        since = " ".join(self.section(self.build().out,
                                      "since the last build").split())
        said = [since.index(f"changed R{label} ") for label in ("QF", "Playoff")]
        self.assertEqual(said, sorted(said))

    def test_since_the_last_build_lists_what_is_gone_in_the_same_order(self):
        """The QF's and the Playoff's cards read with no draw, then the draw alone.

        Both fixtures are still in the draw, which says the Playoff is a final, so
        it is listed after the QF as the dashboard lists it.
        """
        self.write_finals("QF", "Playoff")
        self.build()
        self.declare()
        shutil.rmtree(self.cwd / "data" / "Finals")
        since = " ".join(self.section(self.build().out,
                                      "since the last build").split())
        said = [since.index(f"gone R{label} ") for label in ("QF", "Playoff")]
        self.assertEqual(said, sorted(said))

    def test_a_players_rating_and_run_are_the_last_final_s_played(self):
        """Ana Fernandez: 3.0 on the QF's card and lost, 3.5 on the Playoff's and won.

        Newest is the last round in the season's order. Measured before, with the
        Playoff sorted first, her rating was the QF's.
        """
        self.declare()
        self.write_finals("QF", "Playoff")
        self.build()
        ana = next(p for p in self.season()["players"]
                   if p["name"] == "Ana Fernandez")
        self.assertEqual([h["round"] for h in ana["rating_history"]][-2:],
                         ["QF", "Playoff"])
        self.assertEqual(ana["rating"], {"singles": 3.5, "doubles": 3.5})
        self.assertEqual(ana["streak"]["type"], "W")

    def test_the_front_page_gives_the_first_final_the_draw_lists(self):
        """A second section, the three finals dated and no card: its first night.

        Measured before: ``round Major Semi on 14 Oct 2026``, the second night.
        """
        self.declare(extra=(
            '\n[competitions.thursday-division-1]\nday = "Thursday"\n'
            'division = "1"\n' + "".join(
                f'\n[[competitions.thursday-division-1.rounds]]\nnumber = "{number}"\n'
                f'date = "{when}"\nfinals = true\n'
                for number, when in (("QF", "2026-10-07"), ("Major Semi", "2026-10-14"),
                                     ("GF", "2026-10-21")))))
        self.build()
        front = " ".join((self.cwd / "site" / "index.html").read_text(
            encoding="utf-8").split())
        self.assertIn("round QF on 7 Oct 2026", front)
        self.assertNotIn("round Major Semi on", front)


class FinalsDrawCase(CliCase):
    """The standard season, a semi-final card, and a declared draw with ``finals`` typed."""

    FINALS = TestAFinalsSeriesRunsInTheOrderItWasPlayed.FINALS
    write_finals = TestAFinalsSeriesRunsInTheOrderItWasPlayed.write_finals
    COMP = "tuesday-division-b"

    def declare(self, finals: dict[str, str], *, later: tuple[str, ...] = (),
                total: int | None = None) -> None:
        """Rounds 1 to 3 and the SF with their fixtures, then *later* with none.

        ``rounds_total`` is *total*, and with none the draw gives the length. *finals*
        is what is typed after ``finals =`` in each round it names, and nothing is
        typed in the rest.
        """
        rounds = [(rnd, [[TEAMS[h][0], TEAMS[a][0]] for r, h, a, _ in FIXTURES
                         if r == rnd]) for rnd in ("1", "2", "3")]
        rounds.append(("SF", [[TEAMS["riverside-rockets"][0],
                               TEAMS["hilltop-aces"][0]]]))
        rounds += [(number, []) for number in later]
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f'teams = {json.dumps([name for name, _ in TEAMS.values()])}\n'
            + (f"rounds_total = {total}\n" if total is not None else "")
            + "".join(f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "{number}"\n'
                      + (f"fixtures = {json.dumps(fixtures)}\n" if fixtures else "")
                      + (f"finals = {finals[number]}\n" if number in finals else "")
                      for number, fixtures in rounds),
            encoding="utf-8")

    def finals_in(self, doc: dict) -> dict[str, bool]:
        return {r["number"]: r["is_finals"] for r in doc["rounds"]}


class TestARoundDeclaredRegularIsScoredInTheLadderWhateverItsLabel(FinalsDrawCase):
    """``finals = false`` on a round labelled as a final keeps it in the ladder.

    It was ignored. The loader read the key as true or not true, so false and not
    typed were one value, and discovery took a label that names a final over it.
    Measured on the demo with a declared draw of rounds 1 to 3 and ``SF`` typed
    ``finals = false``, over three SF cards (/tmp/t6/scratch/m2/p470): the SF's
    matches were ``counts_for_ladder`` false, the ladder's matches played ``[2, 2, 3,
    3, 3, 3]``, the draw three regular rounds long, and the run said ``round SF is
    declared as finals ... Set finals = true or false ... to decide it yourself`` and
    F11 ``Set finals = false ... if this round is really a regular one``, both
    beside the line that did just that. The note also said "declared" of an SF the
    club typed nothing on. Now a typed value decides, a round with none is read by
    its label, and the note says which of the two it was. Rejected: reading a false
    the label contradicts as a slip, which leaves the setting the note offers with
    no effect.
    """

    def test_its_matches_count_for_the_ladder(self):
        self.declare({"SF": "false"})
        self.write_finals("SF")
        self.build()
        doc = self.season()
        self.assertFalse(self.finals_in(doc)["SF"])
        self.assertEqual({m["counts_for_ladder"] for m in doc["matches"]
                          if m["round"] == "SF"}, {True})
        self.assertEqual(sorted(t["played"] for t in doc["teams"]), [3, 3, 4, 4])
        # And it is one of the season's regular rounds: 1, 2, 3 and SF.
        self.assertEqual(doc["meta"]["rounds_total"], 4)

    def test_the_run_does_not_ask_for_what_the_club_typed(self):
        self.declare({"SF": "false"})
        self.write_finals("SF")
        flat = " ".join(self.build().out.split())
        self.assertNotIn("round SF is declared as finals", flat)
        self.assertNotIn("round SF is a finals round", flat)
        self.assertNotIn("to decide it yourself", flat)

    def test_left_out_the_label_decides_and_the_note_says_it_was_the_label(self):
        self.declare({})
        self.write_finals("SF")
        flat = " ".join(self.build().out.split())
        self.assertTrue(self.finals_in(self.season())["SF"])
        self.assertIn(f"round SF is read as finals because the round label names a "
                      f"final, and earns no ladder points. Set finals = true or false "
                      f"under [[competitions.{self.COMP}.rounds]] to decide it "
                      f"yourself.", flat)
        self.assertNotIn("declared as finals", flat)

    def test_typed_true_the_note_says_declared_and_asks_nothing(self):
        self.declare({"3": "true", "SF": "true"})
        self.write_finals("SF")
        flat = " ".join(self.build().out.split())
        self.assertIn("rounds 3 and SF are declared as finals, and earn no ladder "
                      "points.", flat)
        self.assertNotIn("to decide it yourself", flat)

    def test_a_typed_final_and_one_read_off_its_label_are_each_said_as_theirs(self):
        self.declare({"3": "true"}, later=("GF",))
        self.write_finals("SF")
        flat = " ".join(self.build().out.split())
        self.assertIn("round 3 is declared as finals, and earns no ladder points.",
                      flat)
        self.assertIn("rounds SF and GF are read as finals because the round label "
                      "names a final, and earn no ladder points. Set finals",
                      flat)


class TestTheRefusalNamesAFinalTheDrawDeclaresAgainstItsLabel(FinalsDrawCase):
    """``--discover`` without ``--force`` says which declared finals go with the draw.

    Finals are declared only in ``[[…rounds]]`` blocks and ``--force`` drops every
    one, so the run after it tells a final by its label alone. Measured on the
    four-round demo with a draw of rounds 1 to 4 and round 3 typed ``finals = true``
    (/tmp/t6/scratch/m2/p466): the refusal named the dates, fixtures and byes the
    blocks hold and nothing else; after ``--force`` round 3 was a regular round, the
    ladder's matches played went from ``[2, 2, 3, 3, 3, 3]`` to ``[3, 3, 4, 4, 4,
    4]``, and the run exited 1 on F3 over the length of 3 the draw had given. With
    ``rounds_total = 4`` typed it exited 0, on the other ladder with nothing said.
    A round is named when what was typed on it is not what its label gives, in
    either direction, and only then: a GF typed ``finals = true`` loses nothing.
    Rejected: carrying the key through in a ``[[…rounds]]`` block of its own, which
    is a declared draw of one round; measured, the run on it noted "cards were found
    for rounds 1, 2, 4, which the declared draw does not list".
    """

    TYPED = {"1": "false", "3": "true", "SF": "false", "GF": "true"}

    def refused(self) -> str:
        self.declare(self.TYPED, later=("GF",))
        self.write_finals("SF")
        # Moved by 4.431: what the refusal said, the proposal's header says.
        return proposal_of(self)

    def test_a_final_typed_on_a_numbered_round_is_named(self):
        self.assertIn(f"round 3 of {self.COMP} is scored in the ladder as a regular "
                      f"round, not as the final you declared", self.refused())

    def test_a_regular_round_typed_on_a_finals_label_is_named(self):
        self.assertIn(f"round SF of {self.COMP} is left out of the ladder as a final, "
                      f"not scored as the regular round you declared", self.refused())

    def test_rounds_moved_either_way_are_said_in_one_sentence(self):
        self.assertIn(f"not as the final you declared, and round SF of {self.COMP} "
                      f"is left out", self.refused())

    def test_rounds_moved_the_same_way_are_said_together(self):
        self.declare({"1": "true", "2": "true", "3": "true"})
        self.write_finals("SF")
        said = proposal_of(self)  # moved by 4.431: the proposal's header
        self.assertIn(f"round 1 of {self.COMP}, round 2 of {self.COMP} and round 3 of "
                      f"{self.COMP} are scored in the ladder as regular rounds, not as "
                      f"the finals you declared.", said)

    def test_a_final_is_named_where_rounds_total_is_typed_and_nothing_else_says_it(self):
        # With the length typed, it is written back as typed, the run after --force
        # fits it and exits 0, and the refusal is the one place the move is said.
        self.declare({"3": "true"}, total=3)
        self.write_finals("SF")
        said = proposal_of(self)  # moved by 4.431: the proposal's header
        self.assertIn(f"round 3 of {self.COMP} is scored in the ladder as a regular "
                      f"round, not as the final you declared", said)
        self.build("--discover", "--force")
        self.build()
        self.assertFalse(self.finals_in(self.season())["3"])

    def test_a_round_whose_label_says_what_was_typed_is_not(self):
        said = self.refused()
        self.assertNotIn("round 1 of", said)
        self.assertNotIn("round GF of", said)

    def test_a_draw_whose_labels_say_it_all_is_told_nothing_of_finals(self):
        self.declare({"1": "false", "SF": "true"})
        self.write_finals("SF")
        said = proposal_of(self)  # moved by 4.431: the proposal's header
        self.assertIn("the dates, fixtures, byes and notes they hold.", said)
        self.assertNotIn("you declared", said)

    def test_and_what_it_names_is_what_the_run_after_force_does(self):
        self.declare(self.TYPED, later=("GF",))
        self.write_finals("SF")
        self.build()
        before = self.finals_in(self.season())
        self.build("--discover", "--force")
        # Whatever it exits: a length --force writes from the draw can be one F3
        # holds the next run's regular rounds against, which is not this row's.
        self.build(expect=None)
        after = self.finals_in(self.season())
        self.assertEqual({n: before[n] for n in ("1", "3", "SF")},
                         {"1": False, "3": True, "SF": False})
        self.assertEqual({n: after[n] for n in ("1", "3", "SF")},
                         {"1": False, "3": False, "SF": True})


class TestForceWritesTheSeasonLengthTheRunAfterItReads(FinalsDrawCase):
    """``--discover --force`` counts the length it writes as the run after counts rounds.

    The rewrite drops the draw and every ``finals`` typed in it, so the run after it
    tells a final by its label alone (4.66), and it wrote the length the draw gave
    under the flags it had just dropped. Measured on the suite's season with SF
    cards (/tmp/t7/scratch/CFORCE/p162): with round 3 typed ``finals = true`` the
    run before read ``2 of 2``, ``--force`` wrote ``rounds_total = 2``, and the run
    after exited 1 on F3, "rounds_total is declared as 2 but 3 regular rounds have
    been played"; with SF typed ``finals = false`` it read ``4 of 4``, ``--force``
    wrote 4, and the run after read ``3 of 4`` with SF a final, a season one round
    longer than its regular rounds. With every regular round typed a final it wrote
    the commented line counted as no round played, and a second ``--force`` wrote
    another. Now the length is counted under the labels, the refusal names it beside
    the round it follows, and a ``rounds_total`` the club typed is written as typed.
    Rejected: keeping the count under the typed flags, which the run after either
    stops on or reads a season longer than its regular rounds, with nothing said.
    Counted so, a draw that leaves out a round with cards can be one the run after
    finds played past, and is written commented out, as a draw this run finds played
    past already was (/tmp/t7/scratch/CFORCE/corner); the rounds played the comment
    offers instead are counted as the run after counts them too (corner2), and the
    file says why the length went, as it does for that draw. The refusal is printed
    before a card is read, so each length it names is said with what can keep it
    out, a length the draw gave or the labels give played past; and it names one
    for every section whose rounds move, where it named only a length that moved and
    said its proviso once for them all (/tmp/t7/scratch/CFORCE/fixup).
    """

    def config(self) -> str:
        return (self.cwd / "config.toml").read_text(encoding="utf-8")

    def forced(self, finals: dict[str, str], **declared) -> list[str]:
        """The live ``rounds_total`` lines ``--force`` writes over *finals*."""
        self.declare(finals, **declared)
        self.write_finals("SF")
        self.build("--discover", "--force")
        return [line for line in self.config().splitlines()
                if line.startswith("rounds_total")]

    def rounds(self) -> tuple[int, int | None]:
        meta = self.season()["meta"]
        return meta["rounds_played"], meta["rounds_total"]

    def test_a_round_typed_a_final_is_counted_as_the_regular_round_it_becomes(self):
        self.assertEqual(self.forced({"3": "true"}), ["rounds_total = 3"])
        flat = " ".join(self.build().out.split())        # exit 0
        self.assertNotIn("rounds_total is declared as", flat)
        self.assertFalse(self.finals_in(self.season())["3"])
        self.assertEqual(self.rounds(), (3, 3))

    def test_a_final_typed_regular_is_counted_as_the_final_it_becomes(self):
        self.assertEqual(self.forced({"SF": "false"}), ["rounds_total = 3"])
        flat = " ".join(self.build().out.split())
        self.assertNotIn("the season is declared as 4 rounds long", flat)
        self.assertTrue(self.finals_in(self.season())["SF"])
        self.assertEqual(self.rounds(), (3, 3))

    def test_a_draw_whose_every_regular_round_was_typed_a_final_gets_its_length(self):
        # It was ``# rounds_total = 1``, under "0 rounds played", and the next
        # --force wrote ``# rounds_total = 3``.
        self.assertEqual(self.forced({"1": "true", "2": "true", "3": "true"}),
                         ["rounds_total = 3"])
        self.build()
        self.assertEqual(self.rounds(), (3, 3))

    def test_a_rounds_total_the_club_typed_is_written_as_typed(self):
        self.assertEqual(self.forced({"SF": "false"}, total=4), ["rounds_total = 4"])

    def unlisted(self, finals: dict[str, str] | None = None, **declared) -> None:
        """The draw of ``declare`` with the SF typed regular and round 3 left out.

        Round 3 has cards and the SF none, so the run before counts rounds 1, 2 and
        3 against a draw of 1, 2 and SF, three of three. The run after reads the SF
        as a final, so the draw is two rounds long, and the cards have played three.
        *finals* is typed in the rounds it names as well.
        """
        self.declare({"SF": "false", **(finals or {})}, **declared)
        self.leave_out_round_three()

    def leave_out_round_three(self) -> None:
        """Round 3's block taken out of the draw declared, and its cards kept."""
        head, _, tail = self.config().partition(
            f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "3"\n')
        (self.cwd / "config.toml").write_text(head + tail[tail.index("\n[["):],
                                              encoding="utf-8")

    def test_a_length_the_run_after_finds_played_past_is_written_commented_out(self):
        # Measured (/tmp/t7/scratch/CFORCE/corner): written live as the labels count
        # it, rounds_total = 2 stopped the run after on F3, where the run before
        # exited 0. The rule is the one for a draw this run finds played past, and
        # the file says why, as it does for that. The base wrote rounds_total = 3
        # here, counted with the SF regular, which the run after read as 3 of 3
        # because round 3's cards made up the third (/tmp/t7/scratch/CFORCE/fixup,
        # base.out, C): the one shape the fix loses a working live length on.
        self.unlisted()
        self.build()
        self.assertEqual(self.rounds(), (3, 3))
        self.assertIn(f"so rounds_total = 2 is written for {self.COMP} where your draw "
                      f"gave it 3 rounds, unless its cards have played past either "
                      f"length.",
                      proposal_of(self))  # moved by 4.431: the proposal's header
        self.build("--discover", "--force")
        self.assertNotIn("\nrounds_total", self.config())
        # Moved by 4.465: the length's line, with nothing after its =.
        self.assertIn("\n# rounds_total =\n", self.config())
        flat = " ".join(line.lstrip("# ") for line in self.config().splitlines())
        self.assertIn("The draw you declared gave the season 2 rounds, with a round "
                      "counted a final only if its label names one, and cards were "
                      "found for 3 regular rounds, so that length is not written "
                      "here.", flat)
        flat = " ".join(self.build().out.split())       # exit 0
        self.assertNotIn("rounds_total is declared as", flat)
        self.assertEqual(self.rounds(), (3, None))

    def test_the_rounds_it_is_played_past_by_are_those_the_run_after_counts(self):
        # Round 2 typed a final as well: the run before counts rounds 1 and 3 against
        # a draw of 1 and SF, two of two, and the run after counts 1, 2 and 3 against
        # a draw of 1 and 2. Measured (/tmp/t7/scratch/CFORCE/corner2), rounds_total
        # = 2 was written live and the run after exited 1 on F3.
        self.unlisted({"2": "true"})
        self.build()
        self.assertEqual(self.rounds(), (2, 2))
        self.build("--discover", "--force")
        self.assertNotIn("\nrounds_total", self.config())
        self.build()
        self.assertEqual(self.rounds(), (3, None))

    def test_the_count_the_commented_line_names_is_the_run_afters(self):
        # Counted as this run counts, under the typed flags, it would offer
        # ``# rounds_total = 2`` beside "2 rounds played", where the run after says
        # 3 and stops on 2 if the # is taken off. The base wrote that 2 live on
        # this draw (/tmp/t7/scratch/CFORCE/fixup, base.out, B), and offered it
        # commented so on a draw of 1 and 2 typed true, which its cards outgrew
        # (/tmp/t7/scratch/CFORCE/corner).
        # Moved by 4.465, and renamed from
        # test_the_count_the_commented_line_offers_is_the_run_afters: the count is
        # named in the comment, and the line offers none.
        self.unlisted({"2": "true"})
        self.build("--discover", "--force")
        self.assertIn('Without it the dashboard says "3 rounds played" and shows no '
                      'percentage', written_flat(self.config()))
        self.assertIn("\n# rounds_total =\n", self.config())

    def test_a_draw_this_run_finds_played_past_has_no_length_written_live(self):
        # The draw gives rounds 1 and 2, and round 3 has cards it does not list, so
        # F3 stops this run. By the labels it gives 3, rounds 1, 2 and 4, which the
        # three played do not pass: written live, the run after read them as a
        # season over, 3 of 3, with round 4 of the draw not played. Any count of a
        # draw its cards outgrew is a count of rounds other than the ones played.
        self.declare({"4": "true"}, later=("4",))
        self.leave_out_round_three()
        self.build(expect=1)
        self.build("--discover", "--force", expect=1)
        self.assertNotIn("\nrounds_total", self.config())
        flat = " ".join(line.lstrip("# ") for line in self.config().splitlines())
        self.assertIn("The draw you declared gave the season 2 rounds, and cards "
                      "were found for round 3, which it does not list", flat)
        # Moved by 4.465: the length's line, with nothing after its =.
        self.assertIn("\n# rounds_total =\n", self.config())
        self.build()
        self.assertEqual(self.rounds(), (3, None))

    def test_the_refusal_says_the_length_the_draw_gave_can_keep_it_out_too(self):
        # The draw above. Said "unless the cards have played past it", the refusal
        # promised a 3 the three played do not pass, and --force wrote it commented
        # for the draw's own 2, which they do: F3 stops this run on that one.
        self.declare({"4": "true"}, later=("4",))
        self.leave_out_round_three()
        self.assertIn(f"so rounds_total = 3 is written for {self.COMP} where your "
                      f"draw gave it 2 rounds, unless its cards have played past "
                      f"either length. The file is written fresh",
                      proposal_of(self))  # moved by 4.431: the proposal's header

    def test_a_length_both_runs_find_played_past_is_said_why_once(self):
        # Round 2 typed a final and round 3 left out: this run counts rounds 1 and 3
        # against the draw's 1, and F3 stops it, and the run after would count 1, 2
        # and 3 against the labels' 2 (/tmp/t7/scratch/CFORCE/fixup2, F-after.out).
        # Either keeps the length out, and the file says the one this run stopped
        # on, where the club has already been told of it.
        self.declare({"2": "true"})
        self.leave_out_round_three()
        self.build("--discover", "--force", expect=1)
        flat = " ".join(line.lstrip("# ") for line in self.config().splitlines())
        self.assertIn("The draw you declared gave the season 1 round, and cards were "
                      "found for round 3, which it does not list", flat)
        self.assertNotIn("with a round counted a final", flat)
        # Moved by 4.465: the length's line, with nothing after its =.
        self.assertIn("\n# rounds_total =\n", self.config())

    def test_a_length_the_labels_leave_as_it_was_is_named_where_its_rounds_move(self):
        # Rounds 2 and SF move opposite ways, so the draw of 1, 2 and SF gives 2
        # either way, and the refusal said nothing of it; round 3's cards take the
        # run after past it, and --force wrote it commented all the same
        # (/tmp/t7/scratch/CFORCE/fixup, pre.out, B).
        self.unlisted({"2": "true"})
        self.assertIn(f"so rounds_total = 2 is written for {self.COMP} as your draw "
                      f"gave it, unless its cards have played past it. The file",
                      proposal_of(self))  # moved by 4.431: the proposal's header
        self.build("--discover", "--force")
        flat = " ".join(line.lstrip("# ") for line in self.config().splitlines())
        self.assertIn("The draw you declared gave the season 2 rounds, with a round "
                      "counted a final only if its label names one, and cards were "
                      "found for 3 regular rounds", flat)

    def test_one_the_club_typed_is_written_as_typed_though_played_past(self):
        # Theirs, and F3 stops the run before on it as it stops the run after.
        self.unlisted(total=2)
        self.build(expect=1)
        self.build("--discover", "--force", expect=1)
        self.assertIn("\nrounds_total = 2\n", self.config())
        self.build(expect=1)

    def test_a_second_force_writes_the_file_the_first_wrote(self):
        for finals in ({"3": "true"}, {"SF": "false"},
                       {"1": "true", "2": "true", "3": "true"}):
            with self.subTest(finals=finals):
                self.forced(finals)
                first = self.config()
                self.build("--discover", "--force")
                self.assertEqual(self.config(), first)

    def refusal(self, finals: dict[str, str], **declared) -> str:
        self.declare(finals, **declared)
        self.write_finals("SF")
        # Moved by 4.431: what the refusal said, the proposal's header says.
        return proposal_of(self)

    def test_the_refusal_names_the_length_after_the_round_it_follows(self):
        self.assertIn(f"round 3 of {self.COMP} is scored in the ladder as a regular "
                      f"round, not as the final you declared. The season's length is "
                      f"counted the same way, so rounds_total = 3 is written for "
                      f"{self.COMP} where your draw gave it 2 rounds, unless its cards "
                      f"have played past either length. The file is written fresh",
                      self.refusal({"3": "true"}))

    def test_and_the_other_way(self):
        self.assertIn(f"so rounds_total = 3 is written for {self.COMP} where your "
                      f"draw gave it 4 rounds, unless its cards have played past "
                      f"either length.", self.refusal({"SF": "false"}))

    def test_a_draw_that_gave_no_length_is_said_to_have_given_none(self):
        # No length to play past but the one written, so no "either".
        self.assertIn(f"so rounds_total = 3 is written for {self.COMP} where your "
                      f"draw gave it no length, unless its cards have played past it.",
                      self.refusal({"1": "true", "2": "true", "3": "true"}))

    def test_a_draw_whose_length_goes_with_it_is_said_to_lose_it(self):
        # Every round it lists is a final by its label, and SF was typed regular.
        path = self.cwd / "only.toml"
        path.write_text(f'[competitions.{self.COMP}]\nday = "Tuesday"\n'
                        f'[[competitions.{self.COMP}.rounds]]\nnumber = "SF"\n'
                        f'finals = false\n', encoding="utf-8")
        said = " ".join(build_mod._what_force_drops(config_mod.load(path)).split())
        self.assertIn(f"so no rounds_total is written for {self.COMP} where your draw "
                      f"gave it 1 round.", said)

    def test_two_lengths_are_each_said_with_what_can_keep_them_out(self):
        # Said once in front of the list, "unless the cards have played past it"
        # was read of a section with no rounds_total written and not of the one
        # before it (/tmp/t7/scratch/CFORCE/fixup, pre.out, D).
        path = self.cwd / "two.toml"
        path.write_text(
            '[competitions.tuesday-a]\nday = "Tuesday"\n'
            + "".join(f'[[competitions.tuesday-a.rounds]]\nnumber = "{number}"\n{typed}'
                      for number, typed in (("1", ""), ("2", "finals = true\n"),
                                            ("3", "")))
            + '[competitions.tuesday-b]\nday = "Tuesday"\n'
            '[[competitions.tuesday-b.rounds]]\nnumber = "SF"\nfinals = false\n',
            encoding="utf-8")
        said = " ".join(build_mod._what_force_drops(config_mod.load(path)).split())
        self.assertIn("The season's length is counted the same way, so rounds_total = "
                      "3 is written for tuesday-a where your draw gave it 2 rounds, "
                      "unless its cards have played past either length, and no "
                      "rounds_total is written for tuesday-b where your draw gave it "
                      "1 round. The file", said)

    def test_a_length_typed_or_of_rounds_nothing_moves_is_not_named(self):
        for finals, total in (({"3": "true"}, 3), ({"1": "false", "SF": "true"}, None)):
            with self.subTest(finals=finals, total=total):
                self.assertNotIn("The season's length", self.refusal(finals,
                                                                     total=total))


class TestTheFinalsAdviceToASeasonOfNoKnownLengthSaysWhatElseToType(FinalsDrawCase):
    """Sent to a round's ``finals``, a season nothing gives a length to is told more.

    The setting is typed in a ``[[…rounds]]`` block, and the blocks are a declared
    draw. Measured on the demo with three SF cards and no draw declared
    (/tmp/t6/scratch/m2/adv): the discovery note and F11 both said to set ``finals``
    under the blocks' heading and nothing else. Typed as they said, one block with
    ``number = "SF"`` and ``finals = false``, the run exited 1 on F3, "the declared
    draw lists 1 regular round ... but 4 regular rounds have been played", where
    the same block had exited 0 before ``finals = false`` counted for anything.
    With ``rounds_total = 4`` beside it, or every round in a block, it exits 0. A
    declared draw of the SF alone, untyped, went the same way, told nothing more
    (/tmp/t6/scratch/m2/adv3). A draw that declares a regular round has its length,
    which a round typed false grows, and a typed ``rounds_total`` is not changed by
    it, so neither is told. Rejected: reading a lone block's draw as no draw, which
    is the length rule of 4.18 asked a second way.
    """

    CAVEAT = ("The blocks are a declared draw, so give every round one or set "
              "rounds_total too: a block alone is a draw one round long.")

    def undeclared(self) -> str:
        self.write_finals("SF")
        return " ".join(self.build().out.split())

    def test_the_note_says_it(self):
        self.assertIn(f"round SF is read as finals because the round label on the "
                      f"cards names a final, and earns no ladder points. Set finals = "
                      f"true or false under [[competitions.{self.COMP}.rounds]] to "
                      f"decide it yourself. {self.CAVEAT}", self.undeclared())

    def test_the_f11_warning_says_it(self):
        self.assertIn(f"Set finals = false under [[competitions.{self.COMP}.rounds]] "
                      f"if this round is really a regular one. {self.CAVEAT}",
                      self.undeclared())

    def test_a_draw_of_finals_alone_is_told_it(self):
        # The SF typed false as it says is then the draw's one regular round.
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "SF"\n',
            encoding="utf-8")
        flat = self.undeclared()
        self.assertIn(f"because the round label names a final, and earns no ladder "
                      f"points. Set finals = true or false under [[competitions."
                      f"{self.COMP}.rounds]] to decide it yourself. {self.CAVEAT}",
                      flat)
        self.assertIn(f"if this round is really a regular one. {self.CAVEAT}", flat)

    def test_a_draw_that_declares_a_regular_round_is_not_told_it(self):
        self.declare({})
        flat = self.undeclared()
        self.assertIn("to decide it yourself.", flat)
        self.assertIn("if this round is really a regular one.", flat)
        self.assertNotIn("The blocks are a declared draw", flat)

    def test_a_grade_whose_length_is_typed_is_not_told_it(self):
        # A block then lists a round of a season whose length was already said.
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f"rounds_total = 4\n", encoding="utf-8")
        flat = self.undeclared()
        self.assertIn("to decide it yourself.", flat)
        self.assertIn("if this round is really a regular one.", flat)
        self.assertNotIn("The blocks are a declared draw", flat)

    def test_it_says_what_a_lone_block_does(self):
        self.write_finals("SF")
        head = f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
        lone = f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "SF"\nfinals = false\n'
        (self.cwd / "config.toml").write_text(head + lone, encoding="utf-8")
        flat = " ".join(self.build(expect=1).out.split())
        self.assertIn("the declared draw lists 1 regular round", flat)
        (self.cwd / "config.toml").write_text(head + "rounds_total = 4\n" + lone,
                                              encoding="utf-8")
        self.build()
        self.assertFalse(self.finals_in(self.season())["SF"])


class TestTheFinalsWarningOffersTheSettingOnlyToARoundNothingWasTypedOn(FinalsDrawCase):
    """F11 asks what the club typed after ``finals =``, as the finals note does.

    It did not ask. Its warning that a final's results are left out of the ladder
    ended ``Set finals = false under [[competitions.<id>.rounds]] if this round is
    really a regular one`` whatever was typed, and its warning that a label is
    neither a number nor a finals label was given to a round typed ``finals =
    false``. Measured on the demo season with rounds 1 to 3 declared and round 4's
    three cards relabelled (/tmp/t7/scratch/DR/probe.py): with ``SF`` typed true
    the note said ``round SF is declared as finals, and earns no ladder points.``
    and F11 still offered the setting; with ``Bonus`` typed false the run exited 0
    saying ``round label 'Bonus' is neither a number nor a finals label this
    program recognises; it is being scored as a regular round.``, word for word as
    with nothing typed, into a season.json identical to that run's, byte for byte.
    The round now carries what was typed, ``Round.finals_typed``, set once where
    the declared draw is built, and F11 and the note both ask it. Rejected: handing
    the config to validate(), a second road to what discovery already read, on
    which the note and the warning could disagree about one round.
    """

    FINALS = FinalsDrawCase.FINALS + (
        ("Bonus", "2026-09-08", "riverside-rockets", "hilltop-aces", 3.0),)
    ADVICE = "if this round is really a regular one"
    UNKNOWN = "round label 'Bonus' is neither a number nor a finals label"

    def f11(self, run) -> str:
        """Every F11 sentence the run printed and season.json carries, joined."""
        found = [w["message"] for w in self.season()["validation"]["warnings"]
                 if w["rule"] == "F11"]
        return " ".join(" ".join([run.out] + found).split())

    def test_a_final_typed_true_is_not_told_to_set_it_false(self):
        self.declare({"SF": "true"})
        self.write_finals("SF")
        said = self.f11(self.build())
        self.assertIn("round SF is a finals round, so its 1 result is left out of "
                      "the ladder", said)
        self.assertNotIn(self.ADVICE, said)

    def test_a_final_nothing_was_typed_on_is_still_told_the_setting(self):
        self.declare({})
        self.write_finals("SF")
        said = self.f11(self.build())
        self.assertIn(f"records of the players in it. Set finals = false under "
                      f"[[competitions.{self.COMP}.rounds]] {self.ADVICE}.", said)

    def test_a_round_typed_false_is_not_told_its_label_is_unrecognised(self):
        self.declare({"Bonus": "false"}, later=("Bonus",))
        self.write_finals("Bonus")
        run = self.build()
        self.assertNotIn(self.UNKNOWN, self.f11(run))
        self.assertFalse(self.finals_in(self.season())["Bonus"])

    def test_a_round_nothing_was_typed_on_is_still_told_its_label_is_unrecognised(self):
        self.declare({}, later=("Bonus",))
        self.write_finals("Bonus")
        self.assertIn(self.UNKNOWN, self.f11(self.build()))


class TestACardWhoseRoundIsASuperscriptDigitIsBuiltAsARoundWithAName(CliCase):
    """The suite's season and one more card, its round printed ``³``: built, and warned.

    Measured before (``/tmp/t6/scratch/m16/before/probe_build.py``, ``build.log``):
    the reader took ``³``, ``③`` and ``¹²`` off such a card as printed, and the build
    stopped with a ``ValueError`` traceback from ``competition.round_sort_key``,
    called by discovery's sort of the matches, before any report and with no site
    written, and exited 1, the status of an uncaught exception. Such a label is a
    round with a name, as ``Catch-up`` is: it comes after the numbered rounds, is
    scored as a regular round, and F11 warns that it is neither a number nor a
    finals label.

    Rejected: refusing the card, which drops the result it states for the way one
    field of it is written, when F11's warning already puts the label in front of
    the club; and reading it as round 3, which guesses what the club meant.

    The writer prints ASCII alone, so the card is written with a ToUnicode map that
    reads the code for ``~`` as ``³``, which is how a PDF whose font draws a
    superscript three hands a reader its text.
    """

    def write_card(self) -> None:
        cmap = cardwriter._TO_UNICODE_CMAP.replace(
            b"<20> <7E> <0020>\nendbfrange\n",
            b"<20> <7D> <0020>\nendbfrange\n1 beginbfchar\n<7E> <00B3>\nendbfchar\n")
        self.assertNotEqual(cmap, cardwriter._TO_UNICODE_CMAP)
        (home_name, home_players), (away_name, away_players) = (
            TEAMS["riverside-rockets"], TEAMS["hilltop-aces"])
        home_rows, home_on_court = squad_for("riverside-rockets", home_players)
        away_rows, away_on_court = squad_for("hilltop-aces", away_players)
        with mock.patch.object(cardwriter, "_TO_UNICODE_CMAP", cmap):
            path = cardwriter.write_card_file(
                self.cwd / "data" / "Extra" / "card.pdf", cardwriter.CardSpec(
                    date="2026-09-08", round_label="~", division="B", court="40",
                    match_id="7000001", home_name=home_name, away_name=away_name,
                    rows=rows_for(((6, 2), (6, 3), (4, 6), (6, 1)), home_on_court,
                                  away_on_court),
                    home_roster=home_rows, away_roster=away_rows))
        (card,), _ = scorecard.read(path)
        self.assertEqual(card.round, "\u00b3")

    def test_the_build_finishes_and_names_the_label_it_does_not_recognise(self):
        self.write_card()
        run = self.build()
        self.assertNotIn("Traceback", run.text)
        self.assertIn("round label '\u00b3' is neither a number nor a finals label "
                      "this program recognises; it is being scored as a regular "
                      "round.", " ".join(run.out.split()))
        doc = self.season()
        self.assertEqual([(r["number"], r["is_finals"]) for r in doc["rounds"]],
                         [("1", False), ("2", False), ("3", False),
                          ("\u00b3", False)])
        self.assertEqual([m["counts_for_ladder"] for m in doc["matches"]
                          if m["round"] == "\u00b3"], [True])


