# --- the association's sheet ---------------------------------------------------


# The fixture season's figures after round 3, as the association's sheet would
# print them if it agreed: the paper sums in test_pipeline.EXPECTED_POINTS.
AGREEING_TABLE = """
[competitions.tuesday-division-b.expected]
after_round = 3
"Hilltop Aces"       = { points = 10.7, played = 3 }
"Lakeside Spinners"  = { points = 15.8, played = 3 }
"Parkview Wanderers" = { points = 11.1, played = 3 }
"Riverside Rockets"  = { points = 19.0, played = 3 }
"""
DISAGREEING_TABLE = AGREEING_TABLE.replace("points = 10.7", "points = 10.9")


def typed_into(text: str, table: str) -> str:
    """*text* with *table* typed in, as the README says: under the heading if the file has it.

    A first run writes each competition's table heading with every line under it
    commented, and TOML takes a heading once, so a table typed below a second copy
    of it is a file that does not load.
    """
    heading = table.lstrip("\n").split("\n", 1)[0] + "\n"
    if "\n" + heading in text:
        return text.replace(heading, table.lstrip("\n"), 1)
    return text + table


class SheetCliCase(CliCase):
    """A first run, then a sheet table typed under the heading of the file it wrote."""

    COMP = "tuesday-division-b"

    def typed(self, table: str) -> None:
        config = self.cwd / "config.toml"
        if not config.exists():
            self.build()
        config.write_text(typed_into(config.read_text(encoding="utf-8"), table),
                          encoding="utf-8")

    @staticmethod
    def sheet_lines(out: str) -> list[str]:
        """The ``sheet`` field as printed: its line and the lines wrapped under it."""
        lines = out.splitlines()
        start = next((i for i, line in enumerate(lines)
                      if line.startswith("  sheet ")), None)
        if start is None:
            return []
        block = [lines[start]]
        for line in lines[start + 1:]:
            if not line.startswith(" " * (2 + build_mod._Report.LABEL)):
                break
            block.append(line)
        return block

    def sheet_said(self, out: str) -> str:
        """The ``sheet`` sentence, unwrapped."""
        return " ".join(line.strip() for line in self.sheet_lines(out))[len("sheet "):] \
            .strip()

    def state(self) -> dict[str, tuple[bytes, int]]:
        return {p.relative_to(self.cwd).as_posix(): (p.read_bytes(), p.stat().st_mtime_ns)
                for p in sorted((self.cwd / "site").rglob("*")) if p.is_file()}


class TestTheReportSaysHowMuchOfTheSheetWasCompared(SheetCliCase):
    """One sentence in the competition's block, and every team not compared named.

    "All agree" said over a team nobody checked is the false assurance this line
    exists to prevent, so a team left out is named with its reason. Printed with
    ``sentence``: the critic measured the first wording at 85 columns under the
    label, and ``field`` does not wrap. Rejected: printing it only when something
    disagrees, which leaves "no line" meaning both "all agree" and "no table".
    """

    def assertFits(self, out: str) -> None:
        over = [line for line in out.splitlines() if len(line) > build_mod.WIDTH]
        self.assertEqual(over, [], f"lines past {build_mod.WIDTH} columns")

    def said(self, table: str, *argv: str) -> str:
        self.typed(table)
        run = self.build("--check", *argv)
        self.assertFits(run.out)
        return self.sheet_said(run.out)

    def test_every_team_agreeing_is_said(self):
        self.assertEqual(self.said(AGREEING_TABLE),
                         "after round 3: 4 of 4 teams compared, all agree")

    def test_one_team_out_is_counted_and_pointed_below(self):
        self.assertEqual(self.said(DISAGREEING_TABLE),
                         "after round 3: 4 of 4 teams compared, 1 differs -- see below")

    def test_two_teams_out_are_counted_in_the_plural(self):
        self.assertEqual(
            self.said(DISAGREEING_TABLE.replace("points = 11.1", "points = 11.3")),
            "after round 3: 4 of 4 teams compared, 2 differ -- see below")

    def test_a_sheet_ahead_of_the_cards_is_said_as_that(self):
        self.assertEqual(
            self.said(AGREEING_TABLE.replace("after_round = 3", "after_round = 4")),
            "after round 4: not compared -- see sheet-ahead below")

    def declared(self, table: str):
        """``--check`` under a declared draw, with round 2's rockets v spinners
        never exported, and *table* with the spinners left out of it."""
        self.cards[2].unlink()
        fixtures = {}
        for rnd, home, away, _ in FIXTURES:
            fixtures.setdefault(rnd, []).append(
                f'["{TEAMS[home][0].title()}", "{TEAMS[away][0].title()}"]')
        (self.cwd / "config.toml").write_text(
            f'[competitions.{self.COMP}]\nday = "Tuesday"\ndivision = "B"\n'
            f'teams = [{", ".join(chr(34) + n.title() + chr(34) for n, _ in TEAMS.values())}]\n'
            + "".join(f'\n[[competitions.{self.COMP}.rounds]]\nnumber = "{n}"\n'
                      f'fixtures = [{", ".join(pairs)}]\n'
                      for n, pairs in fixtures.items())
            + table.replace('"Lakeside Spinners"  = { points = 15.8, '
                            'played = 3 }\n', ""),
            encoding="utf-8")
        run = self.build("--check")
        self.assertFits(run.out)
        return run

    def test_every_team_not_compared_is_named_with_its_reason(self):
        # One team for each reason the base tree had.
        run = self.declared(AGREEING_TABLE)
        self.assertEqual(self.sheet_said(run.out), (
            "after round 3: 2 of 4 teams compared, all agree; not compared: "
            "Riverside Rockets (card missing), Lakeside Spinners (not typed in)"))
        self.assertGreater(len(self.sheet_lines(run.out)), 1,
                           "the sentence fits one line, so this measures no wrap")

    def test_the_three_reasons_are_said_card_missing_nearly_named_not_typed_in(self):
        """A card to export, then a line to correct, then the club's own choice.

        Measured: with the first two swapped in the build's order, no test failed,
        because no sentence held a team for each. Rejected: sorting the groups by
        reason, which gives this order only by how the reasons are spelt.
        """
        run = self.declared(AGREEING_TABLE.replace('"Hilltop Aces"', '"Hilltop Acse"'))
        self.assertEqual(self.sheet_said(run.out), (
            "after round 3: 1 of 4 teams compared, all agree; not compared: "
            "Riverside Rockets (card missing), Hilltop Aces (nearly named -- see "
            "sheet-team below), Lakeside Spinners (not typed in)"))

    def test_a_team_a_line_nearly_names_is_said_as_that(self):
        # The finding under it says "Did you mean Hilltop Aces?", so the sentence
        # does not say the club never typed it in.
        self.assertEqual(
            self.said(AGREEING_TABLE.replace('"Hilltop Aces"', '"Hilltop Acse"')),
            "after round 3: 3 of 4 teams compared, all agree; not compared: "
            "Hilltop Aces (nearly named -- see sheet-team below)")

    def test_a_run_with_no_table_has_no_sheet_line(self):
        run = self.build()
        self.assertEqual(self.sheet_lines(run.out), [])
        self.assertEqual(self.sheet_lines(self.build("--check").out), [])


