class TestADisagreeingSheetIsAWarningAndTheBuildStillPasses(SheetCliCase):
    """A sheet that disagrees is a warning, in every place a warning goes.

    The build's exit status is the cards': a nightly job that failed over the
    association's arithmetic would stop publishing a right ladder. Rejected: an
    error, and a switch to make it one, which nobody asked for.
    """

    LATER = "2026-09-17T19:40:00"

    def test_the_run_passes_and_the_warning_is_in_the_report_and_the_document(self):
        self.typed(DISAGREEING_TABLE)
        run = self.build("--generated", self.LATER)
        self.assertEqual(run.code, 0)
        self.assertIn("sheet-mismatch", self.section(run.out, "2 warnings"))
        warnings = self.season()["validation"]["warnings"]
        found = [w for w in warnings if w["rule"] == "sheet-mismatch"]
        self.assertEqual(len(found), 1)
        self.assertTrue(found[0]["message"].startswith(
            "after round 3 the cards give Hilltop Aces 10.7 points"))
        self.assertEqual(found[0]["severity"], "warning")

    def test_check_says_the_same_and_writes_nothing(self):
        self.typed(DISAGREEING_TABLE)
        before = self.state()
        check = self.build("--check", "--generated", self.LATER)
        self.assertEqual(self.state(), before)
        run = self.build("--generated", self.LATER)
        self.assertIn("sheet-mismatch", self.section(check.out, "2 warnings"))
        self.assertEqual(self.section(check.out, "2 warnings"),
                         self.section(run.out, "2 warnings"))

    def test_the_one_file_page_carries_the_warning(self):
        self.typed(DISAGREEING_TABLE)
        self.build("--single-file", "--generated", self.LATER)
        # Moved by 4.430: the careers page at the root is not a fold.
        found = sorted(p for p in (self.cwd / "site").rglob("*.html")
                       if p.name != "index.html"
                       and p != self.cwd / "site" / site.CAREERS_PAGE)
        self.assertEqual(len(found), 1, found)
        page = page_parts(found[0].read_text(encoding="utf-8"))
        document = json.loads(island_json(page.scripts[0]))
        self.assertIn("sheet-mismatch",
                      [w["rule"] for w in document["validation"]["warnings"]])


class TestASheetThatAgreesChangesNoByte(SheetCliCase):
    """An agreeing sheet leaves every file, byte and date, as it was.

    Measured before this existed: both tables were ignored, and nothing was written.
    Now a first disagreement rewrites that competition's document once, and its
    ``generated`` date moves with it although no figure did: the document differs in
    more than its stamp, which is the rule the stamp has always kept. The index is
    rewritten with it, because it counts each season's warnings (measured: 1, then
    2); the plan said the document alone. Rejected: holding the stamp still over a
    changed document, which would say a page built tonight was built last week.
    """

    LATER = "2026-09-17T19:40:00"
    LATEST = "2026-09-24T19:40:00"
    FOURTH = "2026-10-01T19:40:00"

    def test_agreeing_writes_nothing_and_disagreeing_writes_once(self):
        self.build()
        built = self.state()
        self.typed(AGREEING_TABLE)
        agreeing = self.build("--generated", self.LATER)
        self.assertEqual(self.state(), built)

        self.typed_over(DISAGREEING_TABLE)
        disagreeing = self.build("--generated", self.LATEST)
        after = self.state()
        changed = sorted(name for name in after if after[name] != built.get(name))
        # The competition's document, and the picker, which counts every season's
        # warnings and dates it: one more warning is news the index has to carry.
        # Moved by 4.430: and the careers page, which carries the stamp.
        self.assertEqual(changed, ["site/careers.html", "site/index.html",
                                   "site/picker-data.js",
                                   f"site/{self.COMP}/season-data.js",
                                   f"site/{self.COMP}/season.json"])
        self.assertEqual(self.season()["meta"]["generated"], self.LATEST)

        again = self.build("--generated", self.FOURTH)
        self.assertEqual(self.state(), after)
        self.assertEqual(self.season()["meta"]["generated"], self.LATEST)
        for run in (agreeing, disagreeing, again):
            self.assertNotIn("== since the last build", run.out)

    def typed_over(self, table: str) -> None:
        config = self.cwd / "config.toml"
        text = config.read_text(encoding="utf-8")
        self.assertIn(AGREEING_TABLE, text)
        config.write_text(text.replace(AGREEING_TABLE, table), encoding="utf-8")


